insert into public.learning_categories (id, name, name_vi, description, sort_order) values
  ('vocabulary', 'Vocabulary', 'Từ vựng', 'Learn words you can use every day.', 0),
  ('grammar', 'Grammar', 'Ngữ pháp', 'Build sentences that sound natural.', 1),
  ('listening', 'Listening', 'Nghe', 'Train your ear with short clips.', 2),
  ('writing', 'Writing', 'Viết', 'Put words in order and write clearly.', 3),
  ('speaking', 'Speaking', 'Nói', 'Listen, repeat and record yourself.', 4)
insert into public.lessons (id, language, category_id, level, topic, title, title_vi, objectives, sort_order) values
  ('vocab-a1-daily-routine', 'en', 'vocabulary', 'A1', 'daily routine', 'Our Little Days: Daily Routine Words', 'Một ngày của hai đứa: từ vựng về sinh hoạt hằng ngày', array['Name everyday actions from morning to night', 'Talk about when you usually do things', 'Share your daily schedule with your partner']::text[], 0),
  ('vocab-a1-food-cooking', 'en', 'vocabulary', 'A1', 'food & cooking', 'Cooking for Two: Food & Kitchen Words', 'Nấu cho hai người: từ vựng về đồ ăn và nấu nướng', array['Describe how food tastes', 'Name simple cooking actions', 'Talk about meals with your partner']::text[], 1),
  ('vocab-a1-home-furniture', 'en', 'vocabulary', 'A1', 'home & furniture', 'Home Sweet Home: Rooms & Furniture', 'Tổ ấm: từ vựng về phòng ốc và đồ nội thất', array['Name rooms in a house', 'Name common furniture and household things', 'Describe your room on a video call']::text[], 2),
  ('vocab-a2-communication', 'en', 'vocabulary', 'A2', 'communication: calls & messages', 'Always Connected: Calls & Messages', 'Luôn kết nối: từ vựng về gọi điện và nhắn tin', array['Talk about phone calls, video calls, and messages', 'Explain small tech problems like a weak signal', 'Keep in touch with your partner in English']::text[], 3),
  ('vocab-a2-feelings-emotions', 'en', 'vocabulary', 'A2', 'feelings & emotions', 'Heart to Heart: Feelings & Emotions', 'Thật lòng với nhau: từ vựng về cảm xúc', array['Name common feelings in English', 'Choose the right feeling word for a situation', 'Tell your partner how you really feel']::text[], 4),
  ('vocab-a2-weather-nature', 'en', 'vocabulary', 'A2', 'weather & nature', 'Under the Same Sky: Weather & Nature', 'Chung một bầu trời: từ vựng về thời tiết và thiên nhiên', array['Describe today''s weather', 'Name simple things in nature and the sky', 'Compare the weather where each of you lives']::text[], 5),
  ('vocab-b1-love-relationships', 'en', 'vocabulary', 'B1', 'love & relationships', 'Close at Heart: Love & Relationships', 'Xa mặt nhưng gần lòng: Tình yêu và các mối quan hệ', array['Talk about trust, support and commitment', 'Describe a loving partner with natural adjectives', 'Talk about the ups and downs of a long-distance relationship']::text[], 6),
  ('vocab-b1-travel-places', 'en', 'vocabulary', 'B1', 'travel & places', 'Our Next Trip Together: Travel & Places', 'Chuyến đi tiếp theo của tụi mình: Du lịch và địa điểm', array['Talk about trip plans with words like destination and itinerary', 'Describe places, views and crowds', 'Understand common airport and booking vocabulary']::text[], 7),
  ('vocab-b2-plans-future', 'en', 'vocabulary', 'B2', 'plans & the future', 'One Day, Same City: Plans & the Future', 'Một ngày, chung một thành phố: Kế hoạch và tương lai', array['Use phrasal verbs about plans: look forward to, settle down, figure out', 'Talk about long-term goals and uncertainty', 'Discuss changing and delaying plans']::text[], 8),
  ('vocab-b2-study-work', 'en', 'vocabulary', 'B2', 'study & work', 'Busy Days, Big Goals: Study & Work', 'Ngày bận rộn, mục tiêu lớn: Học tập và công việc', array['Talk about deadlines, workload and feedback', 'Describe career steps like internships and promotions', 'Use work verbs like collaborate, submit and procrastinate']::text[], 9),
  ('grammar-a1-articles', 'en', 'grammar', 'A1', 'articles a / an / the / zero article', 'A, An, The… or Nothing?', 'A, an, the… hay không dùng mạo từ?', array['Choose a or an by the first sound of the next word', 'Use the for things already known or unique', 'Know when to use no article']::text[], 10),
  ('grammar-a1-be-present-simple', 'en', 'grammar', 'A1', 'to be & present simple', 'Every Day With You: "to be" & the Present Simple', 'Mỗi ngày bên nhau: động từ "to be" và thì hiện tại đơn', array['Use am / is / are correctly', 'Add -s / -es to verbs after he, she, it', 'Make questions and negatives with do / does']::text[], 11),
  ('grammar-a2-past-simple', 'en', 'grammar', 'A2', 'past simple', 'Yesterday With You: the Past Simple', 'Hôm qua của chúng mình: thì quá khứ đơn', array['Form regular (-ed) and common irregular past verbs', 'Use did + base verb in questions and negatives', 'Use was / were for the past of "to be"']::text[], 12),
  ('grammar-a2-prepositions-in-on-at', 'en', 'grammar', 'A2', 'prepositions of time and place (in / on / at)', 'Meet Me There: In, On, At', 'Hẹn gặp ở đó: giới từ in, on, at', array['Use in / on / at with times, days, months and years', 'Use in / on / at for places', 'Remember common fixed phrases like at night']::text[], 13),
  ('grammar-b1-conditionals', 'en', 'grammar', 'B1', 'first and second conditionals', 'If You Were Here: First & Second Conditionals', 'Nếu anh ở đây: câu điều kiện loại 1 và loại 2', array['Use the first conditional for real, possible futures', 'Use the second conditional for imaginary situations', 'Use "If I were…" to give advice and talk about wishes']::text[], 14),
  ('grammar-b1-present-perfect-past-simple', 'en', 'grammar', 'B1', 'present perfect vs past simple', 'Since the Day We Met: Present Perfect vs Past Simple', 'Từ ngày mình gặp nhau: hiện tại hoàn thành và quá khứ đơn', array['Use the present perfect for life experience and situations that continue to now', 'Use for / since / ago correctly', 'Use the past simple with finished time expressions']::text[], 15),
  ('listen-a1-calls-daily-life', 'en', 'listening', 'A1', 'video calls & daily life', 'Hello, Can You Hear Me? First Listening', 'Alo, nghe rõ không? Bài nghe đầu tiên', array['Hear the difference between similar sounds: live / leave, ship / sheep', 'Notice final sounds like the t in cat', 'Catch simple times and places in one sentence']::text[], 16),
  ('listen-a2-planning-to-meet', 'en', 'listening', 'A2', 'planning to meet', 'See You Soon! Planning to Meet', 'Sắp gặp rồi! Lên kế hoạch gặp nhau', array['Hear the difference between thirteen / thirty and fifteen / fifty', 'Understand where and when people plan to meet', 'Hear the difference between walk and work']::text[], 17),
  ('listen-b1-calls-daily-life', 'en', 'listening', 'B1', 'video calls & daily life', 'Our Evening Calls: Daily Life on Video', 'Những cuộc gọi buổi tối: Cuộc sống hằng ngày qua video', array['Understand reasons and problems during a video call', 'Follow the order of activities in a daily routine', 'Hear small differences like left / lost and thirty / thirteen']::text[], 18),
  ('listen-b1-travel', 'en', 'listening', 'B1', 'travel', 'On the Way to You: Travel Listening', 'Trên đường đến bên em: Nghe về du lịch', array['Understand announcements and requests while travelling', 'Hear the difference between ship / sheep and fifteen / fifty', 'Catch the main question in a hotel conversation']::text[], 19),
  ('writing-a1-sentence-puzzle', 'en', 'writing', 'A1', 'basic word order', 'Sentence Puzzle: First Words', 'Ghép câu: những câu đầu tiên', array['Put the subject before the verb', 'Build simple statements and questions', 'Place time words at the end of the sentence']::text[], 20),
  ('writing-a2-sentence-puzzle', 'en', 'writing', 'A2', 'past, future and question word order', 'Sentence Puzzle: Our Days Apart', 'Ghép câu: những ngày xa nhau', array['Order words in past simple statements and questions', 'Place adverbs of frequency correctly', 'Build sentences with "going to" and polite requests']::text[], 21),
  ('writing-b1-sentence-puzzle', 'en', 'writing', 'B1', 'perfect tenses, conditionals and complex sentences', 'Sentence Puzzle: Closer Than It Seems', 'Ghép câu: gần hơn mình nghĩ', array['Order words in present perfect sentences', 'Build conditional and embedded-question sentences', 'Join ideas with relative clauses and "although"']::text[], 22),
  ('zh-vocab-hsk1-greetings', 'zh', 'vocabulary', 'HSK1', 'greetings and people', 'Hello, Friend!', 'Xin chào, bạn thân mến!', array['Say thank you, sorry and goodbye in Chinese', 'Name the people around you: friends, classmates, teachers and family', 'Ask someone''s name and say you''re happy to meet them']::text[], 23),
  ('zh-vocab-hsk1-numbers-time', 'zh', 'vocabulary', 'HSK1', 'numbers, time and daily life', 'What Time Is It There?', 'Chỗ em bây giờ mấy giờ rồi?', array['Tell the time and say your age in Chinese', 'Talk about today, tomorrow and the days of the week', 'Name simple daily actions like drinking and sleeping']::text[], 24),
  ('zh-vocab-hsk2-feelings', 'zh', 'vocabulary', 'HSK2', 'feelings and relationships', 'Missing You, Loving You', 'Nhớ em, thương em', array['Express love, missing someone and happiness', 'Give wishes for birthdays and the future', 'Talk about waiting for, telling and giving gifts to your partner']::text[], 25),
  ('zh-vocab-hsk2-food-shopping', 'zh', 'vocabulary', 'HSK2', 'food and shopping', 'Dinner and a Little Shopping', 'Ăn tối và đi mua sắm', array['Name common foods like rice, eggs, fruit and dishes', 'Talk about prices: cheap, expensive and how many kuai', 'Say what a shop sells and what tastes good']::text[], 26),
  ('zh-vocab-hsk3-study-work', 'zh', 'vocabulary', 'HSK3', 'study, work and plans', 'Working Toward Our Future', 'Cùng cố gắng cho tương lai', array['Talk about exams, homework, practice and review', 'Describe going to work and your company', 'Share your plans and how hard you''re working']::text[], 27),
  ('zh-vocab-hsk3-travel', 'zh', 'vocabulary', 'HSK3', 'travel and places', 'Our Next Trip Together', 'Chuyến đi tiếp theo của hai đứa', array['Name travel essentials: passport, ticket, map and hotel', 'Talk about places in a city: airport, park, nearby spots', 'Say how far one place is from another with 离']::text[], 28),
  ('zh-grammar-hsk1-basics', 'zh', 'grammar', 'HSK1', '是, 吗, 不/没, basic word order', 'First Sentences Together: 是, 吗, 不 & 没', 'Những câu đầu tiên bên nhau: 是, 吗, 不 và 没', array['Use 是 with nouns, but not with adjectives', 'Make yes/no questions with 吗', 'Choose 不 or 没 to make negatives', 'Put time and place words before the verb']::text[], 29),
  ('zh-grammar-hsk2-aspect-compare', 'zh', 'grammar', 'HSK2', '了, 过, 在, 比', 'Our Story So Far: 了, 过, 在 & 比', 'Chuyện của tụi mình: 了, 过, 在 và 比', array['Use 了 for completed actions', 'Use 过 for past experiences', 'Use 在 + verb for actions in progress', 'Compare two things with 比']::text[], 30),
  ('zh-grammar-hsk3-ba-complements', 'zh', 'grammar', 'HSK3', '把, resultative complements, 越来越, 因为…所以, 虽然…但是', 'Growing Closer: 把, Results & Linking Ideas', 'Ngày càng gần nhau: câu chữ 把, bổ ngữ kết quả và liên từ', array['Build 把 sentences: 把 + object + verb + result', 'Use resultative complements like 听懂 and 看完', 'Describe change with 越来越', 'Link ideas with 因为…所以… and 虽然…但是…']::text[], 31),
  ('zh-listen-hsk1-daily-life', 'zh', 'listening', 'HSK1', 'numbers, shopping & plans', 'Nǐ hǎo! First Chinese Listening', 'Nǐ hǎo! Bài nghe tiếng Trung đầu tiên', array['Hear the difference between 四 (sì) and 十 (shí)', 'Tell 买 (mǎi) from 卖 (mài) by tone', 'Catch places, times and likes in one sentence']::text[], 32),
  ('zh-listen-hsk2-plans-together', 'zh', 'listening', 'HSK2', 'shopping, travel & plans', 'Making Plans: Listening in Two Sentences', 'Lên kế hoạch: nghe hiểu câu dài hơn', array['Hear tone pairs like 买/卖 inside longer sentences', 'Catch dates, transport and locations', 'Understand the reason behind a change of plan']::text[], 33),
  ('zh-writing-hsk1-sentence-puzzle', 'zh', 'writing', 'HSK1', 'basic word order', 'Sentence Puzzle: First Chinese Sentences', 'Ghép câu: những câu tiếng Trung đầu tiên', array['Build Subject + Verb + Object sentences', 'Put time and place words before the verb', 'Make questions with 吗 and question words']::text[], 34),
  ('zh-writing-hsk2-sentence-puzzle', 'zh', 'writing', 'HSK2', '了, 过, 在, 比 & complements', 'Sentence Puzzle: Telling Our Story', 'Ghép câu: kể chuyện của tụi mình', array['Place 了, 过 and 在 correctly around the verb', 'Build comparisons with 比', 'Use 给, 都 and degree complements with 得']::text[], 35)
insert into public.lesson_questions (id, lesson_id, position, kind, level, objective, prompt, prompt_vi, options, tokens, audio_text, hint, hint_vi, word_term, answers, explanation, explanation_vi, word) values
  ('vocab-a1-routine-01', 'vocab-a1-daily-routine', 1, 'multiple_choice', 'A1', 'Recognize the meaning of ''wake up''', 'My alarm rings and I ___ at 6 a.m.', 'Chuông báo thức reo và anh ___ lúc 6 giờ sáng.', '["wake up","fall asleep","go to bed","stay asleep"]'::jsonb, null, null, null, null, 'wake up', '["wake up"]'::jsonb, '"Wake up" means to stop sleeping. When the alarm rings, you wake up — you don''t fall asleep or go to bed.', '"Wake up" là thức dậy. Chuông báo thức reo thì mình thức dậy, chứ không phải ngủ thiếp đi (fall asleep) hay đi ngủ (go to bed).', '{"term":"wake up","ipa":"/weɪk ʌp/","part_of_speech":"phrase","meaning_vi":"thức dậy","example":"I wake up early so I can say good morning to you before your day starts.","example_vi":"Anh dậy sớm để kịp chào buổi sáng em trước khi ngày của em bắt đầu."}'::jsonb),
  ('vocab-a1-routine-02', 'vocab-a1-daily-routine', 2, 'multiple_choice', 'A1', 'Recognize the meaning of ''brush''', 'What does ''brush'' mean in "brush your teeth"?', 'Từ ''brush'' trong "brush your teeth" có nghĩa là gì?', '["to clean something with a tool that has many small hairs","to wash your whole body with water","to cut something into small pieces","to dry something with a towel"]'::jsonb, null, null, null, null, 'brush', '["to clean something with a tool that has many small hairs"]'::jsonb, 'To brush is to clean or tidy something with a brush. We brush our teeth and brush our hair every day.', '"Brush" là chải, đánh (bằng bàn chải). Mình nói brush your teeth (đánh răng) và brush your hair (chải tóc).', '{"term":"brush","ipa":"/brʌʃ/","part_of_speech":"verb","meaning_vi":"chải, đánh (răng)","example":"I brush my teeth after breakfast and before bed.","example_vi":"Em đánh răng sau bữa sáng và trước khi đi ngủ."}'::jsonb),
  ('vocab-a1-routine-03', 'vocab-a1-daily-routine', 3, 'multiple_choice', 'A1', 'Recognize the meaning of ''breakfast''', '''breakfast'' nghĩa là gì?', null, '["bữa sáng","bữa trưa","bữa tối","bữa ăn nhẹ"]'::jsonb, null, null, null, null, 'breakfast', '["bữa sáng"]'::jsonb, 'Breakfast is the first meal of the day, eaten in the morning. Lunch is at midday and dinner is in the evening.', 'Breakfast là bữa sáng — bữa ăn đầu tiên trong ngày. Bữa trưa là lunch, bữa tối là dinner.', '{"term":"breakfast","ipa":"/ˈbrɛkfəst/","part_of_speech":"noun","meaning_vi":"bữa sáng","example":"What did you have for breakfast today? I had bánh mì.","example_vi":"Hôm nay em ăn sáng món gì? Anh ăn bánh mì."}'::jsonb),
  ('vocab-a1-routine-04', 'vocab-a1-daily-routine', 4, 'multiple_choice', 'A1', 'Recognize the meaning of ''shower''', 'I take a quick ___ before work, so my hair is still wet.', 'Em ___ nhanh trước khi đi làm nên tóc vẫn còn ướt.', '["shower","nap","walk","breakfast"]'::jsonb, null, null, null, null, 'shower', '["shower"]'::jsonb, 'A shower is when you wash your body under running water. Wet hair is the clue — a nap or a walk won''t make your hair wet.', '"Shower" là tắm vòi sen. Manh mối là tóc còn ướt — ngủ trưa (nap) hay đi dạo (walk) thì không làm ướt tóc. Cụm hay dùng: take a shower.', '{"term":"shower","ipa":"/ˈʃaʊər/","part_of_speech":"noun","meaning_vi":"sự tắm vòi sen; vòi sen","example":"I''ll take a shower and call you in ten minutes.","example_vi":"Anh đi tắm rồi mười phút nữa gọi em nhé."}'::jsonb),
  ('vocab-a1-routine-05', 'vocab-a1-daily-routine', 5, 'multiple_choice', 'A1', 'Recognize the meaning of ''nap''', 'What does ''nap'' mean?', 'Từ ''nap'' có nghĩa là gì?', '["a short sleep during the day","a long walk in the morning","a small meal in the afternoon","a break to drink coffee"]'::jsonb, null, null, null, null, 'nap', '["a short sleep during the day"]'::jsonb, 'A nap is a short sleep, usually after lunch or in the afternoon. We often say "take a nap".', '"Nap" là giấc ngủ ngắn ban ngày, giống ngủ trưa ở Việt Nam. Cụm hay dùng: take a nap.', '{"term":"nap","ipa":"/næp/","part_of_speech":"noun","meaning_vi":"giấc ngủ ngắn, ngủ trưa","example":"I took a nap after lunch, so I''m not sleepy tonight.","example_vi":"Em ngủ trưa rồi nên tối nay chưa buồn ngủ."}'::jsonb),
  ('vocab-a1-routine-06', 'vocab-a1-daily-routine', 6, 'multiple_choice', 'A1', 'Recognize the meaning of ''alarm''', 'I set my ___ for 5 a.m. so I can call you before you go to sleep.', 'Anh đặt ___ lúc 5 giờ sáng để kịp gọi em trước khi em đi ngủ.', '["alarm","shoes","breakfast","shower"]'::jsonb, null, null, null, null, 'alarm', '["alarm"]'::jsonb, 'An alarm is a clock or phone sound that wakes you up at a set time. We say "set an alarm" for a time.', '"Alarm" là chuông báo thức. Mình nói set an alarm (đặt báo thức) cho một giờ nhất định.', '{"term":"alarm","ipa":"/əˈlɑrm/","part_of_speech":"noun","meaning_vi":"chuông báo thức","example":"My alarm didn''t ring, so I was late for work.","example_vi":"Báo thức không reo nên em đi làm trễ."}'::jsonb),
  ('vocab-a1-routine-07', 'vocab-a1-daily-routine', 7, 'multiple_choice', 'A1', 'Recognize the meaning of ''get dressed''', 'What does ''get dressed'' mean?', 'Cụm ''get dressed'' có nghĩa là gì?', '["to put on your clothes","to take a bath","to buy new clothes","to wash your clothes"]'::jsonb, null, null, null, null, 'get dressed', '["to put on your clothes"]'::jsonb, 'To get dressed means to put your clothes on, usually after you wake up or take a shower.', '"Get dressed" là mặc quần áo vào, thường làm sau khi thức dậy hoặc tắm xong. Không phải mua hay giặt quần áo.', '{"term":"get dressed","ipa":"/ɡɛt drɛst/","part_of_speech":"phrase","meaning_vi":"mặc quần áo","example":"Give me five minutes to get dressed, then we can video call.","example_vi":"Cho em năm phút thay đồ rồi mình gọi video nha."}'::jsonb),
  ('vocab-a1-routine-08', 'vocab-a1-daily-routine', 8, 'multiple_choice', 'A1', 'Recognize the meaning of ''usually''', 'I ___ drink coffee in the morning, but today I had tea.', 'Anh ___ uống cà phê vào buổi sáng, nhưng hôm nay anh uống trà.', '["usually","never","yesterday","tomorrow"]'::jsonb, null, null, null, null, 'usually', '["usually"]'::jsonb, '"Usually" means most of the time. The word "but today" shows that today is different from the normal habit.', '"Usually" là thường thường, hầu như lúc nào cũng vậy. Chữ "but today" cho thấy hôm nay khác với thói quen thường ngày. "Never" (không bao giờ) thì không hợp nghĩa.', '{"term":"usually","ipa":"/ˈjuʒuəli/","part_of_speech":"adverb","meaning_vi":"thường thường, thường xuyên","example":"We usually talk on the phone after dinner.","example_vi":"Tụi mình thường gọi điện cho nhau sau bữa tối."}'::jsonb),
  ('vocab-a1-routine-09', 'vocab-a1-daily-routine', 9, 'multiple_choice', 'A1', 'Recognize the meaning of ''early''', 'You go to bed so ___! It''s only 9 p.m.', 'Em đi ngủ ___ quá! Mới có 9 giờ tối thôi mà.', '["early","late","slowly","loud"]'::jsonb, null, null, null, null, 'early', '["early"]'::jsonb, '"Early" means before the usual time. "It''s only 9 p.m." tells us the time is earlier than normal, not late.', '"Early" là sớm, trước giờ bình thường. "It''s only 9 p.m." cho thấy giờ còn sớm, nên không thể là "late" (muộn).', '{"term":"early","ipa":"/ˈɝli/","part_of_speech":"adverb","meaning_vi":"sớm","example":"I have to get up early tomorrow for my flight.","example_vi":"Mai anh phải dậy sớm để bay."}'::jsonb),
  ('vocab-a1-routine-10', 'vocab-a1-daily-routine', 10, 'multiple_choice', 'A1', 'Recognize the meaning of ''bedtime''', '''bedtime'' nghĩa là gì?', null, '["giờ đi ngủ","phòng ngủ","giờ thức dậy","giờ ăn trưa"]'::jsonb, null, null, null, null, 'bedtime', '["giờ đi ngủ"]'::jsonb, 'Bedtime is the time when you usually go to bed. Don''t mix it up with "bedroom", the room where you sleep.', '"Bedtime" là giờ đi ngủ. Đừng nhầm với "bedroom" là phòng ngủ nhé.', '{"term":"bedtime","ipa":"/ˈbɛdtaɪm/","part_of_speech":"noun","meaning_vi":"giờ đi ngủ","example":"It''s your bedtime soon — sweet dreams!","example_vi":"Sắp tới giờ em đi ngủ rồi — chúc em ngủ ngon!"}'::jsonb),
  ('vocab-a1-food-01', 'vocab-a1-food-cooking', 1, 'multiple_choice', 'A1', 'Recognize the meaning of ''cook''', 'When you visit, I''ll ___ dinner for you — my mom taught me her recipe.', 'Khi em sang chơi, anh sẽ ___ bữa tối cho em — mẹ anh đã dạy anh công thức của mẹ.', '["cook","sleep","drink","wash"]'::jsonb, null, null, null, null, 'cook', '["cook"]'::jsonb, 'To cook is to make food ready to eat by heating it. A recipe tells you how to cook a dish.', '"Cook" là nấu ăn. Manh mối là "recipe" (công thức nấu ăn) — công thức thì dùng để nấu.', '{"term":"cook","ipa":"/kʊk/","part_of_speech":"verb","meaning_vi":"nấu ăn","example":"Let''s cook the same dish tonight and eat together on video.","example_vi":"Tối nay mình nấu cùng một món rồi ăn chung qua video nha."}'::jsonb),
  ('vocab-a1-food-02', 'vocab-a1-food-cooking', 2, 'multiple_choice', 'A1', 'Recognize the meaning of ''delicious''', 'What does ''delicious'' mean?', 'Từ ''delicious'' có nghĩa là gì?', '["having a very good taste","very hot in temperature","not cooked yet","having too much salt"]'::jsonb, null, null, null, null, 'delicious', '["having a very good taste"]'::jsonb, '"Delicious" means very tasty. It''s a strong, happy word — perfect for praising someone''s cooking.', '"Delicious" là rất ngon. Đây là từ khen mạnh, rất hợp để khen người yêu nấu ăn.', '{"term":"delicious","ipa":"/dɪˈlɪʃəs/","part_of_speech":"adjective","meaning_vi":"ngon, rất ngon","example":"Your bún chả looks delicious! I wish I could try it.","example_vi":"Bún chả của em nhìn ngon quá! Ước gì anh được ăn thử."}'::jsonb),
  ('vocab-a1-food-03', 'vocab-a1-food-cooking', 3, 'multiple_choice', 'A1', 'Recognize the meaning of ''spicy''', 'This soup has a lot of chili in it. It''s very ___.', 'Món canh này cho nhiều ớt lắm. Nó rất ___.', '["spicy","sweet","frozen","plain"]'::jsonb, null, null, null, null, 'spicy', '["spicy"]'::jsonb, 'Food with a lot of chili is spicy — it gives a hot, burning feeling in your mouth.', 'Đồ ăn nhiều ớt thì "spicy" — cay. "Sweet" là ngọt, "plain" là nhạt, không gia vị.', '{"term":"spicy","ipa":"/ˈspaɪsi/","part_of_speech":"adjective","meaning_vi":"cay","example":"I can''t eat spicy food, but you love it!","example_vi":"Anh không ăn cay được, còn em thì mê đồ cay!"}'::jsonb),
  ('vocab-a1-food-04', 'vocab-a1-food-cooking', 4, 'multiple_choice', 'A1', 'Recognize the meaning of ''bowl''', 'What does ''bowl'' mean?', 'Từ ''bowl'' có nghĩa là gì?', '["a round, deep dish for soup or rice","a flat plate for cutting bread","a tool for picking up noodles","a cup with a handle for coffee"]'::jsonb, null, null, null, null, 'bowl', '["a round, deep dish for soup or rice"]'::jsonb, 'A bowl is a round, deep dish. We eat phở, soup, and rice from a bowl.', '"Bowl" là cái bát (cái chén) — đồ đựng tròn, sâu. Ăn phở, canh, cơm đều dùng bowl.', '{"term":"bowl","ipa":"/boʊl/","part_of_speech":"noun","meaning_vi":"cái bát, cái tô, cái chén","example":"I just ate a big bowl of phở and I''m so full.","example_vi":"Em vừa ăn một tô phở to, no căng luôn."}'::jsonb),
  ('vocab-a1-food-05', 'vocab-a1-food-cooking', 5, 'multiple_choice', 'A1', 'Recognize the meaning of ''recipe''', 'What does ''recipe'' mean?', 'Từ ''recipe'' có nghĩa là gì?', '["instructions that tell you how to cook a dish","a list of prices in a restaurant","a bill you pay after eating","a person who cooks in a restaurant"]'::jsonb, null, null, null, null, 'recipe', '["instructions that tell you how to cook a dish"]'::jsonb, 'A recipe lists the ingredients and steps for making a dish. Careful: "receipt" (the paper you get after paying) is a different word.', '"Recipe" là công thức nấu ăn. Cẩn thận đừng nhầm với "receipt" (hóa đơn, biên lai) nhé.', '{"term":"recipe","ipa":"/ˈrɛsəpi/","part_of_speech":"noun","meaning_vi":"công thức nấu ăn","example":"Can you send me your grandma''s recipe for caramel pork?","example_vi":"Em gửi anh công thức thịt kho của bà em được không?"}'::jsonb),
  ('vocab-a1-food-06', 'vocab-a1-food-cooking', 6, 'multiple_choice', 'A1', 'Recognize the meaning of ''boil''', 'First, ___ the water, then add the noodles.', 'Đầu tiên, ___ nước, rồi cho mì vào.', '["boil","freeze","cut","peel"]'::jsonb, null, null, null, null, 'boil', '["boil"]'::jsonb, 'To boil is to heat water (or food in water) until it bubbles. You can''t cut or peel water, and frozen water won''t cook noodles.', '"Boil" là đun sôi, luộc. Nước thì không thể cắt (cut) hay gọt (peel), còn làm đông (freeze) thì không nấu mì được.', '{"term":"boil","ipa":"/bɔɪl/","part_of_speech":"verb","meaning_vi":"đun sôi, luộc","example":"Boil the eggs for about eight minutes.","example_vi":"Luộc trứng khoảng tám phút."}'::jsonb),
  ('vocab-a1-food-07', 'vocab-a1-food-cooking', 7, 'multiple_choice', 'A1', 'Recognize the meaning of ''fry''', '''fry'' nghĩa là gì?', null, '["chiên, rán","luộc","nướng","hấp"]'::jsonb, null, null, null, null, 'fry', '["chiên, rán"]'::jsonb, 'To fry is to cook food in hot oil, like fried rice or spring rolls. Boil = luộc, grill = nướng, steam = hấp.', '"Fry" là chiên, rán trong dầu nóng, như cơm chiên hay chả giò. Luộc là boil, nướng là grill, hấp là steam.', '{"term":"fry","ipa":"/fraɪ/","part_of_speech":"verb","meaning_vi":"chiên, rán","example":"My mom is frying spring rolls — the whole house smells amazing.","example_vi":"Mẹ em đang chiên chả giò — cả nhà thơm phức."}'::jsonb),
  ('vocab-a1-food-08', 'vocab-a1-food-cooking', 8, 'multiple_choice', 'A1', 'Recognize the meaning of ''hungry''', 'I didn''t eat lunch, so I''m really ___ now.', 'Anh chưa ăn trưa nên giờ anh ___ lắm.', '["hungry","full","thirsty","sleepy"]'::jsonb, null, null, null, null, 'hungry', '["hungry"]'::jsonb, 'When you need food, you are hungry. Skipping lunch makes you hungry, not full. "Thirsty" is about needing a drink.', '"Hungry" là đói. Bỏ bữa trưa thì đói chứ không no (full). "Thirsty" là khát nước.', '{"term":"hungry","ipa":"/ˈhʌŋɡri/","part_of_speech":"adjective","meaning_vi":"đói","example":"Are you hungry? Let''s order something and eat together on video.","example_vi":"Em đói chưa? Mình đặt đồ ăn rồi ăn chung qua video nha."}'::jsonb),
  ('vocab-a1-food-09', 'vocab-a1-food-cooking', 9, 'multiple_choice', 'A1', 'Recognize the meaning of ''vegetable''', 'What does ''vegetable'' mean?', 'Từ ''vegetable'' có nghĩa là gì?', '["a plant or part of a plant that we eat, like carrots","a sweet food eaten after dinner","a type of meat from chickens","a drink made from fruit"]'::jsonb, null, null, null, null, 'vegetable', '["a plant or part of a plant that we eat, like carrots"]'::jsonb, 'Vegetables are plants we eat, such as carrots, cabbage, and morning glory. Note the short pronunciation: VEJ-tuh-bul.', '"Vegetable" là rau củ, như cà rốt, bắp cải, rau muống. Lưu ý phát âm chỉ có ba âm tiết: /ˈvɛdʒtəbəl/.', '{"term":"vegetable","ipa":"/ˈvɛdʒtəbəl/","part_of_speech":"noun","meaning_vi":"rau củ","example":"You should eat more vegetables, not just instant noodles!","example_vi":"Anh phải ăn thêm rau đi, đừng chỉ ăn mì gói!"}'::jsonb),
  ('vocab-a1-food-10', 'vocab-a1-food-cooking', 10, 'multiple_choice', 'A1', 'Recognize the meaning of ''snack''', 'I''m not very hungry — just a small ___ is enough.', 'Em không đói lắm — chỉ cần một ___ nhỏ là đủ.', '["snack","feast","kitchen","recipe"]'::jsonb, null, null, null, null, 'snack', '["snack"]'::jsonb, 'A snack is a small amount of food eaten between meals. A feast is a very big meal, so it doesn''t fit "not very hungry".', '"Snack" là đồ ăn vặt, bữa ăn nhẹ. "Feast" là bữa tiệc lớn nên không hợp với "không đói lắm".', '{"term":"snack","ipa":"/snæk/","part_of_speech":"noun","meaning_vi":"đồ ăn vặt, bữa ăn nhẹ","example":"I''m sending you a box of your favorite Vietnamese snacks.","example_vi":"Anh gửi cho em một thùng đồ ăn vặt Việt Nam mà em thích."}'::jsonb),
  ('vocab-a1-home-01', 'vocab-a1-home-furniture', 1, 'multiple_choice', 'A1', 'Recognize the meaning of ''sofa''', 'What does ''sofa'' mean?', 'Từ ''sofa'' có nghĩa là gì?', '["a long, soft seat for two or more people","a small bed for a baby","a small table next to a bed","a cupboard for clothes"]'::jsonb, null, null, null, null, 'sofa', '["a long, soft seat for two or more people"]'::jsonb, 'A sofa (also called a couch) is a long, soft seat in the living room where several people can sit together.', '"Sofa" (hay "couch") là ghế dài, êm, ngồi được nhiều người, thường đặt ở phòng khách.', '{"term":"sofa","ipa":"/ˈsoʊfə/","part_of_speech":"noun","meaning_vi":"ghế sofa, ghế dài","example":"One day we''ll watch movies together on the same sofa.","example_vi":"Một ngày nào đó tụi mình sẽ cùng xem phim trên một chiếc sofa."}'::jsonb),
  ('vocab-a1-home-02', 'vocab-a1-home-furniture', 2, 'multiple_choice', 'A1', 'Recognize the meaning of ''kitchen''', 'Mom is making dinner in the ___.', 'Mẹ đang nấu bữa tối trong ___.', '["kitchen","bedroom","garage","bathroom"]'::jsonb, null, null, null, null, 'kitchen', '["kitchen"]'::jsonb, 'The kitchen is the room where we cook food. That''s where Mom makes dinner.', '"Kitchen" là nhà bếp — phòng để nấu ăn.', '{"term":"kitchen","ipa":"/ˈkɪtʃən/","part_of_speech":"noun","meaning_vi":"nhà bếp","example":"Show me your kitchen — what are you cooking?","example_vi":"Cho anh xem bếp của em đi — em đang nấu gì đó?"}'::jsonb),
  ('vocab-a1-home-03', 'vocab-a1-home-furniture', 3, 'multiple_choice', 'A1', 'Recognize the meaning of ''bedroom''', '''bedroom'' nghĩa là gì?', null, '["phòng ngủ","phòng khách","phòng tắm","nhà bếp"]'::jsonb, null, null, null, null, 'bedroom', '["phòng ngủ"]'::jsonb, 'A bedroom is the room where you sleep. The living room is "phòng khách" and the bathroom is "phòng tắm".', '"Bedroom" là phòng ngủ. Phòng khách là living room, phòng tắm là bathroom, nhà bếp là kitchen.', '{"term":"bedroom","ipa":"/ˈbɛdrum/","part_of_speech":"noun","meaning_vi":"phòng ngủ","example":"I put the photo of us on the wall in my bedroom.","example_vi":"Em treo tấm ảnh hai đứa lên tường phòng ngủ."}'::jsonb),
  ('vocab-a1-home-04', 'vocab-a1-home-furniture', 4, 'multiple_choice', 'A1', 'Recognize the meaning of ''lamp''', 'It''s dark in here. Can you turn on the ___?', 'Trong này tối quá. Em bật ___ lên được không?', '["lamp","sofa","pillow","shelf"]'::jsonb, null, null, null, null, 'lamp', '["lamp"]'::jsonb, 'A lamp is a light you can turn on and off, often on a table or desk. You can''t turn on a sofa or a pillow.', '"Lamp" là cái đèn (thường là đèn bàn, đèn ngủ). Ghế sofa hay gối thì không "bật" được.', '{"term":"lamp","ipa":"/læmp/","part_of_speech":"noun","meaning_vi":"cái đèn (đèn bàn, đèn ngủ)","example":"I bought a warm yellow lamp, so you can see my face better on video.","example_vi":"Anh mua một cái đèn vàng ấm để em nhìn rõ mặt anh hơn khi gọi video."}'::jsonb),
  ('vocab-a1-home-05', 'vocab-a1-home-furniture', 5, 'multiple_choice', 'A1', 'Recognize the meaning of ''pillow''', 'What does ''pillow'' mean?', 'Từ ''pillow'' có nghĩa là gì?', '["a soft thing you put your head on in bed","a thick cover that keeps you warm in bed","a small rug next to the door","a hard seat with no back"]'::jsonb, null, null, null, null, 'pillow', '["a soft thing you put your head on in bed"]'::jsonb, 'A pillow is the soft thing under your head when you sleep. The warm cover over your body is a blanket.', '"Pillow" là cái gối để kê đầu khi ngủ. Còn cái đắp lên người cho ấm là "blanket" (cái chăn/mền).', '{"term":"pillow","ipa":"/ˈpɪloʊ/","part_of_speech":"noun","meaning_vi":"cái gối","example":"I hug my pillow and pretend it''s you.","example_vi":"Em ôm gối rồi tưởng tượng đó là anh."}'::jsonb),
  ('vocab-a1-home-06', 'vocab-a1-home-furniture', 6, 'multiple_choice', 'A1', 'Recognize the meaning of ''blanket''', 'It''s cold tonight, so I''m under a warm ___ while we video call.', 'Tối nay lạnh nên anh trùm một cái ___ ấm trong lúc tụi mình gọi video.', '["blanket","mirror","shelf","lamp"]'::jsonb, null, null, null, null, 'blanket', '["blanket"]'::jsonb, 'A blanket is a large, warm cover for your body, especially in bed. You get "under" a blanket to stay warm.', '"Blanket" là cái chăn, cái mền. Trời lạnh thì chui vào (under) chăn cho ấm.', '{"term":"blanket","ipa":"/ˈblæŋkɪt/","part_of_speech":"noun","meaning_vi":"cái chăn, cái mền","example":"This blanket is so soft — it''s my favorite.","example_vi":"Cái chăn này mềm quá — em thích nó nhất."}'::jsonb),
  ('vocab-a1-home-07', 'vocab-a1-home-furniture', 7, 'multiple_choice', 'A1', 'Recognize the meaning of ''fridge''', 'What does ''fridge'' mean?', 'Từ ''fridge'' có nghĩa là gì?', '["a machine that keeps food cold","a machine that washes clothes","a machine that heats food quickly","a box for keeping shoes"]'::jsonb, null, null, null, null, 'fridge', '["a machine that keeps food cold"]'::jsonb, 'A fridge (short for refrigerator) keeps food and drinks cold and fresh. A machine that heats food quickly is a microwave.', '"Fridge" (viết tắt của refrigerator) là tủ lạnh. Máy hâm nóng đồ ăn nhanh là microwave (lò vi sóng).', '{"term":"fridge","ipa":"/frɪdʒ/","part_of_speech":"noun","meaning_vi":"tủ lạnh","example":"There''s some leftover chè in the fridge for you.","example_vi":"Trong tủ lạnh còn ít chè để dành cho em đó."}'::jsonb),
  ('vocab-a1-home-08', 'vocab-a1-home-furniture', 8, 'multiple_choice', 'A1', 'Recognize the meaning of ''shelf''', 'I put our photo on the ___ above my desk.', 'Anh để ảnh hai đứa trên ___ phía trên bàn làm việc.', '["shelf","sofa","pillow","sink"]'::jsonb, null, null, null, null, 'shelf', '["shelf"]'::jsonb, 'A shelf is a flat board on a wall or in a cupboard for putting things on, like books or photos.', '"Shelf" là cái kệ, giá để đồ — tấm ván phẳng gắn trên tường hoặc trong tủ để đặt sách, ảnh. Số nhiều là shelves.', '{"term":"shelf","ipa":"/ʃɛlf/","part_of_speech":"noun","meaning_vi":"cái kệ, giá để đồ","example":"The gift you sent me is on my bookshelf.","example_vi":"Món quà anh gửi đang nằm trên kệ sách của em."}'::jsonb),
  ('vocab-a1-home-09', 'vocab-a1-home-furniture', 9, 'multiple_choice', 'A1', 'Recognize the meaning of ''mirror''', 'She checked her hair in the ___ before their date.', 'Cô ấy soi lại tóc trong ___ trước buổi hẹn.', '["mirror","lamp","fridge","blanket"]'::jsonb, null, null, null, null, 'mirror', '["mirror"]'::jsonb, 'A mirror is a piece of glass where you can see yourself. People look in a mirror to check their hair or clothes.', '"Mirror" là cái gương. Mình soi gương để xem lại tóc tai, quần áo.', '{"term":"mirror","ipa":"/ˈmɪrər/","part_of_speech":"noun","meaning_vi":"cái gương","example":"I practiced saying \"I love you\" in English in front of the mirror.","example_vi":"Anh tập nói \"I love you\" bằng tiếng Anh trước gương."}'::jsonb),
  ('vocab-a1-home-10', 'vocab-a1-home-furniture', 10, 'multiple_choice', 'A1', 'Recognize the meaning of ''cozy''', '''cozy'' nghĩa là gì?', null, '["ấm cúng","rộng rãi","lạnh lẽo","bừa bộn"]'::jsonb, null, null, null, null, 'cozy', '["ấm cúng"]'::jsonb, '"Cozy" describes a place that feels warm, comfortable, and relaxing — like a small room with soft lights and a blanket.', '"Cozy" là ấm cúng, dễ chịu — như một căn phòng nhỏ có đèn vàng và chăn êm. British English viết là "cosy".', '{"term":"cozy","ipa":"/ˈkoʊzi/","part_of_speech":"adjective","meaning_vi":"ấm cúng","example":"Your room looks so cozy with all those little lights.","example_vi":"Phòng em nhìn ấm cúng quá với mấy dây đèn nhỏ đó."}'::jsonb),
  ('vocab-a2-comm-01', 'vocab-a2-communication', 1, 'multiple_choice', 'A2', 'Recognize the meaning of ''call back''', 'I''m in a meeting right now. I''ll ___ in an hour, okay?', 'Giờ anh đang họp. Một tiếng nữa anh ___ nhé?', '["call you back","hang up on you","mute you","text yourself"]'::jsonb, null, null, null, null, 'call back', '["call you back"]'::jsonb, 'To call someone back means to phone them again later, usually because you couldn''t talk before. The person goes in the middle: call you back.', '"Call back" là gọi lại sau. Người được gọi đứng giữa: call you back, call her back.', '{"term":"call back","ipa":"/kɔl bæk/","part_of_speech":"phrase","meaning_vi":"gọi lại","example":"Sorry I missed your call — I''ll call you back after class.","example_vi":"Xin lỗi em lỡ cuộc gọi của anh — tan học em gọi lại nha."}'::jsonb),
  ('vocab-a2-comm-02', 'vocab-a2-communication', 2, 'multiple_choice', 'A2', 'Recognize the meaning of ''text''', 'What does ''text'' mean in "I''ll text you later"?', 'Từ ''text'' trong "I''ll text you later" có nghĩa là gì?', '["to send a written message by phone","to speak loudly on the phone","to read a book aloud","to write a long letter by hand"]'::jsonb, null, null, null, null, 'text', '["to send a written message by phone"]'::jsonb, 'As a verb, "text" means to send someone a written message on your phone. The past form is "texted".', 'Khi là động từ, "text" là nhắn tin qua điện thoại. Quá khứ là "texted".', '{"term":"text","ipa":"/tɛkst/","part_of_speech":"verb","meaning_vi":"nhắn tin","example":"Text me when you get home safely, okay?","example_vi":"Về tới nhà an toàn thì nhắn anh nhé?"}'::jsonb),
  ('vocab-a2-comm-03', 'vocab-a2-communication', 3, 'multiple_choice', 'A2', 'Recognize the meaning of ''voice message''', 'You were asleep, so I left you a ___ singing "Happy Birthday".', 'Lúc đó em đang ngủ nên anh để lại một ___ hát "Happy Birthday" cho em.', '["voice message","battery","signal","password"]'::jsonb, null, null, null, null, 'voice message', '["voice message"]'::jsonb, 'A voice message is a recorded audio message someone can listen to later. Singing is the clue — you need your voice!', '"Voice message" là tin nhắn thoại — đoạn ghi âm để người kia nghe sau. Manh mối là "singing" — hát thì cần giọng nói.', '{"term":"voice message","ipa":"/vɔɪs ˈmɛsɪdʒ/","part_of_speech":"noun","meaning_vi":"tin nhắn thoại","example":"I listen to your voice messages again when I miss you.","example_vi":"Những lúc nhớ anh, em lại mở nghe tin nhắn thoại của anh."}'::jsonb),
  ('vocab-a2-comm-04', 'vocab-a2-communication', 4, 'multiple_choice', 'A2', 'Recognize the meaning of ''video call''', 'What does ''video call'' mean?', 'Cụm ''video call'' có nghĩa là gì?', '["a call where you can see each other''s faces on a screen","a short written message","a movie you watch online","a phone call with no sound"]'::jsonb, null, null, null, null, 'video call', '["a call where you can see each other''s faces on a screen"]'::jsonb, 'On a video call you can see and hear each other through the camera. It can also be a verb: "Let''s video call tonight."', '"Video call" là cuộc gọi video — nhìn thấy và nghe nhau qua camera. Cũng dùng như động từ: "Let''s video call tonight."', '{"term":"video call","ipa":"/ˈvɪdioʊ kɔl/","part_of_speech":"noun","meaning_vi":"cuộc gọi video","example":"Our Sunday video call is the best part of my week.","example_vi":"Cuộc gọi video ngày Chủ nhật là khoảnh khắc vui nhất trong tuần của anh."}'::jsonb),
  ('vocab-a2-comm-05', 'vocab-a2-communication', 5, 'multiple_choice', 'A2', 'Recognize the meaning of ''hang up''', 'Don''t ___ yet — I want to say good night one more time!', 'Đừng ___ vội — em muốn chúc anh ngủ ngon thêm lần nữa!', '["hang up","pick up","turn on","sit down"]'::jsonb, null, null, null, null, 'hang up', '["hang up"]'::jsonb, 'To hang up means to end a phone call. "Pick up" is the opposite — answering a call.', '"Hang up" là cúp máy, tắt cuộc gọi. Ngược lại, "pick up" là nhấc máy, nghe điện thoại.', '{"term":"hang up","ipa":"/hæŋ ʌp/","part_of_speech":"phrase","meaning_vi":"cúp máy","example":"Neither of us wanted to hang up first.","example_vi":"Chẳng ai trong hai đứa muốn cúp máy trước."}'::jsonb),
  ('vocab-a2-comm-06', 'vocab-a2-communication', 6, 'multiple_choice', 'A2', 'Recognize the meaning of ''signal''', 'Sorry, I''m on the train and my phone ___ is really weak. I can''t hear you well.', 'Xin lỗi, anh đang trên tàu và ___ điện thoại yếu quá. Anh nghe em không rõ.', '["signal","ticket","coffee","seat"]'::jsonb, null, null, null, null, 'signal', '["signal"]'::jsonb, 'A phone signal is the connection your phone needs to make calls and use data. A weak signal makes voices break up.', '"Signal" là sóng, tín hiệu điện thoại. Sóng yếu (weak signal) thì cuộc gọi bị ngắt quãng, nghe không rõ.', '{"term":"signal","ipa":"/ˈsɪɡnəl/","part_of_speech":"noun","meaning_vi":"sóng, tín hiệu (điện thoại)","example":"There''s no signal in the mountains, so I''ll text you tomorrow.","example_vi":"Trên núi không có sóng nên mai em nhắn anh nha."}'::jsonb),
  ('vocab-a2-comm-07', 'vocab-a2-communication', 7, 'multiple_choice', 'A2', 'Recognize the meaning of ''reply''', '''reply'' nghĩa là gì?', null, '["trả lời, hồi âm","gọi lại","xóa","gửi đi"]'::jsonb, null, null, null, null, 'reply', '["trả lời, hồi âm"]'::jsonb, 'To reply means to answer a message, letter, or question. We say "reply to" someone or something.', '"Reply" là trả lời, hồi âm (tin nhắn, thư). Cấu trúc: reply to someone/something.', '{"term":"reply","ipa":"/rɪˈplaɪ/","part_of_speech":"verb","meaning_vi":"trả lời, hồi âm","example":"Sorry I didn''t reply — my phone was in my bag.","example_vi":"Xin lỗi anh không trả lời — điện thoại anh để trong túi."}'::jsonb),
  ('vocab-a2-comm-08', 'vocab-a2-communication', 8, 'multiple_choice', 'A2', 'Recognize the meaning of ''battery''', 'My phone ___ is at 2%. I need to charge it before we talk!', '___ điện thoại em còn 2%. Em phải sạc trước khi mình nói chuyện!', '["battery","signal","screen","camera"]'::jsonb, null, null, null, null, 'battery', '["battery"]'::jsonb, 'A battery stores power for your phone. When it''s low (like 2%), you need to charge it.', '"Battery" là pin. Pin còn ít (2%) thì phải sạc (charge).', '{"term":"battery","ipa":"/ˈbætəri/","part_of_speech":"noun","meaning_vi":"pin","example":"My battery died in the middle of our call — sorry!","example_vi":"Điện thoại anh hết pin giữa cuộc gọi — xin lỗi em nha!"}'::jsonb),
  ('vocab-a2-comm-09', 'vocab-a2-communication', 9, 'multiple_choice', 'A2', 'Recognize the meaning of ''mute''', 'What does ''mute'' mean on a call?', 'Từ ''mute'' trong cuộc gọi có nghĩa là gì?', '["to turn off the sound so others can''t hear you","to make the screen brighter","to end the call","to send a photo"]'::jsonb, null, null, null, null, 'mute', '["to turn off the sound so others can''t hear you"]'::jsonb, 'To mute means to turn the sound off. If your partner can''t hear you, maybe you''re on mute!', '"Mute" là tắt tiếng. Nếu người kia không nghe thấy mình, có thể mình đang bật chế độ tắt mic (on mute) đó!', '{"term":"mute","ipa":"/mjut/","part_of_speech":"verb","meaning_vi":"tắt tiếng","example":"I can''t hear you — I think you muted yourself.","example_vi":"Anh không nghe em nói gì hết — hình như em tự tắt mic rồi."}'::jsonb),
  ('vocab-a2-comm-10', 'vocab-a2-communication', 10, 'multiple_choice', 'A2', 'Recognize the meaning of ''online''', 'I see you''re ___ — are you free to chat now?', 'Anh thấy em đang ___ — giờ em rảnh nói chuyện không?', '["online","offline","absent","closed"]'::jsonb, null, null, null, null, 'online', '["online"]'::jsonb, '"Online" means connected to the internet and active, so you can chat. "Offline" is the opposite.', '"Online" là đang trực tuyến, đang kết nối mạng nên có thể nói chuyện. Ngược lại là "offline".', '{"term":"online","ipa":"/ˌɑnˈlaɪn/","part_of_speech":"adjective","meaning_vi":"trực tuyến, đang online","example":"You''re still online at 2 a.m.? Go to sleep, my love!","example_vi":"Hai giờ sáng mà em vẫn còn online hả? Đi ngủ đi em yêu!"}'::jsonb),
  ('vocab-a2-feelings-01', 'vocab-a2-feelings-emotions', 1, 'multiple_choice', 'A2', 'Recognize the meaning of ''grateful''', 'Thank you for staying up late to talk to me. I''m really ___.', 'Cảm ơn anh đã thức khuya nói chuyện với em. Em thật sự rất ___.', '["grateful","bored","angry","jealous"]'::jsonb, null, null, null, null, 'grateful', '["grateful"]'::jsonb, '"Grateful" means thankful — you feel it when someone does something kind for you. We say "grateful for" something.', '"Grateful" là biết ơn, cảm kích — cảm giác khi ai đó làm điều tốt cho mình. Cụm hay dùng: grateful for something.', '{"term":"grateful","ipa":"/ˈɡreɪtfəl/","part_of_speech":"adjective","meaning_vi":"biết ơn, cảm kích","example":"I''m so grateful for every minute we spend together.","example_vi":"Anh rất biết ơn từng phút giây tụi mình bên nhau."}'::jsonb),
  ('vocab-a2-feelings-02', 'vocab-a2-feelings-emotions', 2, 'multiple_choice', 'A2', 'Recognize the meaning of ''lonely''', 'What does ''lonely'' mean?', 'Từ ''lonely'' có nghĩa là gì?', '["sad because you are alone or have no one to talk to","happy to be with many friends","tired after working hard","afraid of the dark"]'::jsonb, null, null, null, null, 'lonely', '["sad because you are alone or have no one to talk to"]'::jsonb, '"Lonely" is the sad feeling of being alone. "Alone" just means no one is with you; "lonely" adds the sadness.', '"Lonely" là cô đơn — buồn vì chỉ có một mình. "Alone" chỉ là ở một mình, còn "lonely" có thêm cảm giác buồn.', '{"term":"lonely","ipa":"/ˈloʊnli/","part_of_speech":"adjective","meaning_vi":"cô đơn","example":"Weekends feel lonely without you, so let''s video call on Saturday.","example_vi":"Cuối tuần thiếu em thấy cô đơn lắm, thứ Bảy mình gọi video nha."}'::jsonb),
  ('vocab-a2-feelings-03', 'vocab-a2-feelings-emotions', 3, 'multiple_choice', 'A2', 'Recognize the meaning of ''nervous''', 'I''m so ___ about meeting your parents for the first time!', 'Anh ___ quá khi lần đầu gặp bố mẹ em!', '["nervous","bored","sleepy","full"]'::jsonb, null, null, null, null, 'nervous', '["nervous"]'::jsonb, '"Nervous" means a little worried or scared about something that will happen, like a first meeting or a test.', '"Nervous" là hồi hộp, lo lắng về chuyện sắp xảy ra, như lần đầu ra mắt hay đi thi.', '{"term":"nervous","ipa":"/ˈnɝvəs/","part_of_speech":"adjective","meaning_vi":"hồi hộp, lo lắng","example":"I always feel nervous before speaking English in public.","example_vi":"Em lúc nào cũng hồi hộp trước khi nói tiếng Anh trước đám đông."}'::jsonb),
  ('vocab-a2-feelings-04', 'vocab-a2-feelings-emotions', 4, 'multiple_choice', 'A2', 'Recognize the meaning of ''excited''', 'What does ''excited'' mean?', 'Từ ''excited'' có nghĩa là gì?', '["very happy and eager about something good that will happen","angry about something unfair","tired and not interested","sad about the past"]'::jsonb, null, null, null, null, 'excited', '["very happy and eager about something good that will happen"]'::jsonb, '"Excited" means very happy and full of energy because something good is coming. Remember: a person is excited; a thing that causes it is exciting.', '"Excited" là háo hức, phấn khích vì sắp có chuyện vui. Nhớ nhé: người cảm thấy thì dùng excited, còn sự việc gây ra cảm giác đó là exciting.', '{"term":"excited","ipa":"/ɪkˈsaɪtɪd/","part_of_speech":"adjective","meaning_vi":"háo hức, phấn khích","example":"Only ten more days until I see you — I''m so excited!","example_vi":"Chỉ còn mười ngày nữa là gặp anh rồi — em háo hức quá!"}'::jsonb),
  ('vocab-a2-feelings-05', 'vocab-a2-feelings-emotions', 5, 'multiple_choice', 'A2', 'Recognize the meaning of ''proud''', 'You passed your English test! I''m so ___ of you.', 'Em đậu bài kiểm tra tiếng Anh rồi! Anh rất ___ về em.', '["proud","bored","hungry","sleepy"]'::jsonb, null, null, null, null, 'proud', '["proud"]'::jsonb, 'You feel proud when you or someone you love does something good. The pattern is "proud of someone".', '"Proud" là tự hào. Cấu trúc: proud of someone (tự hào về ai đó).', '{"term":"proud","ipa":"/praʊd/","part_of_speech":"adjective","meaning_vi":"tự hào","example":"I''m proud of us for making this long-distance thing work.","example_vi":"Anh tự hào về hai đứa mình vì đã cùng nhau vượt qua khoảng cách."}'::jsonb),
  ('vocab-a2-feelings-06', 'vocab-a2-feelings-emotions', 6, 'multiple_choice', 'A2', 'Recognize the meaning of ''upset''', '''upset'' nghĩa là gì?', null, '["buồn bực, khó chịu","phấn khích","bình tĩnh","tự hào"]'::jsonb, null, null, null, null, 'upset', '["buồn bực, khó chịu"]'::jsonb, '"Upset" means unhappy or worried because something bad happened. It''s a softer word than "angry".', '"Upset" là buồn bực, khó chịu, phiền lòng vì chuyện không vui. Nhẹ hơn "angry" (tức giận).', '{"term":"upset","ipa":"/ʌpˈsɛt/","part_of_speech":"adjective","meaning_vi":"buồn bực, khó chịu, phiền lòng","example":"Are you upset with me? You''re very quiet tonight.","example_vi":"Em đang buồn anh hả? Tối nay em im lặng quá."}'::jsonb),
  ('vocab-a2-feelings-07', 'vocab-a2-feelings-emotions', 7, 'multiple_choice', 'A2', 'Recognize the meaning of ''calm''', 'What does ''calm'' mean?', 'Từ ''calm'' có nghĩa là gì?', '["relaxed and not worried or angry","very loud and full of energy","sad and crying","angry and shouting"]'::jsonb, null, null, null, null, 'calm', '["relaxed and not worried or angry"]'::jsonb, '"Calm" means peaceful and relaxed. Note the silent "l": it sounds like /kɑm/.', '"Calm" là bình tĩnh, điềm tĩnh. Lưu ý chữ "l" câm, đọc là /kɑm/.', '{"term":"calm","ipa":"/kɑm/","part_of_speech":"adjective","meaning_vi":"bình tĩnh, điềm tĩnh","example":"Your voice always makes me feel calm after a hard day.","example_vi":"Giọng em lúc nào cũng làm anh thấy bình yên sau một ngày mệt mỏi."}'::jsonb),
  ('vocab-a2-feelings-08', 'vocab-a2-feelings-emotions', 8, 'multiple_choice', 'A2', 'Recognize the meaning of ''jealous''', 'He felt a little ___ when she kept talking about her handsome coworker.', 'Anh ấy hơi ___ khi cô ấy cứ kể về anh đồng nghiệp đẹp trai.', '["jealous","grateful","hungry","sleepy"]'::jsonb, null, null, null, null, 'jealous', '["jealous"]'::jsonb, '"Jealous" is the unhappy feeling when you worry someone might take away the person you love, or when you want what others have.', '"Jealous" là ghen, ghen tị — cảm giác khó chịu khi sợ người khác "cướp" người mình thương, hoặc khi muốn có thứ người khác có.', '{"term":"jealous","ipa":"/ˈdʒɛləs/","part_of_speech":"adjective","meaning_vi":"ghen, ghen tị","example":"Don''t be jealous — he''s just a friend from class.","example_vi":"Đừng ghen mà — cậu ấy chỉ là bạn cùng lớp thôi."}'::jsonb),
  ('vocab-a2-feelings-09', 'vocab-a2-feelings-emotions', 9, 'multiple_choice', 'A2', 'Recognize the meaning of ''relieved''', 'Your flight landed safely? I''m so ___!', 'Chuyến bay của em hạ cánh an toàn rồi hả? Anh ___ quá!', '["relieved","jealous","bored","lonely"]'::jsonb, null, null, null, null, 'relieved', '["relieved"]'::jsonb, 'You feel relieved when a worry goes away and something ends well — like hearing that a flight landed safely.', '"Relieved" là nhẹ nhõm, yên tâm — cảm giác khi nỗi lo qua đi, mọi chuyện ổn thỏa.', '{"term":"relieved","ipa":"/rɪˈlivd/","part_of_speech":"adjective","meaning_vi":"nhẹ nhõm, yên tâm","example":"I was so relieved when you finally answered your phone.","example_vi":"Em nhẹ cả người khi cuối cùng anh cũng nghe máy."}'::jsonb),
  ('vocab-a2-feelings-10', 'vocab-a2-feelings-emotions', 10, 'multiple_choice', 'A2', 'Recognize the meaning of ''bored''', 'What does ''bored'' mean?', 'Từ ''bored'' có nghĩa là gì?', '["tired and unhappy because nothing interesting is happening","very surprised by good news","scared of something dangerous","pleased with something you did"]'::jsonb, null, null, null, null, 'bored', '["tired and unhappy because nothing interesting is happening"]'::jsonb, '"Bored" means you have nothing interesting to do. Say "I''m bored" (how you feel), not "I''m boring" (that means you are not interesting!).', '"Bored" là chán. Nói "I''m bored" (em thấy chán), đừng nói "I''m boring" — câu đó nghĩa là "em là người nhàm chán" đấy!', '{"term":"bored","ipa":"/bɔrd/","part_of_speech":"adjective","meaning_vi":"chán, buồn chán","example":"I''m bored at home — tell me something funny from your day.","example_vi":"Ở nhà chán quá — kể em nghe chuyện gì vui hôm nay đi."}'::jsonb),
  ('vocab-a2-weather-01', 'vocab-a2-weather-nature', 1, 'multiple_choice', 'A2', 'Recognize the meaning of ''sunny''', 'It''s ___ today, so don''t forget your sunglasses.', 'Hôm nay trời ___, đừng quên mang kính râm nhé.', '["sunny","rainy","foggy","snowy"]'::jsonb, null, null, null, null, 'sunny', '["sunny"]'::jsonb, '"Sunny" means the sun is shining brightly. Sunglasses are the clue — you need them on a sunny day.', '"Sunny" là trời nắng. Manh mối là kính râm (sunglasses) — trời nắng mới cần.', '{"term":"sunny","ipa":"/ˈsʌni/","part_of_speech":"adjective","meaning_vi":"có nắng, nắng đẹp","example":"It''s sunny here — I wish you could walk by the river with me.","example_vi":"Ở đây trời nắng đẹp — ước gì em được đi dạo bờ sông cùng anh."}'::jsonb),
  ('vocab-a2-weather-02', 'vocab-a2-weather-nature', 2, 'multiple_choice', 'A2', 'Recognize the meaning of ''cloudy''', 'What does ''cloudy'' mean?', 'Từ ''cloudy'' có nghĩa là gì?', '["with a lot of clouds in the sky","with very strong winds","very hot and dry","with ice on the roads"]'::jsonb, null, null, null, null, 'cloudy', '["with a lot of clouds in the sky"]'::jsonb, '"Cloudy" describes a sky full of clouds, so you can''t see much sun. Many weather words are a noun + -y: cloud → cloudy, sun → sunny.', '"Cloudy" là nhiều mây, trời âm u. Nhiều từ thời tiết được tạo bằng danh từ + -y: cloud → cloudy, sun → sunny, fog → foggy.', '{"term":"cloudy","ipa":"/ˈklaʊdi/","part_of_speech":"adjective","meaning_vi":"nhiều mây, âm u","example":"It''s cloudy and gray today, just like my mood without you.","example_vi":"Hôm nay trời âm u xám xịt, y như tâm trạng anh khi thiếu em."}'::jsonb),
  ('vocab-a2-weather-03', 'vocab-a2-weather-nature', 3, 'multiple_choice', 'A2', 'Recognize the meaning of ''foggy''', 'It''s so ___ this morning that I can''t see the bridge.', 'Sáng nay trời ___ đến mức em không nhìn thấy cây cầu.', '["foggy","sunny","warm","dry"]'::jsonb, null, null, null, null, 'foggy', '["foggy"]'::jsonb, '"Foggy" means there is thick, cloudy air near the ground, so it''s hard to see far.', '"Foggy" là có sương mù dày, khó nhìn xa — như buổi sáng ở Đà Lạt hay Sa Pa.', '{"term":"foggy","ipa":"/ˈfɑɡi/","part_of_speech":"adjective","meaning_vi":"có sương mù","example":"Đà Lạt is foggy and romantic in the early morning.","example_vi":"Đà Lạt sáng sớm sương mù giăng, lãng mạn lắm."}'::jsonb),
  ('vocab-a2-weather-04', 'vocab-a2-weather-nature', 4, 'multiple_choice', 'A2', 'Recognize the meaning of ''storm''', 'What does ''storm'' mean?', 'Từ ''storm'' có nghĩa là gì?', '["very bad weather with strong wind, rain, and often thunder","a light, warm wind","a time of year with no rain","a small amount of snow"]'::jsonb, null, null, null, null, 'storm', '["very bad weather with strong wind, rain, and often thunder"]'::jsonb, 'A storm is very bad weather with strong winds and heavy rain. A light, warm wind is a breeze.', '"Storm" là cơn bão, giông bão — gió mạnh, mưa to, thường có sấm sét. Còn gió nhẹ là "breeze".', '{"term":"storm","ipa":"/stɔrm/","part_of_speech":"noun","meaning_vi":"cơn bão, giông bão","example":"There''s a big storm tonight, so please stay inside and stay safe.","example_vi":"Tối nay có bão lớn, em ở trong nhà cho an toàn nhé."}'::jsonb),
  ('vocab-a2-weather-05', 'vocab-a2-weather-nature', 5, 'multiple_choice', 'A2', 'Recognize the meaning of ''humid''', '''humid'' nghĩa là gì?', null, '["ẩm, oi ẩm","khô hanh","lạnh buốt","nhiều gió"]'::jsonb, null, null, null, null, 'humid', '["ẩm, oi ẩm"]'::jsonb, '"Humid" means the air feels wet and heavy, like a hot summer day in Sài Gòn.', '"Humid" là ẩm, oi ẩm — không khí nhiều hơi nước, nặng nề, như mùa nồm ở miền Bắc hay ngày hè oi bức ở Sài Gòn.', '{"term":"humid","ipa":"/ˈhjumɪd/","part_of_speech":"adjective","meaning_vi":"ẩm, oi ẩm","example":"It''s so humid today that my clothes won''t dry.","example_vi":"Hôm nay trời ẩm quá, phơi đồ mãi không khô."}'::jsonb),
  ('vocab-a2-weather-06', 'vocab-a2-weather-nature', 6, 'multiple_choice', 'A2', 'Recognize the meaning of ''breeze''', 'A cool ___ from the sea made the hot afternoon feel nice.', 'Một làn ___ mát từ biển làm buổi chiều nóng bức trở nên dễ chịu.', '["breeze","storm","rainbow","flood"]'::jsonb, null, null, null, null, 'breeze', '["breeze"]'::jsonb, 'A breeze is a light, gentle wind. A storm or a flood would not make the afternoon "feel nice".', '"Breeze" là làn gió nhẹ, gió hiu hiu. Bão (storm) hay lũ (flood) thì không làm buổi chiều dễ chịu được.', '{"term":"breeze","ipa":"/briz/","part_of_speech":"noun","meaning_vi":"làn gió nhẹ","example":"I love sitting on the balcony in the evening breeze and texting you.","example_vi":"Anh thích ngồi ngoài ban công hóng gió chiều và nhắn tin cho em."}'::jsonb),
  ('vocab-a2-weather-07', 'vocab-a2-weather-nature', 7, 'multiple_choice', 'A2', 'Recognize the meaning of ''rainbow''', 'What does ''rainbow'' mean?', 'Từ ''rainbow'' có nghĩa là gì?', '["an arc of colors in the sky, often after rain","a loud noise during a storm","a bright flash of light in a storm","a cloud that is close to the ground"]'::jsonb, null, null, null, null, 'rainbow', '["an arc of colors in the sky, often after rain"]'::jsonb, 'A rainbow is the curve of colors you see in the sky when the sun shines after rain. The loud noise is thunder and the flash is lightning.', '"Rainbow" là cầu vồng. Tiếng nổ lớn khi giông là thunder (sấm), tia sáng lóe lên là lightning (chớp).', '{"term":"rainbow","ipa":"/ˈreɪnˌboʊ/","part_of_speech":"noun","meaning_vi":"cầu vồng","example":"Look, a rainbow! I took a photo for you.","example_vi":"Nhìn kìa, cầu vồng! Em chụp cho anh một tấm nè."}'::jsonb),
  ('vocab-a2-weather-08', 'vocab-a2-weather-nature', 8, 'multiple_choice', 'A2', 'Recognize the meaning of ''freezing''', 'It''s ___ here — minus five degrees! Is it warm in Sài Gòn?', 'Ở đây ___ lắm — âm năm độ! Sài Gòn có ấm không em?', '["freezing","hot","warm","boiling"]'::jsonb, null, null, null, null, 'freezing', '["freezing"]'::jsonb, '"Freezing" means extremely cold — cold enough for water to turn into ice. Minus five degrees is freezing!', '"Freezing" là lạnh cóng, lạnh buốt — lạnh tới mức nước đóng băng. Âm năm độ thì chắc chắn là freezing!', '{"term":"freezing","ipa":"/ˈfrizɪŋ/","part_of_speech":"adjective","meaning_vi":"lạnh cóng, lạnh buốt","example":"My hands are freezing — I need you to hold them.","example_vi":"Tay em lạnh cóng rồi — cần anh nắm tay sưởi ấm."}'::jsonb),
  ('vocab-a2-weather-09', 'vocab-a2-weather-nature', 9, 'multiple_choice', 'A2', 'Recognize the meaning of ''forecast''', 'What does ''forecast'' mean?', 'Từ ''forecast'' có nghĩa là gì?', '["a report that says what the weather will be like","a map of the stars at night","a photo of the sky","a season with heavy rain"]'::jsonb, null, null, null, null, 'forecast', '["a report that says what the weather will be like"]'::jsonb, 'A forecast tells you what the weather will probably be in the future. We often say "the weather forecast".', '"Forecast" là bản dự báo, thường gặp trong cụm "weather forecast" (dự báo thời tiết).', '{"term":"forecast","ipa":"/ˈfɔrˌkæst/","part_of_speech":"noun","meaning_vi":"dự báo (thời tiết)","example":"I check the forecast for your city every morning.","example_vi":"Sáng nào anh cũng xem dự báo thời tiết ở thành phố của em."}'::jsonb),
  ('vocab-a2-weather-10', 'vocab-a2-weather-nature', 10, 'multiple_choice', 'A2', 'Recognize the meaning of ''sunset''', '''sunset'' nghĩa là gì?', null, '["hoàng hôn","bình minh","cầu vồng","ánh trăng"]'::jsonb, null, null, null, null, 'sunset', '["hoàng hôn"]'::jsonb, 'Sunset is when the sun goes down in the evening. The opposite, when the sun comes up, is sunrise.', '"Sunset" là hoàng hôn, lúc mặt trời lặn. Ngược lại, bình minh là "sunrise".', '{"term":"sunset","ipa":"/ˈsʌnˌsɛt/","part_of_speech":"noun","meaning_vi":"hoàng hôn","example":"Your sunset is my sunrise — we''re never far in my heart.","example_vi":"Hoàng hôn của em là bình minh của anh — trong tim anh, mình chưa bao giờ xa."}'::jsonb),
  ('vocab-b1-love-01', 'vocab-b1-love-relationships', 1, 'multiple_choice', 'B1', 'Use ''reassure'' in context', 'She was worried about the exam, so he called to ___ her that everything would be fine.', 'Cô ấy lo lắng về kỳ thi, nên anh ấy gọi điện để ___ cô ấy rằng mọi chuyện sẽ ổn.', '["reassure","remind","complain","argue"]'::jsonb, null, null, null, null, 'reassure', '["reassure"]'::jsonb, 'To reassure someone means to say or do something to make them feel less worried. We often say "reassure someone that...".', '"Reassure" là trấn an, làm ai đó bớt lo lắng. Cấu trúc thường gặp: "reassure someone that...". "Remind" là nhắc nhở, không hợp với ngữ cảnh đang lo lắng.', '{"term":"reassure","ipa":"/ˌriəˈʃʊr/","part_of_speech":"verb","meaning_vi":"trấn an, làm yên lòng","example":"Whenever I feel lonely, your messages reassure me that we are a team.","example_vi":"Mỗi khi em thấy cô đơn, tin nhắn của anh làm em yên lòng rằng tụi mình là một đội."}'::jsonb),
  ('vocab-b1-love-02', 'vocab-b1-love-relationships', 2, 'multiple_choice', 'B1', 'Understand the meaning of ''commitment''', 'What does ''commitment'' mean in a relationship?', '''commitment'' trong một mối quan hệ nghĩa là gì?', '["A promise to stay loyal and keep working on the relationship","A short argument between two people","A gift you give on a special day","A feeling of being bored with someone"]'::jsonb, null, null, null, null, 'commitment', '["A promise to stay loyal and keep working on the relationship"]'::jsonb, 'Commitment means being dedicated to someone or something for a long time. In love, it shows you are serious about your future together.', '"Commitment" là sự cam kết, gắn bó lâu dài. Trong tình yêu, nó thể hiện bạn nghiêm túc với tương lai của hai người.', '{"term":"commitment","ipa":"/kəˈmɪtmənt/","part_of_speech":"noun","meaning_vi":"sự cam kết, sự gắn bó","example":"Calling each other every night, even when we''re tired, is our small commitment.","example_vi":"Gọi cho nhau mỗi tối, kể cả khi mệt, là cam kết nhỏ của tụi mình."}'::jsonb),
  ('vocab-b1-love-03', 'vocab-b1-love-relationships', 3, 'multiple_choice', 'B1', 'Use ''cherish'' in context', 'I will always ___ the memories of our first trip together.', 'Em sẽ luôn ___ những kỷ niệm của chuyến đi đầu tiên của tụi mình.', '["cherish","forget","borrow","replace"]'::jsonb, null, null, null, null, 'cherish', '["cherish"]'::jsonb, 'To cherish something means to love it and keep it carefully because it is very special to you. Memories, moments and people are often cherished.', '"Cherish" là trân trọng, nâng niu điều gì đó vì nó rất quý giá. Từ này hay đi với memories (kỷ niệm), moments (khoảnh khắc) hay người mình yêu.', '{"term":"cherish","ipa":"/ˈtʃɛrɪʃ/","part_of_speech":"verb","meaning_vi":"trân trọng, nâng niu","example":"I cherish every little note you hide in my suitcase.","example_vi":"Anh trân trọng từng mảnh giấy nhỏ em giấu trong vali của anh."}'::jsonb),
  ('vocab-b1-love-04', 'vocab-b1-love-relationships', 4, 'multiple_choice', 'B1', 'Understand the meaning of ''long-distance''', 'What is a ''long-distance relationship''?', '''long-distance relationship'' là gì?', '["A relationship between two people who live far away from each other","A relationship that has lasted for many years","A friendship between people of different ages","A relationship where people talk only once a year"]'::jsonb, null, null, null, null, 'long-distance', '["A relationship between two people who live far away from each other"]'::jsonb, 'Long-distance describes something between places that are far apart. A long-distance relationship means the couple lives in different cities or countries.', '"Long-distance" nghĩa là đường dài, khoảng cách xa. "Long-distance relationship" là yêu xa, khi hai người sống ở hai thành phố hoặc hai đất nước khác nhau.', '{"term":"long-distance","ipa":"/ˌlɔŋˈdɪstəns/","part_of_speech":"adjective","meaning_vi":"xa, đường dài (yêu xa)","example":"A long-distance relationship is hard, but it teaches us to communicate better.","example_vi":"Yêu xa thì khó, nhưng nó dạy tụi mình cách giao tiếp tốt hơn."}'::jsonb),
  ('vocab-b1-love-05', 'vocab-b1-love-relationships', 5, 'multiple_choice', 'B1', 'Use ''loyal'' to describe a partner', 'He has been ___ to her for years, even when they lived in different countries.', 'Anh ấy đã ___ với cô ấy nhiều năm, kể cả khi họ sống ở hai nước khác nhau.', '["loyal","jealous","selfish","lazy"]'::jsonb, null, null, null, null, 'loyal', '["loyal"]'::jsonb, 'Loyal means always staying faithful and supportive to someone. We say "loyal to someone".', '"Loyal" là chung thủy, trung thành. Cấu trúc: "loyal to someone". Ngữ cảnh "nhiều năm, kể cả khi xa nhau" cho thấy ý tích cực, nên chọn "loyal".', '{"term":"loyal","ipa":"/ˈlɔɪəl/","part_of_speech":"adjective","meaning_vi":"chung thủy, trung thành","example":"Being loyal means I''m on your side, even when you''re far away.","example_vi":"Chung thủy nghĩa là anh luôn đứng về phía em, kể cả khi em ở xa."}'::jsonb),
  ('vocab-b1-love-06', 'vocab-b1-love-relationships', 6, 'multiple_choice', 'B1', 'Understand the meaning of ''affectionate''', 'What does ''affectionate'' mean?', '''affectionate'' nghĩa là gì?', '["Showing love and care, for example with hugs or kind words","Feeling angry very easily","Being very busy with work","Not wanting to talk to anyone"]'::jsonb, null, null, null, null, 'affectionate', '["Showing love and care, for example with hugs or kind words"]'::jsonb, 'Affectionate describes someone who shows their love openly, with hugs, sweet messages or kind gestures.', '"Affectionate" là trìu mến, tình cảm, hay thể hiện tình yêu bằng cái ôm, lời nói ngọt ngào hay cử chỉ quan tâm.', '{"term":"affectionate","ipa":"/əˈfɛkʃənət/","part_of_speech":"adjective","meaning_vi":"trìu mến, tình cảm","example":"You''re so affectionate. Your good-morning messages always make me smile.","example_vi":"Anh tình cảm ghê. Tin nhắn chào buổi sáng của anh lúc nào cũng làm em cười."}'::jsonb),
  ('vocab-b1-love-07', 'vocab-b1-love-relationships', 7, 'multiple_choice', 'B1', 'Use ''compromise'' in context', 'You want to call at nine and I want to call at eleven. Let''s ___ and call at ten.', 'Anh muốn gọi lúc chín giờ còn em muốn gọi lúc mười một giờ. Mình ___ và gọi lúc mười giờ nhé.', '["compromise","promise","pretend","disagree"]'::jsonb, null, null, null, null, 'compromise', '["compromise"]'::jsonb, 'To compromise means each person gives up a little so you can agree. Ten o''clock is in the middle, so it is a compromise.', '"Compromise" là thỏa hiệp, mỗi người nhường một chút để đi đến thống nhất. Mười giờ là điểm ở giữa nên đây là thỏa hiệp. Đừng nhầm với "promise" (hứa).', '{"term":"compromise","ipa":"/ˈkɑmprəˌmaɪz/","part_of_speech":"verb","meaning_vi":"thỏa hiệp, nhường nhau","example":"Good couples know how to compromise when they disagree.","example_vi":"Những cặp đôi tốt biết cách nhường nhau khi không cùng ý kiến."}'::jsonb),
  ('vocab-b1-love-08', 'vocab-b1-love-relationships', 8, 'multiple_choice', 'B1', 'Recognize the Vietnamese meaning of ''time difference''', 'Choose the Vietnamese meaning of ''time difference''.', 'Chọn nghĩa tiếng Việt của ''time difference''.', '["chênh lệch múi giờ","thời gian rảnh","giờ hẹn gặp","thời hạn cuối"]'::jsonb, null, null, null, null, 'time difference', '["chênh lệch múi giờ"]'::jsonb, 'The time difference is how many hours apart two places are. For long-distance couples, it decides when you can call each other.', '"Time difference" là chênh lệch múi giờ giữa hai nơi. Với các cặp yêu xa, nó quyết định lúc nào hai người có thể gọi cho nhau.', '{"term":"time difference","ipa":"/ˈtaɪm ˌdɪfərəns/","part_of_speech":"phrase","meaning_vi":"chênh lệch múi giờ","example":"Because of the time difference, your good night is my good morning.","example_vi":"Vì chênh lệch múi giờ, lời chúc ngủ ngon của anh là lời chào buổi sáng của em."}'::jsonb),
  ('vocab-b1-love-09', 'vocab-b1-love-relationships', 9, 'multiple_choice', 'B1', 'Use ''get along with'' in context', 'I''m so happy that you ___ my family. My mom already loves you!', 'Em vui lắm vì anh ___ gia đình em. Mẹ em đã quý anh rồi!', '["get along with","get away from","get rid of","get over"]'::jsonb, null, null, null, null, 'get along with', '["get along with"]'::jsonb, 'To get along with someone means to have a friendly, easy relationship with them. The other phrases mean escape, remove, and recover from.', '"Get along with someone" là hợp tính, hòa thuận với ai đó. "Get away from" là tránh xa, "get rid of" là loại bỏ, "get over" là vượt qua.', '{"term":"get along with","ipa":"/ɡɛt əˈlɔŋ wɪð/","part_of_speech":"phrase","meaning_vi":"hòa hợp với, hợp tính với","example":"My best friend and my boyfriend get along with each other really well.","example_vi":"Bạn thân của em và người yêu em rất hợp nhau."}'::jsonb),
  ('vocab-b1-love-10', 'vocab-b1-love-relationships', 10, 'multiple_choice', 'B1', 'Understand the meaning of ''anniversary''', 'What does ''anniversary'' mean?', '''anniversary'' nghĩa là gì?', '["The same date each year when something special happened","A party for a new baby","The first day of a new job","A holiday at the end of the year"]'::jsonb, null, null, null, null, 'anniversary', '["The same date each year when something special happened"]'::jsonb, 'An anniversary is the date when you remember a special event, like the day you started dating or got married.', '"Anniversary" là ngày kỷ niệm, ngày đánh dấu một sự kiện đặc biệt mỗi năm, như ngày bắt đầu yêu nhau hay ngày cưới.', '{"term":"anniversary","ipa":"/ˌænəˈvɜrsəri/","part_of_speech":"noun","meaning_vi":"ngày kỷ niệm","example":"For our second anniversary, let''s cook the same dinner on video call.","example_vi":"Kỷ niệm hai năm, mình cùng nấu một món tối qua video call nha."}'::jsonb),
  ('vocab-b1-travel-01', 'vocab-b1-travel-places', 1, 'multiple_choice', 'B1', 'Understand the meaning of ''destination''', 'What does ''destination'' mean?', '''destination'' nghĩa là gì?', '["The place you are travelling to","The ticket you buy for a trip","The person who travels with you","The time when a trip starts"]'::jsonb, null, null, null, null, 'destination', '["The place you are travelling to"]'::jsonb, 'A destination is the place at the end of your journey. "Our next destination is Hội An" means Hội An is where we are going.', '"Destination" là nơi bạn muốn đến, điểm đến cuối cùng của chuyến đi. Ví dụ: "Our next destination is Hội An" = Điểm đến tiếp theo của tụi mình là Hội An.', '{"term":"destination","ipa":"/ˌdɛstəˈneɪʃən/","part_of_speech":"noun","meaning_vi":"điểm đến","example":"Đà Lạt is our favorite destination for a weekend away.","example_vi":"Đà Lạt là điểm đến yêu thích của tụi mình cho những chuyến đi cuối tuần."}'::jsonb),
  ('vocab-b1-travel-02', 'vocab-b1-travel-places', 2, 'multiple_choice', 'B1', 'Use ''itinerary'' in context', 'I made an ___ for our trip: museum in the morning, beach in the afternoon, night market in the evening.', 'Anh đã lên ___ cho chuyến đi: sáng đi bảo tàng, chiều ra biển, tối đi chợ đêm.', '["itinerary","souvenir","passport","luggage"]'::jsonb, null, null, null, null, 'itinerary', '["itinerary"]'::jsonb, 'An itinerary is a plan of where you will go and when during a trip. The sentence lists a schedule, so "itinerary" fits.', '"Itinerary" là lịch trình chuyến đi: đi đâu, lúc nào. Câu này đang liệt kê kế hoạch theo giờ nên chọn "itinerary".', '{"term":"itinerary","ipa":"/aɪˈtɪnəˌrɛri/","part_of_speech":"noun","meaning_vi":"lịch trình (chuyến đi)","example":"Can you send me the itinerary so I know when your flight lands?","example_vi":"Em gửi anh lịch trình được không, để anh biết khi nào máy bay của em hạ cánh?"}'::jsonb),
  ('vocab-b1-travel-03', 'vocab-b1-travel-places', 3, 'multiple_choice', 'B1', 'Understand the meaning of ''landmark''', 'What does ''landmark'' mean?', '''landmark'' nghĩa là gì?', '["A small road in the countryside","A famous building or place that is easy to recognize","A map you use in a new city","A piece of land you can buy"]'::jsonb, null, null, null, null, 'landmark', '["A famous building or place that is easy to recognize"]'::jsonb, 'A landmark is a well-known building or place that helps people recognize a city, like the Eiffel Tower or Bến Thành Market.', '"Landmark" là địa danh, công trình nổi tiếng dễ nhận ra, ví dụ tháp Eiffel hay chợ Bến Thành.', '{"term":"landmark","ipa":"/ˈlændˌmɑrk/","part_of_speech":"noun","meaning_vi":"địa danh, công trình nổi tiếng","example":"Let''s take a photo in front of every famous landmark in the city.","example_vi":"Mình chụp ảnh trước mọi địa danh nổi tiếng trong thành phố nha."}'::jsonb),
  ('vocab-b1-travel-04', 'vocab-b1-travel-places', 4, 'multiple_choice', 'B1', 'Use ''accommodation'' in context', 'We still need to book ___ for three nights. A small homestay near the beach would be perfect.', 'Tụi mình vẫn cần đặt ___ cho ba đêm. Một homestay nhỏ gần biển là tuyệt nhất.', '["accommodation","departure","scenery","destination"]'::jsonb, null, null, null, null, 'accommodation', '["accommodation"]'::jsonb, 'Accommodation is a place to stay, like a hotel, hostel or homestay. You book accommodation for nights, so it is the only word that fits.', '"Accommodation" là chỗ ở (khách sạn, homestay...). Đặt chỗ "cho ba đêm" thì chỉ có thể là chỗ ở. Lưu ý từ này có hai chữ c và hai chữ m.', '{"term":"accommodation","ipa":"/əˌkɑməˈdeɪʃən/","part_of_speech":"noun","meaning_vi":"chỗ ở","example":"The accommodation was cheap, but the view from our window was amazing.","example_vi":"Chỗ ở thì rẻ, nhưng khung cảnh từ cửa sổ phòng tụi mình thì tuyệt đẹp."}'::jsonb),
  ('vocab-b1-travel-05', 'vocab-b1-travel-places', 5, 'multiple_choice', 'B1', 'Recognize the Vietnamese meaning of ''souvenir''', 'Choose the Vietnamese meaning of ''souvenir''.', 'Chọn nghĩa tiếng Việt của ''souvenir''.', '["quà lưu niệm","hành lý","vé máy bay","bản đồ"]'::jsonb, null, null, null, null, 'souvenir', '["quà lưu niệm"]'::jsonb, 'A souvenir is something you buy or keep to remember a place or a trip, like a keychain or a postcard.', '"Souvenir" là quà lưu niệm, món đồ mua để nhớ về một nơi hoặc một chuyến đi.', '{"term":"souvenir","ipa":"/ˌsuvəˈnɪr/","part_of_speech":"noun","meaning_vi":"quà lưu niệm","example":"I bought you a little souvenir from Huế. I hope you like it!","example_vi":"Em mua cho anh một món quà lưu niệm nhỏ từ Huế. Mong là anh thích!"}'::jsonb),
  ('vocab-b1-travel-06', 'vocab-b1-travel-places', 6, 'multiple_choice', 'B1', 'Use ''departure'' in context', 'Please arrive at the airport two hours before ___.', 'Vui lòng có mặt ở sân bay hai tiếng trước giờ ___.', '["departure","landmark","souvenir","accommodation"]'::jsonb, null, null, null, null, 'departure', '["departure"]'::jsonb, 'Departure is the act of leaving, especially when a plane, train or bus leaves. Its opposite is arrival.', '"Departure" là sự khởi hành, lúc máy bay/tàu/xe rời đi. Từ trái nghĩa là "arrival" (sự đến nơi). Ở sân bay bạn sẽ thấy bảng "Departures" và "Arrivals".', '{"term":"departure","ipa":"/dɪˈpɑrtʃər/","part_of_speech":"noun","meaning_vi":"sự khởi hành","example":"Our departure time is six thirty, so let''s sleep early tonight.","example_vi":"Giờ khởi hành của tụi mình là sáu giờ rưỡi, nên tối nay ngủ sớm nha."}'::jsonb),
  ('vocab-b1-travel-07', 'vocab-b1-travel-places', 7, 'multiple_choice', 'B1', 'Understand the meaning of ''scenery''', 'What does ''scenery'' mean?', '''scenery'' nghĩa là gì?', '["The natural things you see around you, like mountains, rivers and fields","A short film about a place","The noise you hear in a busy city","A list of places you plan to visit"]'::jsonb, null, null, null, null, 'scenery', '["The natural things you see around you, like mountains, rivers and fields"]'::jsonb, 'Scenery means the natural view around you in the countryside. It is uncountable, so we say "beautiful scenery", not "a scenery".', '"Scenery" là phong cảnh thiên nhiên. Đây là danh từ không đếm được: nói "beautiful scenery", không nói "a scenery" hay "sceneries".', '{"term":"scenery","ipa":"/ˈsinəri/","part_of_speech":"noun","meaning_vi":"phong cảnh","example":"The scenery on the road to Hà Giang made me wish you were next to me.","example_vi":"Phong cảnh trên đường lên Hà Giang làm em ước gì có anh ngồi bên cạnh."}'::jsonb),
  ('vocab-b1-travel-08', 'vocab-b1-travel-places', 8, 'multiple_choice', 'B1', 'Use ''crowded'' to describe a place', 'The beach was so ___ on the holiday that we couldn''t find a place to sit.', 'Bãi biển ___ vào ngày lễ đến mức tụi mình không tìm được chỗ ngồi.', '["crowded","quiet","empty","peaceful"]'::jsonb, null, null, null, null, 'crowded', '["crowded"]'::jsonb, 'Crowded means full of people. If you couldn''t find a place to sit, the beach had too many people.', '"Crowded" nghĩa là đông người, chật kín. Không tìm được chỗ ngồi tức là quá đông, nên chọn "crowded".', '{"term":"crowded","ipa":"/ˈkraʊdɪd/","part_of_speech":"adjective","meaning_vi":"đông đúc","example":"Let''s visit the night market on a weekday when it''s less crowded.","example_vi":"Mình đi chợ đêm vào ngày thường nha, lúc đó đỡ đông hơn."}'::jsonb),
  ('vocab-b1-travel-09', 'vocab-b1-travel-places', 9, 'multiple_choice', 'B1', 'Recognize the Vietnamese meaning of ''delayed''', 'Choose the Vietnamese meaning of ''delayed'' in "My flight is delayed."', 'Chọn nghĩa tiếng Việt của ''delayed'' trong câu "My flight is delayed."', '["bị hoãn, bị trễ","bị hủy","đã cất cánh","đã đầy chỗ"]'::jsonb, null, null, null, null, 'delayed', '["bị hoãn, bị trễ"]'::jsonb, 'Delayed means later than planned. A delayed flight still leaves, just late; a cancelled flight does not leave at all.', '"Delayed" là bị trễ, bị hoãn so với giờ dự kiến. Chuyến bay "delayed" vẫn bay nhưng trễ; còn "cancelled" mới là bị hủy.', '{"term":"delayed","ipa":"/dɪˈleɪd/","part_of_speech":"adjective","meaning_vi":"bị trễ, bị hoãn","example":"My train is delayed by an hour, so I''ll call you from the station.","example_vi":"Tàu của em bị trễ một tiếng, nên em sẽ gọi cho anh từ nhà ga nha."}'::jsonb),
  ('vocab-b1-travel-10', 'vocab-b1-travel-places', 10, 'multiple_choice', 'B1', 'Use ''explore'' in context', 'When you visit me, I want to ___ the old town with you and find all the hidden cafés.', 'Khi anh sang thăm, em muốn cùng anh ___ khu phố cổ và tìm hết mấy quán cà phê ẩn mình.', '["explore","arrive","return","stay"]'::jsonb, null, null, null, null, 'explore', '["explore"]'::jsonb, 'To explore means to travel around a place to discover it. "Explore the old town" is a very natural phrase.', '"Explore" là khám phá, đi quanh một nơi để tìm hiểu nó. "Explore the old town" là cách nói rất tự nhiên. Các từ khác không đi trực tiếp với "the old town" theo nghĩa này.', '{"term":"explore","ipa":"/ɪkˈsplɔr/","part_of_speech":"verb","meaning_vi":"khám phá","example":"We spent the whole afternoon exploring the little streets near the river.","example_vi":"Tụi mình dành cả buổi chiều khám phá mấy con phố nhỏ gần sông."}'::jsonb),
  ('vocab-b2-future-01', 'vocab-b2-plans-future', 1, 'multiple_choice', 'B2', 'Use ''look forward to'' in context', 'I''m really looking forward ___ you at the airport next month.', 'Em rất mong ___ anh ở sân bay vào tháng sau.', '["to seeing","to see","seeing","for seeing"]'::jsonb, null, null, null, null, 'look forward to', '["to seeing"]'::jsonb, 'In "look forward to", "to" is a preposition, so it is followed by a noun or a verb + -ing: look forward to seeing you.', 'Trong "look forward to", "to" là giới từ, nên theo sau là danh từ hoặc động từ thêm -ing: "look forward to seeing you". Lỗi rất hay gặp là "look forward to see".', '{"term":"look forward to","ipa":"/lʊk ˈfɔrwərd tu/","part_of_speech":"phrase","meaning_vi":"mong chờ, háo hức đợi","example":"I look forward to our video call every single night.","example_vi":"Tối nào anh cũng mong chờ cuộc gọi video của tụi mình."}'::jsonb),
  ('vocab-b2-future-02', 'vocab-b2-plans-future', 2, 'multiple_choice', 'B2', 'Understand the meaning of ''eventually''', 'What does ''eventually'' mean in "We will eventually live in the same city"?', '''eventually'' nghĩa là gì trong câu "We will eventually live in the same city"?', '["In the end, after some time","Maybe, but probably not","Immediately, right now","Every now and then"]'::jsonb, null, null, null, null, 'eventually', '["In the end, after some time"]'::jsonb, 'Eventually means in the end, after a long time or after many steps. It does not mean "possibly" or "maybe".', '"Eventually" là cuối cùng thì, sau một thời gian. Nhiều người hiểu lầm là "có lẽ" hay "có thể", nhưng thật ra nó nói về điều chắc chắn sẽ xảy ra về sau.', '{"term":"eventually","ipa":"/ɪˈvɛntʃuəli/","part_of_speech":"adverb","meaning_vi":"cuối cùng thì, rốt cuộc","example":"The distance is hard now, but eventually we''ll be together every day.","example_vi":"Bây giờ xa nhau thì khó, nhưng rồi cuối cùng tụi mình sẽ được bên nhau mỗi ngày."}'::jsonb),
  ('vocab-b2-future-03', 'vocab-b2-plans-future', 3, 'multiple_choice', 'B2', 'Use ''settle down'' in context', 'After a few years of travelling, they want to ___ and buy a small house.', 'Sau vài năm đi đây đi đó, họ muốn ___ và mua một căn nhà nhỏ.', '["settle down","break down","slow down","turn down"]'::jsonb, null, null, null, null, 'settle down', '["settle down"]'::jsonb, 'To settle down means to start living a calm, stable life in one place, often with a partner. "Break down" means stop working, and "turn down" means refuse.', '"Settle down" là ổn định cuộc sống, an cư ở một nơi, thường cùng người mình yêu. "Break down" là hỏng, "turn down" là từ chối, "slow down" là chậm lại.', '{"term":"settle down","ipa":"/ˌsɛtəl ˈdaʊn/","part_of_speech":"phrase","meaning_vi":"ổn định cuộc sống, an cư","example":"Where do you want to settle down: by the sea or in the mountains?","example_vi":"Em muốn an cư ở đâu: gần biển hay trên núi?"}'::jsonb),
  ('vocab-b2-future-04', 'vocab-b2-plans-future', 4, 'multiple_choice', 'B2', 'Use ''figure out'' in context', 'We still need to ___ how to see each other more often without spending too much money.', 'Tụi mình vẫn cần ___ cách gặp nhau thường xuyên hơn mà không tốn quá nhiều tiền.', '["figure out","give up","put off","run out"]'::jsonb, null, null, null, null, 'figure out', '["figure out"]'::jsonb, 'To figure out means to think about something until you find the answer or solution. It is often followed by how, what, or why.', '"Figure out" là tìm ra, nghĩ ra cách giải quyết. Hay đi với how/what/why: "figure out how to...". "Give up" là bỏ cuộc, "put off" là hoãn lại, "run out" là hết.', '{"term":"figure out","ipa":"/ˌfɪɡjər ˈaʊt/","part_of_speech":"phrase","meaning_vi":"tìm ra, nghĩ ra","example":"Don''t worry, we''ll figure it out together.","example_vi":"Đừng lo, tụi mình sẽ cùng nhau tìm ra cách."}'::jsonb),
  ('vocab-b2-future-05', 'vocab-b2-plans-future', 5, 'multiple_choice', 'B2', 'Understand the meaning of ''in the long run''', 'What does ''in the long run'' mean?', '''in the long run'' nghĩa là gì?', '["Over a long period of time in the future","During a long journey","While running a long distance","Very quickly and suddenly"]'::jsonb, null, null, null, null, 'in the long run', '["Over a long period of time in the future"]'::jsonb, 'In the long run means when you think about the distant future, not just now. "It''s hard now, but it''s worth it in the long run."', '"In the long run" là về lâu dài, khi nhìn xa về tương lai. Ví dụ: "Bây giờ thì vất vả, nhưng về lâu dài thì đáng."', '{"term":"in the long run","ipa":"/ɪn ðə ˈlɔŋ ˌrʌn/","part_of_speech":"phrase","meaning_vi":"về lâu dài","example":"Saving money now will help us a lot in the long run.","example_vi":"Tiết kiệm tiền bây giờ sẽ giúp tụi mình rất nhiều về lâu dài."}'::jsonb),
  ('vocab-b2-future-06', 'vocab-b2-plans-future', 6, 'multiple_choice', 'B2', 'Use ''postpone'' in context', 'The airline cancelled our flight, so we had to ___ the trip until next month.', 'Hãng bay hủy chuyến của tụi mình, nên tụi mình phải ___ chuyến đi đến tháng sau.', '["postpone","prepare","confirm","celebrate"]'::jsonb, null, null, null, null, 'postpone', '["postpone"]'::jsonb, 'To postpone means to move an event to a later time. The words "until next month" show the trip was delayed, not cancelled.', '"Postpone" là hoãn lại, dời sang thời điểm sau. Cụm "until next month" (đến tháng sau) cho biết chuyến đi bị dời chứ không bị hủy.', '{"term":"postpone","ipa":"/poʊstˈpoʊn/","part_of_speech":"verb","meaning_vi":"hoãn lại, dời lại","example":"Let''s not postpone our dream trip again. Let''s book it this week!","example_vi":"Mình đừng hoãn chuyến đi mơ ước nữa. Tuần này đặt luôn đi!"}'::jsonb),
  ('vocab-b2-future-07', 'vocab-b2-plans-future', 7, 'multiple_choice', 'B2', 'Recognize the Vietnamese meaning of ''save up''', 'Choose the Vietnamese meaning of ''save up'' in "I''m saving up for a plane ticket."', 'Chọn nghĩa tiếng Việt của ''save up'' trong câu "I''m saving up for a plane ticket."', '["để dành tiền","tiêu hết tiền","vay tiền","đổi tiền"]'::jsonb, null, null, null, null, 'save up', '["để dành tiền"]'::jsonb, 'To save up means to keep money little by little so you can buy something later. We say "save up for something".', '"Save up" là để dành tiền dần dần để mua thứ gì đó sau này. Cấu trúc: "save up for + thứ muốn mua".', '{"term":"save up","ipa":"/ˌseɪv ˈʌp/","part_of_speech":"phrase","meaning_vi":"để dành tiền, tiết kiệm","example":"We''re both saving up so we can travel to Japan together.","example_vi":"Cả hai tụi mình đang để dành tiền để cùng đi Nhật."}'::jsonb),
  ('vocab-b2-future-08', 'vocab-b2-plans-future', 8, 'multiple_choice', 'B2', 'Use ''reunite'' in context', 'After eight months apart, the couple was finally ___ at the airport.', 'Sau tám tháng xa cách, cặp đôi cuối cùng cũng được ___ ở sân bay.', '["reunited","separated","postponed","delayed"]'::jsonb, null, null, null, null, 'reunite', '["reunited"]'::jsonb, 'To reunite means to bring people together again after a time apart. "Finally" and "after eight months apart" show a happy meeting.', '"Reunite" là đoàn tụ, gặp lại nhau sau thời gian xa cách. "Finally" và "sau tám tháng xa cách" cho thấy đây là cuộc gặp lại vui vẻ.', '{"term":"reunite","ipa":"/ˌrijuˈnaɪt/","part_of_speech":"verb","meaning_vi":"đoàn tụ, gặp lại","example":"I keep imagining the moment we reunite at the arrival gate.","example_vi":"Em cứ tưởng tượng mãi khoảnh khắc tụi mình gặp lại nhau ở cửa đến."}'::jsonb),
  ('vocab-b2-future-09', 'vocab-b2-plans-future', 9, 'multiple_choice', 'B2', 'Understand the meaning of ''uncertain''', 'What does ''uncertain'' mean in "Our plans for next year are still uncertain"?', '''uncertain'' nghĩa là gì trong câu "Our plans for next year are still uncertain"?', '["Not decided or not known yet","Completely finished","Very exciting","Easy to change"]'::jsonb, null, null, null, null, 'uncertain', '["Not decided or not known yet"]'::jsonb, 'Uncertain means not sure or not decided. If plans are uncertain, we don''t know exactly what will happen yet.', '"Uncertain" là chưa chắc chắn, chưa quyết định được. Kế hoạch "uncertain" nghĩa là chưa biết rõ sẽ ra sao.', '{"term":"uncertain","ipa":"/ʌnˈsɜrtən/","part_of_speech":"adjective","meaning_vi":"không chắc chắn, chưa rõ","example":"The future feels uncertain sometimes, but I''m sure about you.","example_vi":"Đôi khi tương lai có vẻ chưa rõ ràng, nhưng anh chắc chắn về em."}'::jsonb),
  ('vocab-b2-future-10', 'vocab-b2-plans-future', 10, 'multiple_choice', 'B2', 'Use ''make up your mind'' in context', 'You have to ___ soon: do you want to visit me in June or in July?', 'Anh phải ___ sớm nha: anh muốn sang thăm em vào tháng Sáu hay tháng Bảy?', '["make up your mind","make up a story","change the subject","take your time"]'::jsonb, null, null, null, null, 'make up your mind', '["make up your mind"]'::jsonb, 'To make up your mind means to decide. The sentence asks for a choice between two months, so a decision is needed.', '"Make up your mind" là quyết định, chọn dứt khoát. Câu hỏi bắt phải chọn giữa hai tháng nên cần quyết định. "Take your time" (cứ từ từ) mâu thuẫn với "soon".', '{"term":"make up your mind","ipa":"/ˌmeɪk ʌp jər ˈmaɪnd/","part_of_speech":"phrase","meaning_vi":"quyết định","example":"I''ve made up my mind: I''m moving to your city next year.","example_vi":"Em quyết định rồi: năm sau em sẽ chuyển đến thành phố của anh."}'::jsonb),
  ('vocab-b2-work-01', 'vocab-b2-study-work', 1, 'multiple_choice', 'B2', 'Use ''deadline'' in context', 'I can''t call tonight. The ___ for my report is tomorrow at nine a.m.', 'Tối nay em không gọi được. ___ nộp báo cáo của em là chín giờ sáng mai.', '["deadline","workload","promotion","feedback"]'::jsonb, null, null, null, null, 'deadline', '["deadline"]'::jsonb, 'A deadline is the latest time by which something must be finished. We meet a deadline or miss a deadline.', '"Deadline" là hạn chót phải hoàn thành việc gì đó. Hay dùng: "meet a deadline" (kịp hạn) và "miss a deadline" (trễ hạn).', '{"term":"deadline","ipa":"/ˈdɛdˌlaɪn/","part_of_speech":"noun","meaning_vi":"hạn chót","example":"Once I meet this deadline, the whole weekend is yours.","example_vi":"Xong hạn chót này là cả cuối tuần anh dành cho em."}'::jsonb),
  ('vocab-b2-work-02', 'vocab-b2-study-work', 2, 'multiple_choice', 'B2', 'Understand the meaning of ''colleague''', 'What does ''colleague'' mean?', '''colleague'' nghĩa là gì?', '["A person you work with","A person who teaches at a college","A person who is looking for a job","A person who owns a company"]'::jsonb, null, null, null, null, 'colleague', '["A person you work with"]'::jsonb, 'A colleague is someone you work with, usually in the same company or profession. Don''t confuse it with "college".', '"Colleague" là đồng nghiệp, người làm việc cùng bạn. Đừng nhầm với "college" (trường cao đẳng/đại học). Chú ý cách đọc: /ˈkɑliɡ/.', '{"term":"colleague","ipa":"/ˈkɑliɡ/","part_of_speech":"noun","meaning_vi":"đồng nghiệp","example":"One of my colleagues also has a long-distance partner, so we share tips.","example_vi":"Một đồng nghiệp của em cũng yêu xa, nên tụi em hay chia sẻ bí quyết với nhau."}'::jsonb),
  ('vocab-b2-work-03', 'vocab-b2-study-work', 3, 'multiple_choice', 'B2', 'Use ''promotion'' in context', 'After two years of hard work, she finally got a ___ to team leader.', 'Sau hai năm làm việc chăm chỉ, cuối cùng cô ấy cũng được ___ lên trưởng nhóm.', '["promotion","deadline","qualification","internship"]'::jsonb, null, null, null, null, 'promotion', '["promotion"]'::jsonb, 'A promotion is a move to a higher position at work. We say "get a promotion to + position".', '"Promotion" là sự thăng chức. Cấu trúc: "get a promotion to + vị trí". Chú ý "promotion" cũng có nghĩa là khuyến mãi trong mua sắm.', '{"term":"promotion","ipa":"/prəˈmoʊʃən/","part_of_speech":"noun","meaning_vi":"sự thăng chức","example":"Congratulations on your promotion! I''m so proud of you.","example_vi":"Chúc mừng anh được thăng chức! Em tự hào về anh lắm."}'::jsonb),
  ('vocab-b2-work-04', 'vocab-b2-study-work', 4, 'multiple_choice', 'B2', 'Understand the meaning of ''internship''', 'What does ''internship'' mean?', '''internship'' nghĩa là gì?', '["A short period of work, often for students, to gain experience","A job you do from home on the internet","A course you take to become a doctor","A meeting between a manager and a new worker"]'::jsonb, null, null, null, null, 'internship', '["A short period of work, often for students, to gain experience"]'::jsonb, 'An internship is a temporary job, usually for students or new graduates, where they learn and gain real work experience.', '"Internship" là kỳ thực tập, thường dành cho sinh viên hoặc người mới ra trường để học hỏi và lấy kinh nghiệm.', '{"term":"internship","ipa":"/ˈɪntɜrnˌʃɪp/","part_of_speech":"noun","meaning_vi":"kỳ thực tập","example":"I''m applying for a summer internship at a design company.","example_vi":"Em đang nộp đơn thực tập hè ở một công ty thiết kế."}'::jsonb),
  ('vocab-b2-work-05', 'vocab-b2-study-work', 5, 'multiple_choice', 'B2', 'Use ''workload'' in context', 'My ___ is really heavy this month, so I might reply to your messages late.', '___ của anh tháng này nặng lắm, nên có thể anh sẽ trả lời tin nhắn của em trễ.', '["workload","colleague","internship","salary"]'::jsonb, null, null, null, null, 'workload', '["workload"]'::jsonb, 'Workload is the amount of work you have to do. We often describe it as heavy or light.', '"Workload" là khối lượng công việc. Thường đi với "heavy" (nặng) hoặc "light" (nhẹ). "Salary" (lương) không đi với "heavy" theo nghĩa này.', '{"term":"workload","ipa":"/ˈwɜrkˌloʊd/","part_of_speech":"noun","meaning_vi":"khối lượng công việc","example":"When your workload is too heavy, remember to take short breaks.","example_vi":"Khi khối lượng công việc quá nhiều, nhớ nghỉ giải lao một chút nha."}'::jsonb),
  ('vocab-b2-work-06', 'vocab-b2-study-work', 6, 'multiple_choice', 'B2', 'Recognize the Vietnamese meaning of ''qualification''', 'Choose the Vietnamese meaning of ''qualification''.', 'Chọn nghĩa tiếng Việt của ''qualification''.', '["bằng cấp, chứng chỉ","kinh nghiệm làm việc","buổi phỏng vấn","hợp đồng lao động"]'::jsonb, null, null, null, null, 'qualification', '["bằng cấp, chứng chỉ"]'::jsonb, 'A qualification is a degree or certificate you get after finishing a course or passing an exam, like an English certificate.', '"Qualification" là bằng cấp, chứng chỉ bạn nhận được sau khi học xong hoặc thi đậu, ví dụ chứng chỉ tiếng Anh.', '{"term":"qualification","ipa":"/ˌkwɑləfəˈkeɪʃən/","part_of_speech":"noun","meaning_vi":"bằng cấp, chứng chỉ","example":"An English qualification could help me find a job in your city.","example_vi":"Một chứng chỉ tiếng Anh có thể giúp em tìm được việc ở thành phố của anh."}'::jsonb),
  ('vocab-b2-work-07', 'vocab-b2-study-work', 7, 'multiple_choice', 'B2', 'Use ''collaborate'' in context', 'Our two teams ___ on the project, so we share ideas every day.', 'Hai nhóm của tụi mình ___ trong dự án này, nên ngày nào cũng chia sẻ ý tưởng.', '["collaborate","compete","resign","retire"]'::jsonb, null, null, null, null, 'collaborate', '["collaborate"]'::jsonb, 'To collaborate means to work together with others to achieve something. Sharing ideas every day shows teamwork, not competition.', '"Collaborate" là hợp tác, cùng làm việc với nhau. Chia sẻ ý tưởng mỗi ngày là hợp tác, không phải cạnh tranh ("compete"). Cấu trúc: "collaborate on a project".', '{"term":"collaborate","ipa":"/kəˈlæbəˌreɪt/","part_of_speech":"verb","meaning_vi":"hợp tác, cộng tác","example":"We collaborate like a real team, even when we plan our trips.","example_vi":"Tụi mình hợp tác như một đội thật sự, kể cả khi lên kế hoạch du lịch."}'::jsonb),
  ('vocab-b2-work-08', 'vocab-b2-study-work', 8, 'multiple_choice', 'B2', 'Understand the meaning of ''procrastinate''', 'What does ''procrastinate'' mean?', '''procrastinate'' nghĩa là gì?', '["To keep delaying something you should do","To finish work earlier than expected","To work extra hours at night","To ask someone else to do your work"]'::jsonb, null, null, null, null, 'procrastinate', '["To keep delaying something you should do"]'::jsonb, 'To procrastinate means to keep putting off a task, often by doing something easier or more fun instead.', '"Procrastinate" là trì hoãn, cứ để việc cần làm sang sau, thường vì làm việc khác dễ hoặc vui hơn. Giống kiểu "để mai tính".', '{"term":"procrastinate","ipa":"/proʊˈkræstəˌneɪt/","part_of_speech":"verb","meaning_vi":"trì hoãn, chần chừ","example":"Stop procrastinating and finish your essay. Then we can watch a movie together!","example_vi":"Đừng chần chừ nữa, viết xong bài luận đi. Rồi mình cùng xem phim!"}'::jsonb),
  ('vocab-b2-work-09', 'vocab-b2-study-work', 9, 'multiple_choice', 'B2', 'Use ''feedback'' in context', 'My manager gave me some useful ___ on my presentation, so I''ll improve it before Friday.', 'Quản lý đã cho em vài ___ hữu ích về bài thuyết trình, nên em sẽ sửa lại trước thứ Sáu.', '["feedback","deadline","colleague","promotion"]'::jsonb, null, null, null, null, 'feedback', '["feedback"]'::jsonb, 'Feedback is comments or advice about how well you did something. It is uncountable: "some feedback", not "a feedback".', '"Feedback" là nhận xét, góp ý về việc bạn đã làm. Đây là danh từ không đếm được: nói "some feedback" hoặc "a piece of feedback", không nói "a feedback" hay "feedbacks".', '{"term":"feedback","ipa":"/ˈfidˌbæk/","part_of_speech":"noun","meaning_vi":"nhận xét, góp ý","example":"Can you give me some feedback on my English pronunciation?","example_vi":"Anh góp ý giúp em về cách phát âm tiếng Anh của em được không?"}'::jsonb),
  ('vocab-b2-work-10', 'vocab-b2-study-work', 10, 'multiple_choice', 'B2', 'Use ''submit'' in context', 'You have to ___ your application online before the end of the month.', 'Bạn phải ___ đơn ứng tuyển trực tuyến trước cuối tháng.', '["submit","receive","collaborate","procrastinate"]'::jsonb, null, null, null, null, 'submit', '["submit"]'::jsonb, 'To submit means to formally give a document, form or piece of work to someone so they can check it or decide on it.', '"Submit" là nộp (hồ sơ, bài tập, đơn từ) một cách chính thức. "Receive" là nhận, ngược nghĩa với người nộp đơn.', '{"term":"submit","ipa":"/səbˈmɪt/","part_of_speech":"verb","meaning_vi":"nộp","example":"I just submitted my visa application. Fingers crossed!","example_vi":"Em vừa nộp hồ sơ xin visa. Cầu mong mọi thứ suôn sẻ!"}'::jsonb),
  ('grammar-a1-articles-01', 'grammar-a1-articles', 1, 'multiple_choice', 'A1', 'Use an before a vowel sound', 'I have ___ idea for our next video date.', 'Em có ___ ý tưởng cho buổi hẹn hò qua video lần tới.', '["an","a","no article"]'::jsonb, null, null, null, null, null, '["an"]'::jsonb, 'Use an before a vowel sound (a, e, i, o, u sounds): an idea, an apple. "Idea" is a singular countable noun, so it needs an article.', 'Dùng an trước từ bắt đầu bằng nguyên âm (âm a, e, i, o, u): an idea. Danh từ đếm được số ít luôn cần mạo từ — tiếng Việt không có mạo từ nên người Việt hay bỏ quên.', null),
  ('grammar-a1-articles-02', 'grammar-a1-articles', 2, 'multiple_choice', 'A1', 'Choose a/an by sound, not spelling', 'She is ___ university student.', 'Cô ấy là ___ sinh viên đại học.', '["a","an","no article"]'::jsonb, null, null, null, null, null, '["a"]'::jsonb, 'The choice depends on the sound, not the letter. "University" starts with a /j/ ("you") sound, which is a consonant sound, so we say a university.', 'Chọn a hay an dựa vào âm đầu, không phải chữ cái. "University" đọc là /juː/ (giống "you"), là phụ âm, nên dùng a: a university, a uniform.', null),
  ('grammar-a1-articles-03', 'grammar-a1-articles', 3, 'multiple_choice', 'A1', 'Use an before a silent h', 'We waited for ___ hour at the airport.', 'Tụi mình đã đợi ___ tiếng ở sân bay.', '["an","a","no article"]'::jsonb, null, null, null, null, null, '["an"]'::jsonb, 'In "hour" the h is silent, so the word starts with a vowel sound: an hour. Compare a house, where the h is pronounced.', 'Chữ h trong "hour" là âm câm, từ này bắt đầu bằng nguyên âm nên dùng an: an hour, an honest person. So sánh: a house (h được phát âm).', null),
  ('grammar-a1-articles-04', 'grammar-a1-articles', 4, 'multiple_choice', 'A1', 'Use the for something mentioned before', 'I bought a cake and a card for you. ___ cake was chocolate.', 'Em đã mua một cái bánh và một tấm thiệp cho anh. Cái bánh là vị sô-cô-la.', '["The","A","An"]'::jsonb, null, null, null, null, null, '["The"]'::jsonb, 'Use a / an the first time you mention something. When you talk about it again, both people know which one, so use the: a cake → the cake.', 'Lần đầu nhắc đến dùng a / an. Từ lần thứ hai trở đi, cả hai đã biết là cái nào nên dùng the — giống như nói "cái bánh đó" trong tiếng Việt.', null),
  ('grammar-a1-articles-05', 'grammar-a1-articles', 5, 'multiple_choice', 'A1', 'Use the for unique things', '___ sun is really hot in Sài Gòn today.', 'Hôm nay mặt trời ở Sài Gòn nóng thật.', '["The","A","No article"]'::jsonb, null, null, null, null, null, '["The"]'::jsonb, 'Use the for things that are unique — there is only one: the sun, the moon, the sky, the internet.', 'Dùng the với những thứ duy nhất: the sun, the moon, the sky, the internet. Vì chỉ có một nên ai cũng biết đang nói về cái nào.', null),
  ('grammar-a1-articles-06', 'grammar-a1-articles', 6, 'multiple_choice', 'A1', 'Use no article for general uncountable nouns', 'I really love ___ music. It helps me relax.', 'Em thật sự rất thích âm nhạc. Nó giúp em thư giãn.', '["no article","a","an"]'::jsonb, null, null, null, null, null, '["no article"]'::jsonb, 'When we talk about something in general, uncountable nouns (music, love, coffee, time) take no article: I love music. A / an are only for singular countable nouns.', 'Khi nói chung chung, danh từ không đếm được (music, love, coffee, time) không dùng mạo từ: I love music. A / an chỉ đi với danh từ đếm được số ít.', null),
  ('grammar-a1-articles-07', 'grammar-a1-articles', 7, 'multiple_choice', 'A1', 'Use a/an with jobs', 'Which sentence about a job is correct?', 'Câu nào nói về nghề nghiệp là đúng?', '["My partner is a nurse.","My partner is nurse.","My partner is an nurse.","My partner is the nurses."]'::jsonb, null, null, null, null, null, '["My partner is a nurse."]'::jsonb, 'When we say someone''s job, English needs a / an: She is a nurse. He is an engineer. Leaving it out ("is nurse") is one of the most common mistakes for Vietnamese speakers.', 'Khi nói nghề nghiệp, tiếng Anh bắt buộc có a / an: She is a nurse, He is an engineer. Tiếng Việt nói "Cô ấy là y tá" không có mạo từ, nên đây là lỗi rất phổ biến của người Việt.', null),
  ('grammar-a1-articles-08', 'grammar-a1-articles', 8, 'multiple_choice', 'A1', 'Know fixed phrases with no article', 'Which sentence about bedtime is correct?', 'Câu nào về giờ đi ngủ là đúng?', '["I usually go to bed at 11 p.m.","I usually go to the bed at 11 p.m.","I usually go to a bed at 11 p.m."]'::jsonb, null, null, null, null, null, '["I usually go to bed at 11 p.m."]'::jsonb, 'Some common phrases use no article: go to bed, go to work, go home, at night, by bus. "Go to bed" means "go to sleep".', 'Một số cụm cố định không dùng mạo từ: go to bed, go to work, go home, at night, by bus. Nên học thuộc cả cụm. "Go to bed" nghĩa là đi ngủ.', null),
  ('grammar-a1-articles-09', 'grammar-a1-articles', 9, 'multiple_choice', 'A1', 'Use no a/an with plural nouns', 'I bought ___ new shoes for our trip.', 'Em đã mua giày mới cho chuyến đi của tụi mình.', '["no article","a","an"]'::jsonb, null, null, null, null, null, '["no article"]'::jsonb, 'A / an means "one", so it never goes with plural nouns. "Shoes" is plural, so we say: I bought new shoes (or some new shoes).', 'A / an có nghĩa là "một", nên không bao giờ đi với danh từ số nhiều. "Shoes" là số nhiều nên không dùng a: I bought new shoes.', null),
  ('grammar-a1-articles-10', 'grammar-a1-articles', 10, 'multiple_choice', 'A1', 'Use the with superlatives', 'Seeing you at the airport was ___ best moment of my year!', 'Gặp anh ở sân bay là khoảnh khắc tuyệt nhất trong năm của em!', '["the","a","no article"]'::jsonb, null, null, null, null, null, '["the"]'::jsonb, 'Superlatives (best, biggest, most beautiful) use the, because there is only one "best": the best moment, the happiest day.', 'So sánh nhất (best, biggest, most beautiful) luôn đi với the, vì chỉ có một cái "nhất": the best moment, the happiest day.', null),
  ('grammar-a1-be-present-01', 'grammar-a1-be-present-simple', 1, 'multiple_choice', 'A1', 'Add -s to the verb after he/she/it', 'She ___ to work every day.', 'Cô ấy ___ đi làm mỗi ngày.', '["goes","go","going","is go"]'::jsonb, null, null, null, null, null, '["goes"]'::jsonb, 'In the present simple, verbs after he / she / it take -s or -es: she goes, he works, it rains. "Is go" is wrong because we don''t put "to be" before a normal verb in the present simple.', 'Ở thì hiện tại đơn, động từ sau he / she / it phải thêm -s hoặc -es: she goes, he works. Tiếng Việt không chia động từ nên người Việt hay quên đuôi -s. Cũng đừng ghép "is" với động từ thường ("is go" là sai).', null),
  ('grammar-a1-be-present-02', 'grammar-a1-be-present-simple', 2, 'multiple_choice', 'A1', 'Use does in questions with he/she/it', '___ he live in Đà Nẵng?', 'Anh ấy có sống ở Đà Nẵng không?', '["Does","Do","Is","Are"]'::jsonb, null, null, null, null, null, '["Does"]'::jsonb, 'Questions with a normal verb use do / does. With he / she / it we use does, and the main verb goes back to the base form: Does he live…? (not Does he lives…?).', 'Câu hỏi với động từ thường dùng do / does. Với he / she / it dùng does, và động từ chính trở về nguyên mẫu: Does he live…? Không dùng "Is he live…?" vì "live" là động từ thường, không phải "to be".', null),
  ('grammar-a1-be-present-03', 'grammar-a1-be-present-simple', 3, 'multiple_choice', 'A1', 'Use am with I', 'I ___ so happy when we talk on video.', 'Em ___ rất vui khi tụi mình gọi video.', '["am","is","are","be"]'::jsonb, null, null, null, null, null, '["am"]'::jsonb, 'The verb "to be" changes with the subject: I am, he / she / it is, you / we / they are. "Be" alone is the base form and is not used after I here.', 'Động từ "to be" thay đổi theo chủ ngữ: I am, he / she / it is, you / we / they are. Người Việt hay bỏ "to be" trước tính từ ("I happy"), nhưng tiếng Anh bắt buộc phải có: I am happy.', null),
  ('grammar-a1-be-present-04', 'grammar-a1-be-present-simple', 4, 'multiple_choice', 'A1', 'Make negatives with doesn''t', 'Linh ___ coffee. She drinks tea.', 'Linh ___ cà phê. Cô ấy uống trà.', '["doesn''t like","don''t like","not like","isn''t like"]'::jsonb, null, null, null, null, null, '["doesn''t like"]'::jsonb, 'Negatives with a normal verb use don''t / doesn''t + base verb. Linh = she, so we use doesn''t: She doesn''t like coffee.', 'Câu phủ định với động từ thường dùng don''t / doesn''t + động từ nguyên mẫu. Linh là "she" nên dùng doesn''t. Không thể chỉ thêm "not" như tiếng Việt thêm "không" ("not like" là sai).', null),
  ('grammar-a1-be-present-05', 'grammar-a1-be-present-simple', 5, 'multiple_choice', 'A1', 'Spell -es after verbs ending in -ch', 'Which sentence about a weekly habit is correct?', 'Câu nào về một thói quen hằng tuần là đúng?', '["He watches movies on Sundays.","He watch movies on Sundays.","He watchs movies on Sundays.","He is watch movies on Sundays."]'::jsonb, null, null, null, null, null, '["He watches movies on Sundays."]'::jsonb, 'Verbs ending in -ch, -sh, -s, -x or -o add -es after he / she / it: watches, washes, goes. So "watchs" is a spelling mistake, and "watch" is missing the ending.', 'Động từ tận cùng bằng -ch, -sh, -s, -x, -o thì thêm -es với he / she / it: watches, washes, goes. "Watchs" sai chính tả, còn "watch" thiếu đuôi.', null),
  ('grammar-a1-be-present-06', 'grammar-a1-be-present-simple', 6, 'multiple_choice', 'A1', 'Use are with we', 'We ___ in different cities, but we talk every day.', 'Tụi mình ___ ở hai thành phố khác nhau, nhưng ngày nào cũng nói chuyện.', '["are","is","am","be"]'::jsonb, null, null, null, null, null, '["are"]'::jsonb, 'With we, you and they, the verb "to be" is are: We are in different cities.', 'Với we, you, they thì "to be" là are. Câu này nói về vị trí (ở đâu) nên cần "to be": We are in different cities.', null),
  ('grammar-a1-be-present-07', 'grammar-a1-be-present-simple', 7, 'multiple_choice', 'A1', 'Use do in questions with you', 'Where ___ you work?', 'Anh làm việc ở đâu?', '["do","does","are","is"]'::jsonb, null, null, null, null, null, '["do"]'::jsonb, 'Wh- questions with a normal verb follow this pattern: question word + do / does + subject + base verb. With you, use do: Where do you work?', 'Câu hỏi Wh- với động từ thường: từ để hỏi + do / does + chủ ngữ + động từ nguyên mẫu. Với "you" dùng do. "Where are you work?" là lỗi rất phổ biến vì trộn "to be" với động từ thường.', null),
  ('grammar-a1-be-present-08', 'grammar-a1-be-present-simple', 8, 'multiple_choice', 'A1', 'Use -s with a singular noun subject', 'The time difference sometimes ___ our calls difficult.', 'Chênh lệch múi giờ đôi khi ___ các cuộc gọi của tụi mình khó khăn.', '["makes","make","making","is make"]'::jsonb, null, null, null, null, null, '["makes"]'::jsonb, '"The time difference" is one thing, so it works like "it": it makes. Any singular noun subject needs the -s verb in the present simple.', '"The time difference" là danh từ số ít, tương đương "it", nên động từ phải thêm -s: makes. Quy tắc thêm -s áp dụng cho mọi chủ ngữ số ít, không chỉ he / she / it.', null),
  ('grammar-a1-be-present-09', 'grammar-a1-be-present-simple', 9, 'multiple_choice', 'A1', 'Make questions with "to be"', '___ your sister a student?', 'Em gái anh là sinh viên phải không?', '["Is","Does","Are","Do"]'::jsonb, null, null, null, null, null, '["Is"]'::jsonb, 'When the sentence uses "to be" (with a noun or adjective, no other verb), we make a question by moving am / is / are to the front: Your sister is a student → Is your sister a student?', 'Khi câu dùng "to be" (không có động từ thường), ta đảo am / is / are lên đầu để hỏi. "Your sister" là số ít nên dùng Is. Không dùng do / does với "to be".', null),
  ('grammar-a1-be-present-10', 'grammar-a1-be-present-simple', 10, 'multiple_choice', 'A1', 'Use the base verb after does', 'Which question is correct?', 'Câu hỏi nào đúng?', '["Does she study English?","Does she studies English?","Do she study English?","Is she study English?"]'::jsonb, null, null, null, null, null, '["Does she study English?"]'::jsonb, 'After does, the -s moves to the helper verb, so the main verb has no -s: Does she study? Using both (does + studies) is a double mistake.', 'Khi đã có does thì đuôi -s "chuyển" sang does, động từ chính giữ nguyên mẫu: Does she study? Không được thêm -s hai lần (does … studies).', null),
  ('grammar-a2-past-simple-01', 'grammar-a2-past-simple', 1, 'multiple_choice', 'A2', 'Use an irregular past form', 'Yesterday I ___ you a long message.', 'Hôm qua em đã gửi cho anh một tin nhắn dài.', '["sent","send","sended","am send"]'::jsonb, null, null, null, null, null, '["sent"]'::jsonb, '"Send" is irregular: send → sent. Words like "yesterday" show finished past time, so the verb must change to the past form.', '"Send" là động từ bất quy tắc: send → sent. Tiếng Việt chỉ cần thêm "hôm qua" là đủ, nhưng tiếng Anh bắt buộc đổi động từ sang quá khứ.', null),
  ('grammar-a2-past-simple-02', 'grammar-a2-past-simple', 2, 'multiple_choice', 'A2', 'Add -ed to regular verbs', 'We ___ for two hours last night.', 'Tối qua tụi mình đã nói chuyện hai tiếng.', '["talked","talk","talks","talking"]'::jsonb, null, null, null, null, null, '["talked"]'::jsonb, 'Regular verbs make the past simple with -ed: talk → talked, call → called. The past form is the same for every subject (I / we / she talked).', 'Động từ có quy tắc thêm -ed: talk → talked. Ở quá khứ đơn, động từ giống nhau với mọi chủ ngữ — không cần thêm -s cho he / she / it.', null),
  ('grammar-a2-past-simple-03', 'grammar-a2-past-simple', 3, 'multiple_choice', 'A2', 'Use did in past questions', '___ you sleep well last night?', 'Tối qua anh ngủ ngon không?', '["Did","Do","Were","Are"]'::jsonb, null, null, null, null, null, '["Did"]'::jsonb, 'Past simple questions with a normal verb use did + subject + base verb: Did you sleep…? "Last night" tells us it is past, so "Do" is wrong.', 'Câu hỏi quá khứ với động từ thường: Did + chủ ngữ + động từ nguyên mẫu. Có "last night" nên phải dùng Did, không dùng Do.', null),
  ('grammar-a2-past-simple-04', 'grammar-a2-past-simple', 4, 'multiple_choice', 'A2', 'Use the base verb after didn''t', 'She didn''t ___ my call this morning.', 'Sáng nay cô ấy không nghe máy khi em gọi.', '["answer","answered","answers","answering"]'::jsonb, null, null, null, null, null, '["answer"]'::jsonb, 'After did / didn''t, always use the base verb. "Did" already shows the past, so we don''t put -ed on the main verb: didn''t answer (not didn''t answered).', 'Sau did / didn''t luôn dùng động từ nguyên mẫu. "Did" đã thể hiện quá khứ rồi nên không thêm -ed nữa: didn''t answer.', null),
  ('grammar-a2-past-simple-05', 'grammar-a2-past-simple', 5, 'multiple_choice', 'A2', 'Use the irregular past of go', 'Which sentence about last summer is correct?', 'Câu nào nói về mùa hè năm ngoái là đúng?', '["I went to Hà Nội last summer.","I go to Hà Nội last summer.","I goed to Hà Nội last summer.","I did went to Hà Nội last summer."]'::jsonb, null, null, null, null, null, '["I went to Hà Nội last summer."]'::jsonb, '"Go" is irregular: go → went. "Goed" does not exist, and in positive sentences we don''t use did with a past verb.', '"Go" là động từ bất quy tắc: go → went. Không có từ "goed". Câu khẳng định không dùng did kèm động từ quá khứ ("did went" là sai).', null),
  ('grammar-a2-past-simple-06', 'grammar-a2-past-simple', 6, 'multiple_choice', 'A2', 'Use the base verb in Wh- questions with did', 'Where did you ___ on your birthday?', 'Sinh nhật anh đã đi đâu?', '["go","went","goes","gone"]'::jsonb, null, null, null, null, null, '["go"]'::jsonb, 'In questions, did carries the past, and the main verb stays in the base form: Where did you go? (not Where did you went?).', 'Trong câu hỏi, did đã mang nghĩa quá khứ, động từ chính giữ nguyên mẫu: Where did you go? Lỗi "did you went" rất hay gặp.', null),
  ('grammar-a2-past-simple-07', 'grammar-a2-past-simple', 7, 'multiple_choice', 'A2', 'Use was with I', 'I ___ very tired after the long flight.', 'Em đã rất mệt sau chuyến bay dài.', '["was","were","am","did"]'::jsonb, null, null, null, null, null, '["was"]'::jsonb, 'The past of "to be" is was (I / he / she / it) and were (you / we / they). "Tired" is an adjective, so we need "to be": I was tired.', 'Quá khứ của "to be": was (I / he / she / it), were (you / we / they). "Tired" là tính từ nên cần "to be": I was tired.', null),
  ('grammar-a2-past-simple-08', 'grammar-a2-past-simple', 8, 'multiple_choice', 'A2', 'Make negatives with weren''t', 'They ___ at home last weekend.', 'Cuối tuần trước họ không ở nhà.', '["weren''t","wasn''t","didn''t","don''t"]'::jsonb, null, null, null, null, null, '["weren''t"]'::jsonb, 'To talk about where someone was, use "to be". With they, the past negative is weren''t. "Didn''t" needs a verb after it (didn''t stay).', 'Nói về việc ở đâu thì dùng "to be". Với they, phủ định quá khứ là weren''t. "Didn''t" phải đi kèm động từ thường (didn''t stay).', null),
  ('grammar-a2-past-simple-09', 'grammar-a2-past-simple', 9, 'multiple_choice', 'A2', 'Use the irregular past of buy', 'When he visited, he ___ me a beautiful bracelet.', 'Khi đến thăm, anh ấy đã mua cho em một chiếc vòng tay rất đẹp.', '["bought","buyed","buy","was buy"]'::jsonb, null, null, null, null, null, '["bought"]'::jsonb, '"Buy" is irregular: buy → bought. Both parts of the sentence are in the past (visited, bought).', '"Buy" là động từ bất quy tắc: buy → bought. Cả hai vế đều ở quá khứ (visited, bought). Không có từ "buyed".', null),
  ('grammar-a2-past-simple-10', 'grammar-a2-past-simple', 10, 'multiple_choice', 'A2', 'Use did in Wh- questions about the past', 'What time ___ your flight land yesterday?', 'Hôm qua chuyến bay của anh hạ cánh lúc mấy giờ?', '["did","was","were","do"]'::jsonb, null, null, null, null, null, '["did"]'::jsonb, '"Land" is a normal verb, so the past question needs did + base verb: What time did your flight land? "Was" cannot go with a base verb.', '"Land" là động từ thường nên câu hỏi quá khứ dùng did + nguyên mẫu. Không dùng "was" với động từ thường nguyên mẫu.', null),
  ('grammar-a2-prepositions-01', 'grammar-a2-prepositions-in-on-at', 1, 'multiple_choice', 'A2', 'Use in with months', 'My birthday is ___ May.', 'Sinh nhật em vào tháng Năm.', '["in","on","at"]'::jsonb, null, null, null, null, null, '["in"]'::jsonb, 'Use in for longer periods: months, years, seasons — in May, in 2025, in summer.', 'Dùng in cho khoảng thời gian dài: tháng, năm, mùa — in May, in 2025, in summer. Mẹo: in (dài) → on (ngày) → at (giờ, rất ngắn).', null),
  ('grammar-a2-prepositions-02', 'grammar-a2-prepositions-in-on-at', 2, 'multiple_choice', 'A2', 'Use on with days of the week', 'Let''s have a video call ___ Saturday.', 'Thứ Bảy mình gọi video nhé.', '["on","in","at"]'::jsonb, null, null, null, null, null, '["on"]'::jsonb, 'Use on for days and dates: on Saturday, on 14 February, on my birthday.', 'Dùng on cho thứ trong tuần và ngày cụ thể: on Saturday, on 14 February, on my birthday.', null),
  ('grammar-a2-prepositions-03', 'grammar-a2-prepositions-in-on-at', 3, 'multiple_choice', 'A2', 'Use at with clock times', 'I''ll call you ___ 9 p.m.', 'Em sẽ gọi cho anh lúc 9 giờ tối.', '["at","on","in"]'::jsonb, null, null, null, null, null, '["at"]'::jsonb, 'Use at for exact times: at 9 p.m., at noon, at midnight.', 'Dùng at cho giờ chính xác: at 9 p.m., at noon, at midnight.', null),
  ('grammar-a2-prepositions-04', 'grammar-a2-prepositions-in-on-at', 4, 'multiple_choice', 'A2', 'Use in with years', 'We met ___ 2023.', 'Tụi mình gặp nhau vào năm 2023.', '["in","on","at"]'::jsonb, null, null, null, null, null, '["in"]'::jsonb, 'Years take in: in 2023, in 1999.', 'Năm luôn đi với in: in 2023.', null),
  ('grammar-a2-prepositions-05', 'grammar-a2-prepositions-in-on-at', 5, 'multiple_choice', 'A2', 'Remember the fixed phrase at night', 'I always miss you more ___ night.', 'Ban đêm em luôn nhớ anh nhiều hơn.', '["at","in","on"]'::jsonb, null, null, null, null, null, '["at"]'::jsonb, 'We say in the morning, in the afternoon, in the evening — but at night (no "the").', 'Ta nói in the morning, in the afternoon, in the evening — nhưng at night (không có "the"). Đây là cụm cố định, nên học thuộc.', null),
  ('grammar-a2-prepositions-06', 'grammar-a2-prepositions-in-on-at', 6, 'multiple_choice', 'A2', 'Use in with cities and countries', 'She lives ___ Tokyo now.', 'Bây giờ cô ấy sống ở Tokyo.', '["in","at","on"]'::jsonb, null, null, null, null, null, '["in"]'::jsonb, 'Use in for cities, countries and other large areas: in Tokyo, in Vietnam, in Europe.', 'Dùng in cho thành phố, quốc gia, khu vực lớn: in Tokyo, in Vietnam. Tiếng Việt chỉ có một chữ "ở", nhưng tiếng Anh phải chọn in / on / at.', null),
  ('grammar-a2-prepositions-07', 'grammar-a2-prepositions-in-on-at', 7, 'multiple_choice', 'A2', 'Use at with a point or meeting place', 'Meet me ___ the bus stop.', 'Gặp em ở trạm xe buýt nhé.', '["at","in","on"]'::jsonb, null, null, null, null, null, '["at"]'::jsonb, 'Use at for a specific point or meeting place: at the bus stop, at the door, at the station.', 'Dùng at cho một điểm cụ thể, nơi hẹn gặp: at the bus stop, at the door, at the station.', null),
  ('grammar-a2-prepositions-08', 'grammar-a2-prepositions-in-on-at', 8, 'multiple_choice', 'A2', 'Use on for surfaces', 'Your photo is ___ the wall above my desk.', 'Ảnh của anh được treo trên tường phía trên bàn làm việc của em.', '["on","in","at"]'::jsonb, null, null, null, null, null, '["on"]'::jsonb, 'Use on for surfaces: on the wall, on the table, on the floor.', 'Dùng on cho bề mặt: on the wall, on the table, on the floor.', null),
  ('grammar-a2-prepositions-09', 'grammar-a2-prepositions-in-on-at', 9, 'multiple_choice', 'A2', 'Use on with a specific named day', 'We''ll finally be together ___ Christmas Day.', 'Cuối cùng tụi mình cũng được ở bên nhau vào ngày Giáng sinh.', '["on","in","at"]'::jsonb, null, null, null, null, null, '["on"]'::jsonb, '"Christmas Day" is one specific day, so it takes on — just like on Monday or on my birthday.', '"Christmas Day" là một ngày cụ thể nên dùng on, giống on Monday hay on my birthday.', null),
  ('grammar-a2-prepositions-10', 'grammar-a2-prepositions-in-on-at', 10, 'multiple_choice', 'A2', 'Use in with parts of the day', 'My plane will arrive ___ the morning.', 'Máy bay của em sẽ đến vào buổi sáng.', '["in","on","at"]'::jsonb, null, null, null, null, null, '["in"]'::jsonb, 'Parts of the day take in the: in the morning, in the afternoon, in the evening. (Remember the exception: at night.)', 'Các buổi trong ngày dùng in the: in the morning, in the afternoon, in the evening. Ngoại lệ cần nhớ: at night.', null),
  ('grammar-b1-conditionals-01', 'grammar-b1-conditionals', 1, 'multiple_choice', 'B1', 'Use the present simple in the if-clause of the first conditional', 'If it ___ tomorrow, we will stay home and watch a movie together on call.', 'Nếu mai trời mưa, tụi mình sẽ ở nhà và cùng xem phim qua cuộc gọi.', '["rains","will rain","rained","rain"]'::jsonb, null, null, null, null, null, '["rains"]'::jsonb, 'First conditional (a real possibility): If + present simple, will + base verb. We don''t use will in the if-part, even though the meaning is future.', 'Điều kiện loại 1 (có thể xảy ra): If + hiện tại đơn, will + V nguyên mẫu. Không dùng will trong vế if dù nghĩa là tương lai. "It" là số ít nên rain thêm -s.', null),
  ('grammar-b1-conditionals-02', 'grammar-b1-conditionals', 2, 'multiple_choice', 'B1', 'Use "If I were you" for advice', 'If I ___ you, I would book the ticket now.', 'Nếu em là anh, em sẽ đặt vé ngay bây giờ.', '["were","am","will be","be"]'::jsonb, null, null, null, null, null, '["were"]'::jsonb, '"If I were you, I would…" is the standard way to give advice. In the second conditional, standard English uses were for every subject, including I.', '"If I were you, I would…" là cách khuyên bảo rất phổ biến. Trong câu điều kiện loại 2, tiếng Anh chuẩn dùng were cho mọi chủ ngữ, kể cả I.', null),
  ('grammar-b1-conditionals-03', 'grammar-b1-conditionals', 3, 'multiple_choice', 'B1', 'Use would + base verb in the result of the second conditional', 'If I had wings, I ___ to you every night.', 'Nếu em có cánh, đêm nào em cũng sẽ bay đến bên anh.', '["would fly","will fly","fly","flew"]'::jsonb, null, null, null, null, null, '["would fly"]'::jsonb, 'Second conditional (imaginary): If + past simple, would + base verb. Having wings is not real, so we use would fly.', 'Điều kiện loại 2 (không có thật ở hiện tại): If + quá khứ đơn, would + V nguyên mẫu. Có cánh là điều không thật nên dùng would fly.', null),
  ('grammar-b1-conditionals-04', 'grammar-b1-conditionals', 4, 'multiple_choice', 'B1', 'Avoid will in the if-clause', 'If you ___ me tonight, I''ll answer right away.', 'Nếu tối nay anh gọi, em sẽ nghe máy ngay.', '["call","will call","called","would call"]'::jsonb, null, null, null, null, null, '["call"]'::jsonb, 'The result uses will (''ll), so this is a first conditional: the if-part uses the present simple — If you call me, I''ll answer.', 'Vế sau dùng will (''ll) nên đây là điều kiện loại 1: vế if dùng hiện tại đơn — If you call me, I''ll answer. Lỗi hay gặp là dùng will ở cả hai vế.', null),
  ('grammar-b1-conditionals-05', 'grammar-b1-conditionals', 5, 'multiple_choice', 'B1', 'Use the past simple in the if-clause of the second conditional', 'If we ___ in the same city, we would see each other every day.', 'Nếu tụi mình sống cùng một thành phố, ngày nào mình cũng gặp nhau.', '["lived","live","will live","would live"]'::jsonb, null, null, null, null, null, '["lived"]'::jsonb, 'The result uses would, so this is a second conditional about an imaginary present: If + past simple. "Lived" here does not mean the past — it means "not true now".', 'Vế sau có would nên đây là điều kiện loại 2, nói về điều không có thật ở hiện tại: If + quá khứ đơn. "Lived" ở đây không mang nghĩa quá khứ mà là "không đúng với hiện tại".', null),
  ('grammar-b1-conditionals-06', 'grammar-b1-conditionals', 6, 'multiple_choice', 'B1', 'Recognise a correct first conditional', 'Which sentence about next month''s visit is correct?', 'Câu nào về chuyến thăm tháng sau là đúng?', '["If I see you next month, I''ll hug you so tight.","If I will see you next month, I''ll hug you so tight.","If I saw you next month, I''ll hug you so tight.","If I see you next month, I would hugged you so tight."]'::jsonb, null, null, null, null, null, '["If I see you next month, I''ll hug you so tight."]'::jsonb, 'A real future plan uses the first conditional: If + present simple, will + base verb. Don''t use will after if, and don''t mix a past if-clause with will.', 'Kế hoạch có thật trong tương lai dùng điều kiện loại 1: If + hiện tại đơn, will + V nguyên mẫu. Không dùng will sau if, và không trộn vế if quá khứ với will.', null),
  ('grammar-b1-conditionals-07', 'grammar-b1-conditionals', 7, 'multiple_choice', 'B1', 'Use would be in the second conditional', 'I ___ much happier if you were here with me.', 'Em sẽ hạnh phúc hơn nhiều nếu anh ở đây với em.', '["would be","will be","am","were"]'::jsonb, null, null, null, null, null, '["would be"]'::jsonb, 'The if-part can come second. "If you were here" is imaginary (you are not here now), so the result needs would + base verb: I would be happier.', 'Vế if có thể đứng sau. "If you were here" là điều không có thật (anh đang không ở đây), nên vế kết quả dùng would + V nguyên mẫu: I would be happier.', null),
  ('grammar-b1-conditionals-08', 'grammar-b1-conditionals', 8, 'multiple_choice', 'B1', 'Use the second conditional in imaginary questions', 'What would you do if you ___ a whole free day with me?', 'Anh sẽ làm gì nếu có trọn một ngày rảnh bên em?', '["had","have","will have","would have"]'::jsonb, null, null, null, null, null, '["had"]'::jsonb, '"What would you do if…?" is a second-conditional question about an imaginary situation, so the if-part uses the past simple: if you had.', '"What would you do if…?" là câu hỏi điều kiện loại 2 về tình huống tưởng tượng, nên vế if dùng quá khứ đơn: if you had.', null),
  ('grammar-b1-conditionals-09', 'grammar-b1-conditionals', 9, 'multiple_choice', 'B1', 'Add -s in the if-clause with he/she/it', 'If she ___ the train, she''ll be late for our call.', 'Nếu cô ấy lỡ chuyến tàu, cô ấy sẽ trễ cuộc gọi của tụi mình.', '["misses","missed","will miss","would miss"]'::jsonb, null, null, null, null, null, '["misses"]'::jsonb, 'First conditional: If + present simple, will + base verb. With she, the present simple verb needs -es: If she misses the train…', 'Điều kiện loại 1: If + hiện tại đơn, will + V nguyên mẫu. Chủ ngữ là she nên động từ thêm -es: misses. Đừng quên đuôi -s ngay cả trong câu điều kiện.', null),
  ('grammar-b1-conditionals-10', 'grammar-b1-conditionals', 10, 'multiple_choice', 'B1', 'Tell the difference between real and imaginary conditions', 'Which sentence talks correctly about an imaginary situation (not true now)?', 'Câu nào diễn đạt đúng một tình huống tưởng tượng (không đúng ở hiện tại)?', '["If I had more time, I would learn to cook.","If I have more time, I will learn to cook.","If I had more time, I will learn to cook."]'::jsonb, null, null, null, null, null, '["If I had more time, I would learn to cook."]'::jsonb, 'Imaginary now = second conditional: If + past simple, would + base verb. "If I have…, I will…" is grammatical but describes a real possibility, and "had… will" mixes two patterns incorrectly.', 'Tình huống tưởng tượng ở hiện tại = điều kiện loại 2: If + quá khứ đơn, would + V. Câu "If I have…, I will…" đúng ngữ pháp nhưng nói về điều có thể xảy ra thật; câu "had… will" trộn sai hai cấu trúc.', null),
  ('grammar-b1-perfect-01', 'grammar-b1-present-perfect-past-simple', 1, 'multiple_choice', 'B1', 'Use the present perfect with since for a situation that continues', 'We ___ each other since 2022.', 'Tụi mình đã quen nhau từ năm 2022.', '["have known","knew","know","are knowing"]'::jsonb, null, null, null, null, null, '["have known"]'::jsonb, 'For a situation that started in the past and is still true now, use the present perfect (have / has + past participle), often with since or for. "Know" is a state verb, so it is not used in the -ing form.', 'Việc bắt đầu trong quá khứ và vẫn còn đến bây giờ dùng hiện tại hoàn thành (have / has + V3), thường đi với since / for. Người Việt hay nói "I know you since 2022" vì tiếng Việt không chia thì — đây là lỗi cần tránh.', null),
  ('grammar-b1-perfect-02', 'grammar-b1-present-perfect-past-simple', 2, 'multiple_choice', 'B1', 'Use the past simple with a finished time', 'I ___ you last night, but you were asleep.', 'Tối qua em có gọi cho anh, nhưng anh ngủ mất rồi.', '["called","have called","call","am calling"]'::jsonb, null, null, null, null, null, '["called"]'::jsonb, '"Last night" is a finished time, so we use the past simple. The present perfect cannot be used with finished time words like yesterday, last night or in 2021.', '"Last night" là thời gian đã kết thúc nên dùng quá khứ đơn. Không dùng hiện tại hoàn thành với các mốc đã qua như yesterday, last night, in 2021.', null),
  ('grammar-b1-perfect-03', 'grammar-b1-present-perfect-past-simple', 3, 'multiple_choice', 'B1', 'Use been for experience with ever', 'Have you ever ___ to Đà Lạt?', 'Anh đã bao giờ đến Đà Lạt chưa?', '["been","went","go","was"]'::jsonb, null, null, null, null, null, '["been"]'::jsonb, 'To ask about life experience, use Have you ever + past participle. For visiting places, we usually say "have been to": Have you ever been to Đà Lạt?', 'Hỏi về trải nghiệm dùng Have you ever + V3. Khi nói đã từng đến đâu, dùng "have been to". Sau have phải là V3, nên "went" là sai.', null),
  ('grammar-b1-perfect-04', 'grammar-b1-present-perfect-past-simple', 4, 'multiple_choice', 'B1', 'Use for with a length of time', 'She has lived in Seoul ___ three years.', 'Cô ấy đã sống ở Seoul được ba năm.', '["for","since","ago","from"]'::jsonb, null, null, null, null, null, '["for"]'::jsonb, 'Use for + a length of time (for three years, for a week) and since + a starting point (since 2022, since Monday).', 'for + khoảng thời gian (for three years, for a week); since + mốc bắt đầu (since 2022, since Monday). "Three years" là khoảng thời gian nên dùng for.', null),
  ('grammar-b1-perfect-05', 'grammar-b1-present-perfect-past-simple', 5, 'multiple_choice', 'B1', 'Use since with a starting point', 'I haven''t seen you ___ your last visit.', 'Em chưa gặp lại anh kể từ lần anh đến thăm gần nhất.', '["since","for","ago","from"]'::jsonb, null, null, null, null, null, '["since"]'::jsonb, '"Your last visit" is a starting point in time, so we use since. Since answers "from when?", for answers "how long?".', '"Your last visit" là một mốc thời gian nên dùng since. Since trả lời câu hỏi "từ khi nào?", for trả lời "bao lâu?".', null),
  ('grammar-b1-perfect-06', 'grammar-b1-present-perfect-past-simple', 6, 'multiple_choice', 'B1', 'Avoid the present perfect with a specific past year', 'Which sentence about a trip in 2021 is correct?', 'Câu nào nói về chuyến đi năm 2021 là đúng?', '["I visited Huế in 2021.","I have visited Huế in 2021.","I have visit Huế in 2021.","I did visited Huế in 2021."]'::jsonb, null, null, null, null, null, '["I visited Huế in 2021."]'::jsonb, 'When you say exactly when something happened (in 2021), use the past simple. Without a time you could say "I have visited Huế" (as an experience), but not together with "in 2021".', 'Khi có thời gian cụ thể đã qua (in 2021) thì dùng quá khứ đơn. Nếu không nêu thời gian, có thể nói "I have visited Huế" (kể trải nghiệm), nhưng không dùng chung với "in 2021".', null),
  ('grammar-b1-perfect-07', 'grammar-b1-present-perfect-past-simple', 7, 'multiple_choice', 'B1', 'Use the past participle with never', 'I have never ___ snow. Let''s see it together one day!', 'Em chưa bao giờ thấy tuyết. Một ngày nào đó mình cùng đi ngắm nhé!', '["seen","saw","see","seeing"]'::jsonb, null, null, null, null, null, '["seen"]'::jsonb, 'Present perfect = have / has + past participle (V3). The verb "see" is irregular: see – saw – seen. "Saw" is the past simple, not the participle.', 'Hiện tại hoàn thành = have / has + V3. "See" là động từ bất quy tắc: see – saw – seen. "Saw" là quá khứ đơn (V2), không dùng sau have.', null),
  ('grammar-b1-perfect-08', 'grammar-b1-present-perfect-past-simple', 8, 'multiple_choice', 'B1', 'Use the past simple for questions with when', 'When ___ you start learning English?', 'Anh bắt đầu học tiếng Anh từ khi nào?', '["did","have","has","do"]'::jsonb, null, null, null, null, null, '["did"]'::jsonb, 'A question with "When…?" asks about a specific past moment, so it uses the past simple: When did you start…? We don''t say "When have you started…?".', 'Câu hỏi "When…?" hỏi về một thời điểm cụ thể trong quá khứ nên dùng quá khứ đơn: When did you start…? Không dùng "When have you…?".', null),
  ('grammar-b1-perfect-09', 'grammar-b1-present-perfect-past-simple', 9, 'multiple_choice', 'B1', 'Use has just for very recent news', 'Guess what? The gift you sent ___ just arrived!', 'Đoán xem? Món quà anh gửi vừa mới đến!', '["has","have","did","is"]'::jsonb, null, null, null, null, null, '["has"]'::jsonb, 'Use have / has + just + past participle for very recent news. "The gift" is singular, so we use has: The gift has just arrived.', 'Dùng have / has + just + V3 cho tin vừa mới xảy ra. "The gift" là số ít nên dùng has. "Just" tương đương "vừa mới" trong tiếng Việt.', null),
  ('grammar-b1-perfect-10', 'grammar-b1-present-perfect-past-simple', 10, 'multiple_choice', 'B1', 'Use ago with the past simple', 'I met my partner two years ___.', 'Em gặp người yêu mình cách đây hai năm.', '["ago","since","for"]'::jsonb, null, null, null, null, null, '["ago"]'::jsonb, '"Ago" means "before now" and comes after the time: two years ago. It goes with the past simple, not the present perfect.', '"Ago" nghĩa là "cách đây", đứng sau khoảng thời gian: two years ago. "Ago" đi với quá khứ đơn, không đi với hiện tại hoàn thành.', null),
  ('listen-a1-01', 'listen-a1-calls-daily-life', 1, 'listening', 'A1', 'Hear the difference between live and leave', 'Which sentence did you hear about the house?', 'Bạn đã nghe câu nào về ngôi nhà?', '["I leave a small house near the river.","I live in a small house near the river.","I love a small house near the river."]'::jsonb, null, 'I live in a small house near the river.', null, null, null, '["I live in a small house near the river."]'::jsonb, '"Live" has a short /ɪ/ sound; "leave" has a long /i/ sound. The speaker says "live in", which means where they stay.', '"Live" /lɪv/ có âm i ngắn, còn "leave" /liv/ có âm i dài (kéo dài hơn, miệng căng hơn). Người nói dùng "live in" = sống ở.', null),
  ('listen-a1-02', 'listen-a1-calls-daily-life', 2, 'listening', 'A1', 'Catch the key verb in a video-call question', 'Which question did you hear at the start of the video call?', 'Bạn đã nghe câu hỏi nào lúc bắt đầu cuộc gọi video?', '["Can you see me now?","Can you call me now?","Can you hear me now?"]'::jsonb, null, 'Can you hear me now?', null, null, null, '["Can you hear me now?"]'::jsonb, 'The speaker says "hear", which is about sound. This is a very common question when the connection is bad.', 'Người nói dùng "hear" (nghe), liên quan đến âm thanh. Đây là câu rất hay dùng khi mạng yếu trong lúc gọi video.', null),
  ('listen-a1-03', 'listen-a1-calls-daily-life', 3, 'listening', 'A1', 'Hear the difference between ship and sheep', 'Which sentence did you hear about the photo?', 'Bạn đã nghe câu nào về bức ảnh?', '["There is a ship in the photo.","There is a sheep in the photo.","There is a shop in the photo."]'::jsonb, null, 'There is a sheep in the photo.', null, null, null, '["There is a sheep in the photo."]'::jsonb, '"Sheep" has a long /i/ sound, like in "see". "Ship" has a short /ɪ/ sound, like in "sit".', '"Sheep" (con cừu) có âm i dài như trong "see". "Ship" (con tàu) có âm i ngắn, bật nhanh như trong "sit".', null),
  ('listen-a1-04', 'listen-a1-calls-daily-life', 4, 'listening', 'A1', 'Catch a time in a sentence about a daily routine', 'What time does the speaker drink coffee?', 'Người nói uống cà phê lúc mấy giờ?', '["At six","At seven","At eleven"]'::jsonb, null, 'I drink coffee at seven every morning.', null, null, null, '["At seven"]'::jsonb, 'The speaker says "at seven every morning". "Seven" and "eleven" both end in -ven, so listen for the start of the word.', 'Người nói nói "at seven every morning" (bảy giờ mỗi sáng). "Seven" và "eleven" đều kết thúc bằng -ven, nên hãy chú ý phần đầu của từ.', null),
  ('listen-a1-05', 'listen-a1-calls-daily-life', 5, 'listening', 'A1', 'Hear final consonant sounds like t and p', 'Which sentence did you hear about what she has?', 'Bạn đã nghe câu nào về thứ cô ấy có?', '["She has a black cap.","She has a black car.","She has a black cat."]'::jsonb, null, 'She has a black cat.', null, null, null, '["She has a black cat."]'::jsonb, 'The words cat, cap and car differ only in their last sound. English speakers say the final sound clearly, so listen to the very end of the word.', 'Cat, cap và car chỉ khác nhau ở âm cuối. Người Việt hay nuốt âm cuối, nhưng trong tiếng Anh âm cuối quyết định nghĩa của từ, nên hãy nghe kỹ phần cuối.', null),
  ('listen-a2-01', 'listen-a2-planning-to-meet', 1, 'listening', 'A2', 'Hear the difference between thirteen and thirty', 'How many days until the visit?', 'Còn bao nhiêu ngày nữa thì đến chuyến thăm?', '["Three days","Thirteen days","Thirty days"]'::jsonb, null, 'I will visit you in thirteen days. I already have my ticket.', null, null, null, '["Thirteen days"]'::jsonb, 'In "thirteen", the stress is at the end: thir-TEEN, with a long /i/ sound. In "thirty", the stress is at the start: THIR-ty.', '"Thirteen" nhấn ở cuối (thir-TEEN) và có âm "n" ở cuối. "Thirty" nhấn ở đầu (THIR-ty) và kết thúc bằng âm "ti" ngắn.', null),
  ('listen-a2-02', 'listen-a2-planning-to-meet', 2, 'listening', 'A2', 'Understand where people plan to meet', 'Where will they meet?', 'Họ sẽ gặp nhau ở đâu?', '["At the bookshop near the park","At the park near the station","At the coffee shop near the park"]'::jsonb, null, 'Let''s meet at the coffee shop near the park on Saturday.', null, null, null, '["At the coffee shop near the park"]'::jsonb, 'The speaker says "the coffee shop near the park". The park is only a landmark to help find the coffee shop.', 'Người nói nói "the coffee shop near the park" (quán cà phê gần công viên). Công viên chỉ là mốc để dễ tìm quán.', null),
  ('listen-a2-03', 'listen-a2-planning-to-meet', 3, 'listening', 'A2', 'Hear the difference between walk and work', 'Which sentence did you hear about the beach?', 'Bạn đã nghe câu nào về bãi biển?', '["We can work on the beach in the evening.","We can walk on the beach in the evening.","We can wake on the beach in the evening."]'::jsonb, null, 'We can walk on the beach in the evening.', null, null, null, '["We can walk on the beach in the evening."]'::jsonb, 'In "walk", the l is silent and the vowel is open: /wɔk/. "Work" has an r sound: /wɜrk/.', 'Trong "walk" /wɔk/, chữ l câm và miệng mở tròn. "Work" /wɜrk/ có âm r, lưỡi cong lên. Đây là cặp từ người Việt rất hay nhầm.', null),
  ('listen-a2-04', 'listen-a2-planning-to-meet', 4, 'listening', 'A2', 'Hear the difference between fifteen and fifty', 'How much does the bus ticket cost?', 'Vé xe buýt giá bao nhiêu?', '["Five dollars","Fifteen dollars","Fifty dollars"]'::jsonb, null, 'The bus ticket costs fifty dollars, so I will take the train instead.', null, null, null, '["Fifty dollars"]'::jsonb, '"Fifty" is stressed at the start: FIF-ty. "Fifteen" is stressed at the end: fif-TEEN. The price is high, so the speaker chooses the train.', '"Fifty" nhấn ở đầu (FIF-ty), "fifteen" nhấn ở cuối (fif-TEEN). Vé đắt nên người nói chọn đi tàu thay vì xe buýt.', null),
  ('listen-a2-05', 'listen-a2-planning-to-meet', 5, 'listening', 'A2', 'Understand advice before a visit', 'What should the listener bring?', 'Người nghe nên mang theo gì?', '["An umbrella","A warm jacket","A swimsuit"]'::jsonb, null, 'Don''t forget to bring a warm jacket. It is very cold here in December.', null, null, null, '["A warm jacket"]'::jsonb, '"Don''t forget to bring" introduces what to pack: a warm jacket, because December is cold there.', '"Don''t forget to bring" (đừng quên mang theo) giới thiệu món cần mang: áo khoác ấm, vì tháng Mười Hai ở đó rất lạnh.', null),
  ('listen-b1-01', 'listen-b1-calls-daily-life', 1, 'listening', 'B1', 'Understand the reason for calling back', 'Why does the speaker want to call back?', 'Tại sao người nói muốn gọi lại?', '["Because the internet is slow","Because the phone battery is low","Because they are busy at work"]'::jsonb, null, 'Sorry, my internet is really slow tonight. Can I call you back in ten minutes from my phone?', null, null, null, '["Because the internet is slow"]'::jsonb, 'The speaker says "my internet is really slow tonight", then offers to call back from their phone.', 'Người nói bảo "my internet is really slow tonight" (mạng tối nay rất chậm), rồi đề nghị gọi lại bằng điện thoại.', null),
  ('listen-b1-02', 'listen-b1-calls-daily-life', 2, 'listening', 'B1', 'Hear the difference between left and lost', 'Which sentence did you hear about the keys?', 'Bạn đã nghe câu nào về chùm chìa khóa?', '["I think I lost my keys at the office.","I think I left my keys at the office.","I think I lent my keys at the office."]'::jsonb, null, 'Wait a minute, I think I left my keys at the office. I need to go back and get them.', null, null, null, '["I think I left my keys at the office."]'::jsonb, '"Left" (past of leave) means the keys are still at the office, so the speaker can go back and get them. "Lost" would mean they don''t know where the keys are.', '"Left" (quá khứ của leave) nghĩa là để quên ở văn phòng, nên người nói có thể quay lại lấy. "Lost" là làm mất, không biết chìa khóa ở đâu.', null),
  ('listen-b1-03', 'listen-b1-calls-daily-life', 3, 'listening', 'B1', 'Follow the order of activities in the evening', 'What does the speaker do after dinner?', 'Người nói làm gì sau bữa tối?', '["Goes for a walk","Studies English","Calls their family"]'::jsonb, null, 'I usually cook dinner at eight. After that, I study English for thirty minutes before bed.', null, null, null, '["Studies English"]'::jsonb, '"After that" shows the next activity: studying English for thirty minutes before going to bed.', '"After that" (sau đó) cho biết hoạt động tiếp theo: học tiếng Anh ba mươi phút trước khi đi ngủ.', null),
  ('listen-b1-04', 'listen-b1-calls-daily-life', 4, 'listening', 'B1', 'Hear the difference between thirty and thirteen in a longer sentence', 'Which sentence did you hear about the speaker''s sister?', 'Bạn đã nghe câu nào về chị/em gái của người nói?', '["My sister is thirteen years old, and she lives in the city with her husband.","My sister is thirty years old, and she lives in the city with her husband.","My sister is thirty years old, and she leaves the city with her husband."]'::jsonb, null, 'My sister is thirty years old, and she lives in the city with her husband.', null, null, null, '["My sister is thirty years old, and she lives in the city with her husband."]'::jsonb, 'You hear THIR-ty, stressed at the start, and "lives in" with a short /ɪ/. A sister with a husband is also more likely to be thirty than thirteen.', 'Bạn nghe THIR-ty (nhấn ở đầu) và "lives in" với âm i ngắn. Ngữ cảnh "sống với chồng" cũng cho thấy ba mươi tuổi hợp lý hơn mười ba.', null),
  ('listen-b1-05', 'listen-b1-calls-daily-life', 5, 'listening', 'B1', 'Understand the cause of a problem on a video call', 'Why is the video so dark?', 'Tại sao video lại tối như vậy?', '["The camera is old","It is night outside","The light in the room is broken"]'::jsonb, null, 'The light in my room is broken. That''s why the video is so dark. I''ll fix it tomorrow.', null, null, null, '["The light in the room is broken"]'::jsonb, '"That''s why" connects the cause to the result: the broken light is the reason the video is dark.', '"That''s why" (đó là lý do) nối nguyên nhân với kết quả: đèn trong phòng bị hỏng nên video bị tối.', null),
  ('listen-b1-06', 'listen-b1-travel', 1, 'listening', 'B1', 'Understand where the speaker is going', 'Where is the speaker going?', 'Người nói đang đi đâu?', '["To the hotel","To the airport","To the train station"]'::jsonb, null, 'Excuse me, does this train go to the airport? I have to check in by six o''clock.', null, null, null, '["To the airport"]'::jsonb, 'The speaker asks if the train goes "to the airport" and mentions checking in, which you do before a flight.', 'Người nói hỏi tàu có đi "to the airport" (đến sân bay) không, và nhắc đến "check in" là thủ tục trước khi bay. Họ đang ở trên tàu nên không phải đi đến nhà ga.', null),
  ('listen-b1-07', 'listen-b1-travel', 2, 'listening', 'B1', 'Hear the difference between ship and sheep in a travel story', 'Which sentence did you hear about the island?', 'Bạn đã nghe câu nào về hòn đảo?', '["We took a sheep to the island, and the sea was very calm.","We took a trip to the island, and the sea was very calm.","We took a ship to the island, and the sea was very calm."]'::jsonb, null, 'We took a ship to the island, and the sea was very calm.', null, null, null, '["We took a ship to the island, and the sea was very calm."]'::jsonb, '"Ship" has a short, quick /ɪ/ sound. "Sheep" is longer, like "see". "Trip" starts with a different sound, tr.', '"Ship" (con tàu) có âm i ngắn và nhanh. "Sheep" (con cừu) có âm i dài như "see". "Trip" bắt đầu bằng âm tr khác hẳn.', null),
  ('listen-b1-08', 'listen-b1-travel', 3, 'listening', 'B1', 'Understand what the speaker will do during a delay', 'What will the speaker do while waiting?', 'Người nói sẽ làm gì trong lúc chờ?', '["Go back to the hotel","Have dinner at the airport","Sleep on the plane"]'::jsonb, null, 'Our flight is delayed by two hours, so we will have dinner at the airport. I will text you when we get on the plane.', null, null, null, '["Have dinner at the airport"]'::jsonb, 'Because the flight is delayed, the speaker says "we will have dinner at the airport". "So" introduces the result of the delay.', 'Vì chuyến bay bị trễ, người nói bảo "we will have dinner at the airport" (tụi mình sẽ ăn tối ở sân bay). Từ "so" giới thiệu kết quả của việc bị trễ.', null),
  ('listen-b1-09', 'listen-b1-travel', 4, 'listening', 'B1', 'Hear the difference between fifteen and fifty in directions', 'Which sentence did you hear about the hotel?', 'Bạn đã nghe câu nào về khách sạn?', '["The hotel is fifty minutes from the beach, so we can walk there every morning.","The hotel is fifteen minutes from the beach, so we can walk there every morning.","The hotel is five minutes from the beach, so we can walk there every morning."]'::jsonb, null, 'The hotel is fifteen minutes from the beach, so we can walk there every morning.', null, null, null, '["The hotel is fifteen minutes from the beach, so we can walk there every morning."]'::jsonb, 'You hear fif-TEEN, with stress at the end and a clear n sound. Fifteen minutes is also a comfortable walk every morning.', 'Bạn nghe fif-TEEN, nhấn ở cuối và có âm n rõ. Mười lăm phút cũng là quãng đường đi bộ hợp lý mỗi sáng.', null),
  ('listen-b1-10', 'listen-b1-travel', 5, 'listening', 'B1', 'Catch the main question at a hotel reception', 'What does the speaker ask about?', 'Người nói hỏi về điều gì?', '["Whether breakfast is included","Where the swimming pool is","What time they must check out"]'::jsonb, null, 'Hello, I would like a room for two nights, please. Does the price include breakfast?', null, null, null, '["Whether breakfast is included"]'::jsonb, 'The question is "Does the price include breakfast?", so the speaker wants to know if breakfast is part of the price.', 'Câu hỏi là "Does the price include breakfast?" (giá phòng có bao gồm bữa sáng không?), nên người nói muốn biết bữa sáng có được tính trong giá không.', null),
  ('puzzle-a1-01', 'writing-a1-sentence-puzzle', 1, 'sentence_order', 'A1', 'Build a subject + verb + object sentence', 'Make the sentence: Em nhớ anh rất nhiều.', null, null, '["so","I","much.","you","miss"]'::jsonb, null, 'Subject first, then the verb, then the person. "So much" goes at the end.', 'Chủ ngữ đứng đầu, rồi đến động từ, rồi đến người được nhớ. "So much" đặt ở cuối.', null, '["I miss you so much."]'::jsonb, 'English word order is Subject + Verb + Object: I (subject) miss (verb) you (object). Words that show how much usually come after: so much.', 'Trật tự câu tiếng Anh: Chủ ngữ + Động từ + Tân ngữ: I + miss + you. Cụm chỉ mức độ "so much" thường đứng sau cùng.', null),
  ('puzzle-a1-02', 'writing-a1-sentence-puzzle', 2, 'sentence_order', 'A1', 'Build a Wh- question with "to be"', 'Make the sentence: Bên đó bây giờ là mấy giờ?', null, null, '["it","What","there?","time","is"]'::jsonb, null, 'Start with the question words "What time", then the verb "is", then "it".', 'Bắt đầu bằng "What time", sau đó là động từ "is", rồi đến "it".', null, '["What time is it there?"]'::jsonb, 'In questions with "to be", the verb comes before the subject: What time is it? We use "it" for time. "There" means "where you are".', 'Trong câu hỏi với "to be", động từ đứng trước chủ ngữ: What time is it? Dùng "it" khi nói về giờ. "There" nghĩa là "ở chỗ anh/em".', null),
  ('puzzle-a1-03', 'writing-a1-sentence-puzzle', 3, 'sentence_order', 'A1', 'Use "to be" with an adjective', 'Make the sentence: Hôm nay em rất vui.', null, null, '["today.","am","happy","I"]'::jsonb, null, 'Don''t forget "am" between "I" and the adjective.', 'Đừng quên "am" giữa "I" và tính từ.', null, '["I am happy today."]'::jsonb, 'English needs "to be" before an adjective: I am happy. Vietnamese says "Em vui" without a verb, but English cannot drop "am".', 'Tiếng Anh cần "to be" trước tính từ: I am happy. Tiếng Việt nói "Em vui" không cần động từ, nhưng tiếng Anh không được bỏ "am".', null),
  ('puzzle-a1-04', 'writing-a1-sentence-puzzle', 4, 'sentence_order', 'A1', 'Build a yes/no question with do', 'Make the sentence: Anh có thích cà phê không?', null, null, '["coffee?","like","Do","you"]'::jsonb, null, 'Yes/no questions start with "Do", then the subject, then the verb.', 'Câu hỏi Có/Không bắt đầu bằng "Do", rồi chủ ngữ, rồi động từ.', null, '["Do you like coffee?"]'::jsonb, 'Present simple yes/no questions: Do / Does + subject + base verb + …? Vietnamese uses "có… không", English uses "Do… ?".', 'Câu hỏi Có/Không ở hiện tại đơn: Do / Does + chủ ngữ + động từ nguyên mẫu? Tiếng Việt dùng "có… không", tiếng Anh dùng "Do…?".', null),
  ('puzzle-a1-05', 'writing-a1-sentence-puzzle', 5, 'sentence_order', 'A1', 'Put time expressions at the end', 'Make the sentence: Tối nào tụi mình cũng nói chuyện với nhau.', null, null, '["night.","We","every","talk"]'::jsonb, null, 'Subject + verb first. The time phrase "every night" goes at the end.', 'Chủ ngữ + động từ trước. Cụm thời gian "every night" đặt ở cuối.', null, '["We talk every night."]'::jsonb, 'Time phrases like every night, every day or on Sundays usually go at the end of an English sentence: We talk every night.', 'Cụm thời gian như every night, every day thường đứng cuối câu tiếng Anh: We talk every night.', null),
  ('puzzle-a1-06', 'writing-a1-sentence-puzzle', 6, 'sentence_order', 'A1', 'Put the adjective before the noun', 'Make the sentence: Anh ấy có một con chó nhỏ.', null, null, '["a","dog.","He","small","has"]'::jsonb, null, 'In English the adjective comes before the noun: "small dog", not "dog small".', 'Trong tiếng Anh, tính từ đứng trước danh từ: "small dog", không phải "dog small".', null, '["He has a small dog."]'::jsonb, 'Vietnamese puts the adjective after the noun (con chó nhỏ), but English puts it before: a small dog. Also remember: he has (not he have).', 'Tiếng Việt đặt tính từ sau danh từ (con chó nhỏ), còn tiếng Anh đặt trước: a small dog. Nhớ thêm: he has (không phải he have).', null),
  ('puzzle-a1-07', 'writing-a1-sentence-puzzle', 7, 'sentence_order', 'A1', 'Build a Where question with "to be"', 'Make the sentence: Bây giờ anh đang ở đâu?', null, null, '["now?","you","Where","are"]'::jsonb, null, 'Question word first, then "are", then "you".', 'Từ để hỏi đứng đầu, rồi đến "are", rồi "you".', null, '["Where are you now?"]'::jsonb, 'Wh- questions with "to be": question word + am / is / are + subject. "Where you are now?" is a common mistake — the verb must come before the subject.', 'Câu hỏi Wh- với "to be": từ để hỏi + am / is / are + chủ ngữ. "Where you are now?" là lỗi thường gặp — động từ phải đứng trước chủ ngữ.', null),
  ('puzzle-a1-08', 'writing-a1-sentence-puzzle', 8, 'sentence_order', 'A1', 'Use "It is" for weather', 'Make the sentence: Ở đây trời rất lạnh.', null, null, '["here.","is","It","cold","very"]'::jsonb, null, 'Weather sentences start with "It is". "Very" comes before the adjective.', 'Câu nói về thời tiết bắt đầu bằng "It is". "Very" đứng trước tính từ.', null, '["It is very cold here."]'::jsonb, 'English sentences need a subject, so for weather we use "it": It is cold. "Very" goes before the adjective, and the place word "here" goes at the end.', 'Câu tiếng Anh luôn cần chủ ngữ, nên khi nói thời tiết ta dùng "it": It is cold. "Very" đứng trước tính từ, "here" đặt cuối câu.', null),
  ('puzzle-a1-09', 'writing-a1-sentence-puzzle', 9, 'sentence_order', 'A1', 'Put the clock time at the end', 'Make the sentence: Em ăn sáng lúc bảy giờ.', null, null, '["at","breakfast","seven.","eat","I"]'::jsonb, null, 'Subject + verb + what you eat, then "at" + the time.', 'Chủ ngữ + động từ + bữa ăn, rồi "at" + giờ.', null, '["I eat breakfast at seven."]'::jsonb, 'We say "eat breakfast" (no article). Clock times use "at" and usually come at the end: at seven.', 'Ta nói "eat breakfast" (không có mạo từ). Giờ giấc dùng "at" và thường đứng cuối câu: at seven.', null),
  ('puzzle-a1-10', 'writing-a1-sentence-puzzle', 10, 'sentence_order', 'A1', 'Use make + person + adjective', 'Make the sentence: Anh làm em hạnh phúc.', null, null, '["happy.","me","You","make"]'::jsonb, null, 'Pattern: someone + make + person + feeling.', 'Cấu trúc: ai đó + make + người + cảm xúc.', null, '["You make me happy."]'::jsonb, 'The pattern "make + someone + adjective" means to cause a feeling: You make me happy. Use the object form "me", not "I", after the verb.', 'Cấu trúc "make + ai đó + tính từ" nghĩa là làm cho ai cảm thấy thế nào: You make me happy. Sau động từ dùng "me", không dùng "I".', null),
  ('puzzle-a2-01', 'writing-a2-sentence-puzzle', 1, 'sentence_order', 'A2', 'Order a past simple statement with a time phrase', 'Make the sentence: Cuối tuần trước em đã về thăm bố mẹ.', null, null, '["my","last","visited","I","parents","weekend."]'::jsonb, null, 'Subject + past verb + who, then the time phrase at the end.', 'Chủ ngữ + động từ quá khứ + ai, rồi cụm thời gian ở cuối.', null, '["I visited my parents last weekend."]'::jsonb, 'Past simple statement: subject + verb-ed + object + time. "Last weekend" shows finished time, so the verb is in the past: visited.', 'Câu quá khứ đơn: chủ ngữ + V-ed + tân ngữ + thời gian. "Last weekend" là thời gian đã qua nên động từ chia quá khứ: visited.', null),
  ('puzzle-a2-02', 'writing-a2-sentence-puzzle', 2, 'sentence_order', 'A2', 'Build a past simple question with did', 'Make the sentence: Tối qua anh ngủ có ngon không?', null, null, '["sleep","last","Did","well","night?","you"]'::jsonb, null, 'Did + subject + base verb. "Well" comes right after the verb.', 'Did + chủ ngữ + động từ nguyên mẫu. "Well" đứng ngay sau động từ.', null, '["Did you sleep well last night?"]'::jsonb, 'Past questions: Did + subject + base verb…? The adverb "well" describes the verb, so it follows "sleep", and the time phrase comes last.', 'Câu hỏi quá khứ: Did + chủ ngữ + động từ nguyên mẫu…? Trạng từ "well" bổ nghĩa cho động từ nên đứng sau "sleep", cụm thời gian đặt cuối.', null),
  ('puzzle-a2-03', 'writing-a2-sentence-puzzle', 3, 'sentence_order', 'A2', 'Build a future plan with "going to"', 'Make the sentence: Tụi mình sẽ gặp nhau vào tháng Mười Hai.', null, null, '["meet","We","in","going","December.","are","to"]'::jsonb, null, 'Pattern: subject + am / is / are + going to + base verb.', 'Cấu trúc: chủ ngữ + am / is / are + going to + động từ nguyên mẫu.', null, '["We are going to meet in December."]'::jsonb, '"Be going to + verb" talks about future plans: We are going to meet. Months take "in": in December.', '"Be going to + động từ" dùng cho kế hoạch tương lai: We are going to meet. Tháng đi với "in": in December.', null),
  ('puzzle-a2-04', 'writing-a2-sentence-puzzle', 4, 'sentence_order', 'A2', 'Build a negative with doesn''t', 'Make the sentence: Cô ấy không ăn đồ cay.', null, null, '["spicy","doesn''t","She","food.","eat"]'::jsonb, null, 'She + doesn''t + base verb. The adjective "spicy" comes before "food".', 'She + doesn''t + động từ nguyên mẫu. Tính từ "spicy" đứng trước "food".', null, '["She doesn''t eat spicy food."]'::jsonb, 'Present simple negative: subject + don''t / doesn''t + base verb. Remember: adjective before noun — spicy food (đồ cay).', 'Phủ định hiện tại đơn: chủ ngữ + don''t / doesn''t + động từ nguyên mẫu. Nhớ: tính từ đứng trước danh từ — spicy food.', null),
  ('puzzle-a2-05', 'writing-a2-sentence-puzzle', 5, 'sentence_order', 'A2', 'Build a Wh- question in the past', 'Make the sentence: Bữa tối anh đã ăn gì?', null, null, '["for","you","What","dinner?","have","did"]'::jsonb, null, 'Question word + did + subject + base verb.', 'Từ để hỏi + did + chủ ngữ + động từ nguyên mẫu.', null, '["What did you have for dinner?"]'::jsonb, 'Wh- questions in the past: What + did + you + have…? We often say "have" for meals: have dinner, have breakfast.', 'Câu hỏi Wh- ở quá khứ: What + did + you + have…? Người bản xứ hay dùng "have" cho bữa ăn: have dinner, have breakfast.', null),
  ('puzzle-a2-06', 'writing-a2-sentence-puzzle', 6, 'sentence_order', 'A2', 'Place adverbs of frequency before the main verb', 'Make the sentence: Em lúc nào cũng nghĩ về anh.', null, null, '["about","always","I","you.","think"]'::jsonb, null, 'Adverbs like "always" go between the subject and the main verb.', 'Trạng từ tần suất như "always" đứng giữa chủ ngữ và động từ chính.', null, '["I always think about you."]'::jsonb, 'Adverbs of frequency (always, usually, often, never) go before the main verb: I always think. But they go after "to be": I am always happy.', 'Trạng từ tần suất (always, usually, often, never) đứng trước động từ thường: I always think. Nhưng đứng sau "to be": I am always happy.', null),
  ('puzzle-a2-07', 'writing-a2-sentence-puzzle', 7, 'sentence_order', 'A2', 'Use was with a weather adjective', 'Make the sentence: Hôm qua thời tiết rất tệ.', null, null, '["terrible","weather","The","yesterday.","was"]'::jsonb, null, 'Start with "The weather", then the past of "to be", then the adjective.', 'Bắt đầu bằng "The weather", rồi "to be" ở quá khứ, rồi tính từ.', null, '["The weather was terrible yesterday."]'::jsonb, '"The weather" is singular, so the past of "to be" is was. Time words like "yesterday" can go at the end.', '"The weather" là số ít nên "to be" quá khứ là was. Từ chỉ thời gian như "yesterday" có thể đặt cuối câu.', null),
  ('puzzle-a2-08', 'writing-a2-sentence-puzzle', 8, 'sentence_order', 'A2', 'Make a request with "Can you"', 'Make the sentence: Anh gửi cho em một tấm ảnh được không?', null, null, '["me","a","Can","photo?","send","you"]'::jsonb, null, 'Can + you + verb + person + thing.', 'Can + you + động từ + người nhận + vật.', null, '["Can you send me a photo?"]'::jsonb, 'Requests: Can you + base verb…? With "send", the person usually comes before the thing: send me a photo.', 'Câu nhờ vả: Can you + động từ nguyên mẫu…? Với "send", người nhận thường đứng trước vật: send me a photo.', null),
  ('puzzle-a2-09', 'writing-a2-sentence-puzzle', 9, 'sentence_order', 'A2', 'Use the present simple for timetables', 'Make the sentence: Chuyến bay của em cất cánh lúc nửa đêm.', null, null, '["leaves","midnight.","My","at","flight"]'::jsonb, null, '"My flight" is the subject. Use "at" with midnight.', '"My flight" là chủ ngữ. Dùng "at" với midnight.', null, '["My flight leaves at midnight."]'::jsonb, 'We often use the present simple for timetables, even in the future: My flight leaves at midnight. "Flight" is singular, so leave + s.', 'Thì hiện tại đơn thường dùng cho lịch trình, kể cả trong tương lai: My flight leaves at midnight. "Flight" là số ít nên leave thêm -s.', null),
  ('puzzle-a2-10', 'writing-a2-sentence-puzzle', 10, 'sentence_order', 'A2', 'Combine past continuous and past simple with when', 'Make the sentence: Em đang xem phim thì anh gọi.', null, null, '["when","a","I","you","movie","was","called.","watching"]'::jsonb, null, 'The longer action uses was + -ing. The short action after "when" uses the past simple.', 'Hành động kéo dài dùng was + V-ing. Hành động ngắn xen vào sau "when" dùng quá khứ đơn.', null, '["I was watching a movie when you called."]'::jsonb, 'Past continuous (was watching) for the longer background action, past simple (called) for the short action that interrupts it.', 'Quá khứ tiếp diễn (was watching) cho hành động đang diễn ra, quá khứ đơn (called) cho hành động ngắn xen vào.', null),
  ('puzzle-b1-01', 'writing-b1-sentence-puzzle', 1, 'sentence_order', 'B1', 'Place never in a present perfect sentence', 'Make the sentence: Em chưa bao giờ đến Nhật Bản.', null, null, '["been","never","I","to","Japan.","have"]'::jsonb, null, '"Never" goes between "have" and the past participle.', '"Never" đứng giữa "have" và động từ phân từ (V3).', null, '["I have never been to Japan."]'::jsonb, 'Present perfect for life experience: have + never + past participle. "Have been to" means "have visited".', 'Hiện tại hoàn thành nói về trải nghiệm: have + never + V3. "Have been to" nghĩa là "đã từng đến".', null),
  ('puzzle-b1-02', 'writing-b1-sentence-puzzle', 2, 'sentence_order', 'B1', 'Use for with the present perfect', 'Make the sentence: Tụi mình đã bên nhau được hai năm.', null, null, '["together","have","We","two","for","been","years."]'::jsonb, null, 'We have been + together, then "for" + the length of time.', 'We have been + together, rồi "for" + khoảng thời gian.', null, '["We have been together for two years."]'::jsonb, 'A situation that started in the past and continues now uses the present perfect: We have been together. "For" + length of time goes at the end.', 'Việc bắt đầu trong quá khứ và vẫn tiếp diễn dùng hiện tại hoàn thành: We have been together. "For" + khoảng thời gian đặt cuối câu.', null),
  ('puzzle-b1-03', 'writing-b1-sentence-puzzle', 3, 'sentence_order', 'B1', 'Build a second conditional sentence', 'Make the sentence: Nếu em ở đó, em sẽ ôm anh.', null, null, '["I","would","If","there,","were","hug","you.","I"]'::jsonb, null, 'If + I + were…, then I + would + base verb.', 'If + I + were…, sau đó I + would + động từ nguyên mẫu.', null, '["If I were there, I would hug you."]'::jsonb, 'Second conditional for an imaginary present: If + past simple (were), would + base verb. When the if-part comes first, put a comma after it.', 'Điều kiện loại 2 cho tình huống không có thật: If + quá khứ đơn (were), would + V nguyên mẫu. Khi vế if đứng đầu, đặt dấu phẩy sau nó.', null),
  ('puzzle-b1-04', 'writing-b1-sentence-puzzle', 4, 'sentence_order', 'B1', 'Use statement word order in an embedded question', 'Make the sentence: Anh có thể cho em biết bây giờ là mấy giờ không?', null, null, '["what","tell","Could","it","me","time","is?","you"]'::jsonb, null, 'After "Could you tell me…", the hidden question uses normal order: what time + it + is.', 'Sau "Could you tell me…", câu hỏi gián tiếp dùng trật tự câu khẳng định: what time + it + is.', null, '["Could you tell me what time it is?"]'::jsonb, 'In an embedded (indirect) question, the subject comes before the verb: What time is it? → Could you tell me what time it is?', 'Trong câu hỏi gián tiếp, chủ ngữ đứng trước động từ: What time is it? → Could you tell me what time it is? Không đảo "is it" nữa.', null),
  ('puzzle-b1-05', 'writing-b1-sentence-puzzle', 5, 'sentence_order', 'B1', 'Use "look forward to" + -ing', 'Make the sentence: Em rất mong được gặp anh.', null, null, '["forward","seeing","I''m","to","you.","looking"]'::jsonb, null, 'The phrase is "look forward to" + verb-ing.', 'Cụm từ là "look forward to" + V-ing.', null, '["I''m looking forward to seeing you."]'::jsonb, 'In "look forward to", "to" is a preposition, so it is followed by -ing: looking forward to seeing you (not to see).', 'Trong "look forward to", "to" là giới từ nên theo sau là V-ing: looking forward to seeing you (không phải to see).', null),
  ('puzzle-b1-06', 'writing-b1-sentence-puzzle', 6, 'sentence_order', 'B1', 'Build a sentence with a relative clause', 'Make the sentence: Lá thư anh viết đã làm em khóc.', null, null, '["made","you","The","that","cry.","letter","wrote","me"]'::jsonb, null, 'The subject is "The letter that you wrote". Then: made + me + cry.', 'Chủ ngữ là "The letter that you wrote". Sau đó: made + me + cry.', null, '["The letter that you wrote made me cry."]'::jsonb, 'A relative clause (that you wrote) can describe the subject. The main verb comes after it. "Make someone + base verb" means cause them to do something: made me cry.', 'Mệnh đề quan hệ (that you wrote) bổ nghĩa cho chủ ngữ, động từ chính đứng sau nó. "Make + ai + V nguyên mẫu" nghĩa là khiến ai làm gì: made me cry.', null),
  ('puzzle-b1-07', 'writing-b1-sentence-puzzle', 7, 'sentence_order', 'B1', 'Place just in a present perfect sentence', 'Make the sentence: Cô ấy vừa thi xong.', null, null, '["finished","has","She","her","just","exams."]'::jsonb, null, '"Just" goes between "has" and the past participle.', '"Just" đứng giữa "has" và V3.', null, '["She has just finished her exams."]'::jsonb, 'has / have + just + past participle describes something that happened very recently: She has just finished.', 'has / have + just + V3 diễn tả việc vừa mới xảy ra: She has just finished.', null),
  ('puzzle-b1-08', 'writing-b1-sentence-puzzle', 8, 'sentence_order', 'B1', 'Use statement order after "I don''t know"', 'Make the sentence: Em không biết anh ấy sống ở đâu.', null, null, '["where","know","I","lives.","he","don''t"]'::jsonb, null, 'After "I don''t know where", use subject + verb (no "does").', 'Sau "I don''t know where", dùng chủ ngữ + động từ (không dùng "does").', null, '["I don''t know where he lives."]'::jsonb, 'Embedded questions don''t use do / does and keep statement order: Where does he live? → I don''t know where he lives.', 'Câu hỏi gián tiếp không dùng do / does và giữ trật tự câu khẳng định: Where does he live? → I don''t know where he lives.', null),
  ('puzzle-b1-09', 'writing-b1-sentence-puzzle', 9, 'sentence_order', 'B1', 'Give advice with should', 'Make the sentence: Tối nay anh nên nghỉ ngơi một chút.', null, null, '["rest","You","some","tonight.","get","should"]'::jsonb, null, 'Subject + should + base verb. "Get some rest" is one idea.', 'Chủ ngữ + should + động từ nguyên mẫu. "Get some rest" là một cụm.', null, '["You should get some rest tonight."]'::jsonb, '"Should + base verb" gives advice. "Get some rest" is a natural phrase meaning "rest a little".', '"Should + V nguyên mẫu" dùng để khuyên. "Get some rest" là cụm tự nhiên, nghĩa là "nghỉ ngơi một chút".', null),
  ('puzzle-b1-10', 'writing-b1-sentence-puzzle', 10, 'sentence_order', 'B1', 'Join contrasting ideas with although', 'Make the sentence: Dù mình ở xa nhau, em vẫn thấy gần anh.', null, null, '["close","we","I","apart,","to","Although","feel","far","you.","are"]'::jsonb, null, 'Start with "Although" + the first idea, then a comma, then the main idea.', 'Bắt đầu bằng "Although" + ý thứ nhất, dấu phẩy, rồi đến ý chính.', null, '["Although we are far apart, I feel close to you."]'::jsonb, '"Although" introduces a contrast. Don''t add "but" in the second part — Vietnamese says "Dù… nhưng…", but English uses only one linking word: Although…, I feel…', '"Although" dùng để nói ý tương phản. Không thêm "but" ở vế sau — tiếng Việt nói "Dù… nhưng…", còn tiếng Anh chỉ dùng một liên từ: Although…, I feel…', null),
  ('zh-vocab-hsk1-greet-01', 'zh-vocab-hsk1-greetings', 1, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''thank you'': 谢谢 (xièxie)', 'Chọn từ có nghĩa là ''cảm ơn''', null, '["谢谢","再见","对不起","你好"]'::jsonb, null, null, null, null, '谢谢', '["谢谢"]'::jsonb, '谢谢 (xièxie) means ''thank you''. The second 谢 is read in the neutral tone.', '谢谢 (xièxie) nghĩa là cảm ơn. Chữ 谢 thứ hai đọc thanh nhẹ, ngắn và nhẹ hơn chữ đầu. Hán-Việt là ''tạ'' (như cảm tạ). Đừng nhầm với 再见 (tạm biệt) hay 对不起 (xin lỗi).', '{"term":"谢谢","pinyin":"xièxie","part_of_speech":"verb","meaning_vi":"cảm ơn","example":"谢谢你每天给我打电话。","example_pinyin":"Xièxie nǐ měi tiān gěi wǒ dǎ diànhuà.","example_vi":"Cảm ơn em ngày nào cũng gọi điện cho anh."}'::jsonb),
  ('zh-vocab-hsk1-greet-02', 'zh-vocab-hsk1-greetings', 2, 'multiple_choice', 'HSK1', 'Recognize the meaning of 朋友 (péngyou)', '「朋友」nghĩa là gì?', null, '["bạn, bạn bè","thầy giáo","học sinh","gia đình"]'::jsonb, null, null, null, null, '朋友', '["bạn, bạn bè"]'::jsonb, '朋友 (péngyou) means ''friend''. 友 is read in the neutral tone.', '朋友 (péngyou) là bạn, bạn bè. Hán-Việt là ''bằng hữu'', nên rất dễ nhớ. Chữ 友 đọc thanh nhẹ: péngyou, không phải péngyǒu. 好朋友 là bạn thân.', '{"term":"朋友","pinyin":"péngyou","part_of_speech":"noun","meaning_vi":"bạn, bạn bè","example":"他是我最好的朋友。","example_pinyin":"Tā shì wǒ zuì hǎo de péngyou.","example_vi":"Anh ấy là người bạn thân nhất của tôi."}'::jsonb),
  ('zh-vocab-hsk1-greet-03', 'zh-vocab-hsk1-greetings', 3, 'multiple_choice', 'HSK1', 'Use 老师 (lǎoshī) to address a teacher', '___，您好！我是您的学生。', 'Em chào thầy/cô ạ! Em là học sinh của thầy/cô.', '["老师","名字","再见","对不起"]'::jsonb, null, null, null, null, '老师', '["老师"]'::jsonb, '老师 (lǎoshī) means ''teacher'', and Chinese students greet their teacher with 老师好 or 老师，您好.', '老师 (lǎoshī) là thầy giáo, cô giáo, dùng cho cả nam lẫn nữ. Người Trung Quốc gọi thẳng ''老师'' để chào, giống mình nói ''Em chào cô''. Chú ý 老 thanh 3, 师 thanh 1.', '{"term":"老师","pinyin":"lǎoshī","part_of_speech":"noun","meaning_vi":"thầy giáo, cô giáo","example":"我的汉语老师是北京人。","example_pinyin":"Wǒ de Hànyǔ lǎoshī shì Běijīng rén.","example_vi":"Cô giáo tiếng Trung của tôi là người Bắc Kinh."}'::jsonb),
  ('zh-vocab-hsk1-greet-04', 'zh-vocab-hsk1-greetings', 4, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''student'': 学生 (xuésheng)', 'Chọn từ có nghĩa là ''học sinh, sinh viên''', null, '["学生","老师","同学","朋友"]'::jsonb, null, null, null, null, '学生', '["学生"]'::jsonb, '学生 (xuésheng) means ''student''. 同学 (tóngxué) is a classmate, not a student in general.', '学生 (xuésheng) là học sinh, sinh viên — Hán-Việt chính là ''học sinh''. Đừng nhầm với 同学 (tóngxué – bạn học, bạn cùng lớp). Chữ 生 trong 学生 thường đọc thanh nhẹ.', '{"term":"学生","pinyin":"xuésheng","part_of_speech":"noun","meaning_vi":"học sinh, sinh viên","example":"我们都是学生。","example_pinyin":"Wǒmen dōu shì xuésheng.","example_vi":"Chúng tôi đều là học sinh."}'::jsonb),
  ('zh-vocab-hsk1-greet-05', 'zh-vocab-hsk1-greetings', 5, 'multiple_choice', 'HSK1', 'Use 名字 (míngzi) to ask someone''s name', '你叫什么___？', 'Bạn tên là gì?', '["名字","朋友","老师","同学"]'::jsonb, null, null, null, null, '名字', '["名字"]'::jsonb, '名字 (míngzi) means ''name''. 你叫什么名字？ is the standard way to ask ''What''s your name?''.', '名字 (míngzi) là tên. Câu 你叫什么名字？ là cách hỏi tên phổ biến nhất. Chữ 字 đọc thanh nhẹ. Hán-Việt ''danh tự'' (danh = tên).', '{"term":"名字","pinyin":"míngzi","part_of_speech":"noun","meaning_vi":"tên","example":"你的名字真好听。","example_pinyin":"Nǐ de míngzi zhēn hǎotīng.","example_vi":"Tên của em hay thật."}'::jsonb),
  ('zh-vocab-hsk1-greet-06', 'zh-vocab-hsk1-greetings', 6, 'multiple_choice', 'HSK1', 'Recognize the meaning of 再见 (zàijiàn)', '「再见」nghĩa là gì?', null, '["tạm biệt","xin chào","xin lỗi","cảm ơn"]'::jsonb, null, null, null, null, '再见', '["tạm biệt"]'::jsonb, '再见 (zàijiàn) means ''goodbye'' — literally ''see again''.', '再见 (zàijiàn) là tạm biệt. Hán-Việt ''tái kiến'' — ''tái'' là lại, ''kiến'' là gặp, tức là ''hẹn gặp lại''. Cả hai chữ đều thanh 4.', '{"term":"再见","pinyin":"zàijiàn","part_of_speech":"verb","meaning_vi":"tạm biệt, hẹn gặp lại","example":"再见，明天给你打电话！","example_pinyin":"Zàijiàn, míngtiān gěi nǐ dǎ diànhuà!","example_vi":"Tạm biệt, mai anh gọi cho em nhé!"}'::jsonb),
  ('zh-vocab-hsk1-greet-07', 'zh-vocab-hsk1-greetings', 7, 'multiple_choice', 'HSK1', 'Use 对不起 (duìbuqǐ) to apologize', '___，我来晚了。', 'Xin lỗi, anh đến muộn rồi.', '["对不起","谢谢","再见","认识"]'::jsonb, null, null, null, null, '对不起', '["对不起"]'::jsonb, '对不起 (duìbuqǐ) means ''sorry''. The usual reply is 没关系 (méi guānxi), ''it''s okay''.', '对不起 (duìbuqǐ) là xin lỗi. Chữ 不 ở giữa đọc thanh nhẹ. Khi ai đó xin lỗi mình, đáp lại bằng 没关系 (méi guānxi – không sao đâu).', '{"term":"对不起","pinyin":"duìbuqǐ","part_of_speech":"verb","meaning_vi":"xin lỗi","example":"对不起，我今天很忙。","example_pinyin":"Duìbuqǐ, wǒ jīntiān hěn máng.","example_vi":"Xin lỗi em, hôm nay anh bận quá."}'::jsonb),
  ('zh-vocab-hsk1-greet-08', 'zh-vocab-hsk1-greetings', 8, 'multiple_choice', 'HSK1', 'Recognize the meaning of 认识 (rènshi)', '「认识」nghĩa là gì?', null, '["quen biết","nhớ nhung","học tập","gặp lại"]'::jsonb, null, null, null, null, '认识', '["quen biết"]'::jsonb, '认识 (rènshi) means ''to know (a person), to get to know''. 很高兴认识你 means ''Nice to meet you''.', '认识 (rènshi) là quen, biết (một người). Hán-Việt ''nhận thức'', nhưng trong giao tiếp hằng ngày nó thường là ''quen biết''. Câu kinh điển: 很高兴认识你 – Rất vui được làm quen với bạn. Chữ 识 đọc thanh nhẹ.', '{"term":"认识","pinyin":"rènshi","part_of_speech":"verb","meaning_vi":"quen biết, nhận ra","example":"很高兴认识你。","example_pinyin":"Hěn gāoxìng rènshi nǐ.","example_vi":"Rất vui được làm quen với bạn."}'::jsonb),
  ('zh-vocab-hsk1-greet-09', 'zh-vocab-hsk1-greetings', 9, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''classmate'': 同学 (tóngxué)', 'Chọn từ có nghĩa là ''bạn học, bạn cùng lớp''', null, '["同学","同事","老师","学生"]'::jsonb, null, null, null, null, '同学', '["同学"]'::jsonb, '同学 (tóngxué) means ''classmate''. 同事 (tóngshì) is a colleague at work.', '同学 (tóngxué) là bạn học. Hán-Việt ''đồng học'' — cùng học. Dễ nhầm với 同事 (tóngshì – đồng sự, đồng nghiệp ở chỗ làm) và 学生 (học sinh nói chung).', '{"term":"同学","pinyin":"tóngxué","part_of_speech":"noun","meaning_vi":"bạn học, bạn cùng lớp","example":"她是我的大学同学。","example_pinyin":"Tā shì wǒ de dàxué tóngxué.","example_vi":"Cô ấy là bạn học đại học của tôi."}'::jsonb),
  ('zh-vocab-hsk1-greet-10', 'zh-vocab-hsk1-greetings', 10, 'multiple_choice', 'HSK1', 'Recognize the meaning of 妈妈 (māma)', '「妈妈」nghĩa là gì?', null, '["mẹ","bố","chị gái","bà"]'::jsonb, null, null, null, null, '妈妈', '["mẹ"]'::jsonb, '妈妈 (māma) means ''mom''. 爸爸 (bàba) is ''dad''.', '妈妈 (māma) là mẹ, chữ 妈 thứ hai đọc thanh nhẹ. Bộ 女 (nữ) bên trái gợi ý đây là người phụ nữ. Bố là 爸爸 (bàba).', '{"term":"妈妈","pinyin":"māma","part_of_speech":"noun","meaning_vi":"mẹ","example":"我妈妈很喜欢你。","example_pinyin":"Wǒ māma hěn xǐhuan nǐ.","example_vi":"Mẹ anh rất quý em."}'::jsonb),
  ('zh-vocab-hsk1-time-01', 'zh-vocab-hsk1-numbers-time', 1, 'multiple_choice', 'HSK1', 'Recognize the number 八 (bā)', '「八」là số mấy?', null, '["số 8","số 6","số 9","số 10"]'::jsonb, null, null, null, null, '八', '["số 8"]'::jsonb, '八 (bā) is the number 8. Six is 六 (liù), nine is 九 (jiǔ), ten is 十 (shí).', '八 (bā) là số 8, Hán-Việt ''bát''. Đừng nhầm với chữ 人 (rén – người) và 入 (rù – vào) vì nét khá giống nhau. Người Trung Quốc rất thích số 8 vì đọc gần giống 发 (fā – phát tài).', '{"term":"八","pinyin":"bā","part_of_speech":"number","meaning_vi":"số tám","example":"我们八点见。","example_pinyin":"Wǒmen bā diǎn jiàn.","example_vi":"Mình gặp nhau lúc 8 giờ nhé."}'::jsonb),
  ('zh-vocab-hsk1-time-02', 'zh-vocab-hsk1-numbers-time', 2, 'multiple_choice', 'HSK1', 'Use 岁 (suì) to say someone''s age', '你今年多大？——我二十五___。', 'Năm nay bạn bao nhiêu tuổi? — Tôi 25 tuổi.', '["岁","点","块","个"]'::jsonb, null, null, null, null, '岁', '["岁"]'::jsonb, '岁 (suì) means ''years old''. Put it right after the number: 二十五岁, 25 years old.', '岁 (suì) là tuổi, đứng ngay sau con số: 二十五岁 = 25 tuổi. Hán-Việt ''tuế'' (như ''vạn tuế''). Đừng nhầm với 点 (giờ) hay 块 (đồng, tệ).', '{"term":"岁","pinyin":"suì","part_of_speech":"measure_word","meaning_vi":"tuổi","example":"我妹妹今年十八岁。","example_pinyin":"Wǒ mèimei jīnnián shíbā suì.","example_vi":"Em gái tôi năm nay 18 tuổi."}'::jsonb),
  ('zh-vocab-hsk1-time-03', 'zh-vocab-hsk1-numbers-time', 3, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''today'': 今天 (jīntiān)', 'Chọn từ có nghĩa là ''hôm nay''', null, '["今天","明天","昨天","每天"]'::jsonb, null, null, null, null, '今天', '["今天"]'::jsonb, '今天 (jīntiān) means ''today''. 明天 is tomorrow, 昨天 is yesterday, 每天 is every day.', '今天 (jīntiān) là hôm nay. 今 Hán-Việt là ''kim'' (như ''kim nhật'', ''cổ kim''). Bộ ba cần nhớ: 昨天 (hôm qua) – 今天 (hôm nay) – 明天 (ngày mai).', '{"term":"今天","pinyin":"jīntiān","part_of_speech":"noun","meaning_vi":"hôm nay","example":"今天你忙吗？","example_pinyin":"Jīntiān nǐ máng ma?","example_vi":"Hôm nay em có bận không?"}'::jsonb),
  ('zh-vocab-hsk1-time-04', 'zh-vocab-hsk1-numbers-time', 4, 'multiple_choice', 'HSK1', 'Use 明天 (míngtiān) to talk about tomorrow', '今天是星期五，___是星期六。', 'Hôm nay là thứ Sáu, ngày mai là thứ Bảy.', '["明天","昨天","上午","现在"]'::jsonb, null, null, null, null, '明天', '["明天"]'::jsonb, '明天 (míngtiān) means ''tomorrow''. If today is Friday, tomorrow is Saturday.', '明天 (míngtiān) là ngày mai. Hôm nay thứ Sáu thì ngày mai là thứ Bảy, nên chọn 明天, không phải 昨天 (hôm qua). Chào tạm biệt kiểu 明天见 nghĩa là ''mai gặp nhé''.', '{"term":"明天","pinyin":"míngtiān","part_of_speech":"noun","meaning_vi":"ngày mai","example":"明天见！","example_pinyin":"Míngtiān jiàn!","example_vi":"Mai gặp nhé!"}'::jsonb),
  ('zh-vocab-hsk1-time-05', 'zh-vocab-hsk1-numbers-time', 5, 'multiple_choice', 'HSK1', 'Recognize the meaning of 现在 (xiànzài)', '「现在」nghĩa là gì?', null, '["bây giờ","hôm qua","buổi sáng","sau này"]'::jsonb, null, null, null, null, '现在', '["bây giờ"]'::jsonb, '现在 (xiànzài) means ''now''. 现在几点？ means ''What time is it now?''.', '现在 (xiànzài) là bây giờ, hiện tại — Hán-Việt chính là ''hiện tại''. Cả hai chữ đều thanh 4. Câu hay dùng: 现在几点？ – Bây giờ mấy giờ rồi?', '{"term":"现在","pinyin":"xiànzài","part_of_speech":"noun","meaning_vi":"bây giờ, hiện tại","example":"你那里现在几点？","example_pinyin":"Nǐ nàli xiànzài jǐ diǎn?","example_vi":"Chỗ em bây giờ là mấy giờ?"}'::jsonb),
  ('zh-vocab-hsk1-time-06', 'zh-vocab-hsk1-numbers-time', 6, 'multiple_choice', 'HSK1', 'Use 点 (diǎn) to tell the time', '现在几___？——三点。', 'Bây giờ mấy giờ? — Ba giờ.', '["点","岁","天","年"]'::jsonb, null, null, null, null, '点', '["点"]'::jsonb, '点 (diǎn) means ''o''clock''. 几点 asks ''what time'', and 三点 is three o''clock.', '点 (diǎn) dùng để nói giờ: 三点 = 3 giờ, 几点？ = mấy giờ? Hán-Việt ''điểm''. Đừng nhầm với 岁 (tuổi) hay 天 (ngày).', '{"term":"点","pinyin":"diǎn","part_of_speech":"measure_word","meaning_vi":"giờ (chỉ thời gian)","example":"我晚上十点给你打电话。","example_pinyin":"Wǒ wǎnshang shí diǎn gěi nǐ dǎ diànhuà.","example_vi":"Anh sẽ gọi cho em lúc 10 giờ tối."}'::jsonb),
  ('zh-vocab-hsk1-time-07', 'zh-vocab-hsk1-numbers-time', 7, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''week'': 星期 (xīngqī)', 'Chọn từ có nghĩa là ''tuần, thứ (trong tuần)''', null, '["星期","时候","上午","今天"]'::jsonb, null, null, null, null, '星期', '["星期"]'::jsonb, '星期 (xīngqī) means ''week''. Add a number for the weekday: 星期一 is Monday, and Sunday is 星期天 or 星期日.', '星期 (xīngqī) là tuần, thứ trong tuần. Cẩn thận: 星期一 là thứ Hai (không phải thứ Nhất), 星期二 là thứ Ba… nghĩa là con số luôn nhỏ hơn tiếng Việt 1 đơn vị. Chủ nhật là 星期天 hoặc 星期日.', '{"term":"星期","pinyin":"xīngqī","part_of_speech":"noun","meaning_vi":"tuần; thứ (trong tuần)","example":"下个星期我们见面吧。","example_pinyin":"Xià ge xīngqī wǒmen jiànmiàn ba.","example_vi":"Tuần sau mình gặp nhau nhé."}'::jsonb),
  ('zh-vocab-hsk1-time-08', 'zh-vocab-hsk1-numbers-time', 8, 'multiple_choice', 'HSK1', 'Recognize the meaning of 上午 (shàngwǔ)', '「上午」nghĩa là gì?', null, '["buổi sáng (trước 12 giờ trưa)","buổi chiều","buổi tối","nửa đêm"]'::jsonb, null, null, null, null, '上午', '["buổi sáng (trước 12 giờ trưa)"]'::jsonb, '上午 (shàngwǔ) means ''morning, before noon''. 下午 (xiàwǔ) is the afternoon.', '上午 (shàngwǔ) là buổi sáng, khoảng thời gian trước 12 giờ trưa. 午 Hán-Việt là ''ngọ'' (giờ ngọ = giữa trưa): 上午 là trước trưa, 中午 là buổi trưa, 下午 là buổi chiều.', '{"term":"上午","pinyin":"shàngwǔ","part_of_speech":"noun","meaning_vi":"buổi sáng (trước trưa)","example":"我上午有课。","example_pinyin":"Wǒ shàngwǔ yǒu kè.","example_vi":"Buổi sáng tôi có tiết học."}'::jsonb),
  ('zh-vocab-hsk1-time-09', 'zh-vocab-hsk1-numbers-time', 9, 'multiple_choice', 'HSK1', 'Use 睡觉 (shuìjiào) to talk about going to sleep', '很晚了，你快去___吧。', 'Khuya rồi, em mau đi ngủ đi.', '["睡觉","认识","喝","现在"]'::jsonb, null, null, null, null, '睡觉', '["睡觉"]'::jsonb, '睡觉 (shuìjiào) means ''to sleep, to go to bed''. Here 觉 is read jiào, not jué.', '睡觉 (shuìjiào) là đi ngủ. Chú ý chữ 觉 có hai cách đọc: trong 睡觉 đọc là jiào, còn trong 觉得 (cảm thấy) đọc là jué. Câu 快去睡觉吧 là lời nhắc ngọt ngào mỗi tối đó!', '{"term":"睡觉","pinyin":"shuìjiào","part_of_speech":"verb","meaning_vi":"ngủ, đi ngủ","example":"你几点睡觉？","example_pinyin":"Nǐ jǐ diǎn shuìjiào?","example_vi":"Em mấy giờ đi ngủ?"}'::jsonb),
  ('zh-vocab-hsk1-time-10', 'zh-vocab-hsk1-numbers-time', 10, 'multiple_choice', 'HSK1', 'Recall the Chinese word for ''to drink'': 喝 (hē)', 'Chọn từ có nghĩa là ''uống''', null, '["喝","吃","看","睡"]'::jsonb, null, null, null, null, '喝', '["喝"]'::jsonb, '喝 (hē) means ''to drink''. 吃 (chī) means ''to eat''.', '喝 (hē) là uống, thanh 1. Bộ 口 (miệng) bên trái gợi ý hành động bằng miệng. Đừng nhầm với 吃 (chī – ăn), cũng có bộ 口: 喝水 (uống nước), 吃饭 (ăn cơm).', '{"term":"喝","pinyin":"hē","part_of_speech":"verb","meaning_vi":"uống","example":"你想喝什么？","example_pinyin":"Nǐ xiǎng hē shénme?","example_vi":"Em muốn uống gì?"}'::jsonb),
  ('zh-vocab-hsk2-feel-01', 'zh-vocab-hsk2-feelings', 1, 'multiple_choice', 'HSK2', 'Use 想 (xiǎng) to say you miss someone', '我很___你，你什么时候回来？', 'Anh rất nhớ em, khi nào em về?', '["想","送","告诉","等"]'::jsonb, null, null, null, null, '想', '["想"]'::jsonb, '想 (xiǎng) means ''to miss (someone)'' when followed by a person. It also means ''to want'' or ''to think''.', '想 (xiǎng) có nhiều nghĩa: 想你 là nhớ em, 想吃 là muốn ăn, 我想… là tôi nghĩ… Hán-Việt ''tưởng'' (tưởng nhớ). 我很想你 hoặc 我好想你 là câu ''anh nhớ em lắm'' mà các cặp đôi yêu xa dùng hằng ngày.', '{"term":"想","pinyin":"xiǎng","part_of_speech":"verb","meaning_vi":"nhớ; muốn; nghĩ","example":"我好想你。","example_pinyin":"Wǒ hǎo xiǎng nǐ.","example_vi":"Anh nhớ em lắm."}'::jsonb),
  ('zh-vocab-hsk2-feel-02', 'zh-vocab-hsk2-feelings', 2, 'multiple_choice', 'HSK2', 'Recognize the meaning of 喜欢 (xǐhuan)', '「喜欢」nghĩa là gì?', null, '["thích","ghét","sợ","đợi"]'::jsonb, null, null, null, null, '喜欢', '["thích"]'::jsonb, '喜欢 (xǐhuan) means ''to like''. 欢 is read in the neutral tone.', '喜欢 (xǐhuan) là thích. Hán-Việt ''hỉ hoan'' (vui mừng). Chữ 欢 đọc thanh nhẹ. 我喜欢你 (anh thích em) nhẹ nhàng hơn 我爱你 (anh yêu em).', '{"term":"喜欢","pinyin":"xǐhuan","part_of_speech":"verb","meaning_vi":"thích","example":"我喜欢和你说话。","example_pinyin":"Wǒ xǐhuan hé nǐ shuōhuà.","example_vi":"Anh thích nói chuyện với em."}'::jsonb),
  ('zh-vocab-hsk2-feel-03', 'zh-vocab-hsk2-feelings', 3, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''happy, glad'': 高兴 (gāoxìng)', 'Chọn từ có nghĩa là ''vui, vui mừng''', null, '["高兴","漂亮","累","饿"]'::jsonb, null, null, null, null, '高兴', '["高兴"]'::jsonb, '高兴 (gāoxìng) means ''happy, glad''. 很高兴认识你 means ''Glad to meet you''.', '高兴 (gāoxìng) là vui, vui mừng. Hán-Việt ''cao hứng''. Chú ý 兴 ở đây đọc xìng (thanh 4). Các từ còn lại: 漂亮 (đẹp), 累 (mệt), 饿 (đói).', '{"term":"高兴","pinyin":"gāoxìng","part_of_speech":"adjective","meaning_vi":"vui, vui mừng","example":"看到你，我很高兴。","example_pinyin":"Kàndào nǐ, wǒ hěn gāoxìng.","example_vi":"Được gặp em, anh rất vui."}'::jsonb),
  ('zh-vocab-hsk2-feel-04', 'zh-vocab-hsk2-feelings', 4, 'multiple_choice', 'HSK2', 'Use 快乐 (kuàilè) in birthday wishes', '生日___！', 'Chúc mừng sinh nhật!', '["快乐","高兴","希望","爱"]'::jsonb, null, null, null, null, '快乐', '["快乐"]'::jsonb, '快乐 (kuàilè) means ''happy, joyful'' and is the fixed word in wishes: 生日快乐 (Happy birthday), 新年快乐 (Happy New Year).', '快乐 (kuàilè) là vui vẻ, hạnh phúc — Hán-Việt ''khoái lạc''. Trong lời chúc luôn dùng 快乐: 生日快乐, 新年快乐. Không nói ''生日高兴'' — 高兴 thường dùng để tả cảm xúc lúc đó (我很高兴), không dùng trong câu chúc.', '{"term":"快乐","pinyin":"kuàilè","part_of_speech":"adjective","meaning_vi":"vui vẻ, hạnh phúc","example":"祝你每天都快乐！","example_pinyin":"Zhù nǐ měi tiān dōu kuàilè!","example_vi":"Chúc em ngày nào cũng vui vẻ!"}'::jsonb),
  ('zh-vocab-hsk2-feel-05', 'zh-vocab-hsk2-feelings', 5, 'multiple_choice', 'HSK2', 'Recognize the meaning of 爱 (ài)', '「爱」nghĩa là gì?', null, '["yêu","ghét","quen biết","đợi"]'::jsonb, null, null, null, null, '爱', '["yêu"]'::jsonb, '爱 (ài) means ''to love''. 我爱你 means ''I love you''.', '爱 (ài) là yêu, thương — Hán-Việt ''ái'' (như ái tình, ân ái). Thanh 4, đọc dứt khoát. 我爱你 (Wǒ ài nǐ) là câu đáng học nhất trong bài này đó!', '{"term":"爱","pinyin":"ài","part_of_speech":"verb","meaning_vi":"yêu, thương","example":"我爱你。","example_pinyin":"Wǒ ài nǐ.","example_vi":"Anh yêu em."}'::jsonb),
  ('zh-vocab-hsk2-feel-06', 'zh-vocab-hsk2-feelings', 6, 'multiple_choice', 'HSK2', 'Use 送 (sòng) to talk about giving a gift', '你生日的时候，我想___你一个礼物。', 'Vào sinh nhật em, anh muốn tặng em một món quà.', '["送","等","爱","希望"]'::jsonb, null, null, null, null, '送', '["送"]'::jsonb, '送 (sòng) means ''to give (as a gift)''. It can also mean ''to see someone off''.', '送 (sòng) là tặng: 送你一个礼物 = tặng em một món quà. Nó còn có nghĩa là tiễn, đưa: 送你去机场 (đưa em ra sân bay). Hán-Việt ''tống'' (như tống tiễn).', '{"term":"送","pinyin":"sòng","part_of_speech":"verb","meaning_vi":"tặng; tiễn, đưa","example":"这是我送你的礼物。","example_pinyin":"Zhè shì wǒ sòng nǐ de lǐwù.","example_vi":"Đây là món quà anh tặng em."}'::jsonb),
  ('zh-vocab-hsk2-feel-07', 'zh-vocab-hsk2-feelings', 7, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''birthday'': 生日 (shēngrì)', 'Chọn từ có nghĩa là ''sinh nhật''', null, '["生日","生活","节日","日期"]'::jsonb, null, null, null, null, '生日', '["生日"]'::jsonb, '生日 (shēngrì) means ''birthday''. 生活 (shēnghuó) means ''life''.', '生日 (shēngrì) là sinh nhật — Hán-Việt chính là ''sinh nhật''! Dễ nhầm với 生活 (sinh hoạt, cuộc sống), 节日 (ngày lễ) và 日期 (ngày tháng).', '{"term":"生日","pinyin":"shēngrì","part_of_speech":"noun","meaning_vi":"sinh nhật","example":"你的生日是几月几号？","example_pinyin":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","example_vi":"Sinh nhật em là ngày mấy tháng mấy?"}'::jsonb),
  ('zh-vocab-hsk2-feel-08', 'zh-vocab-hsk2-feelings', 8, 'multiple_choice', 'HSK2', 'Recognize the meaning of 希望 (xīwàng)', '「希望」nghĩa là gì?', null, '["hy vọng, mong","thất vọng","nhớ nhung","chờ đợi"]'::jsonb, null, null, null, null, '希望', '["hy vọng, mong"]'::jsonb, '希望 (xīwàng) means ''to hope, to wish'' and also ''hope'' as a noun.', '希望 (xīwàng) là hy vọng, mong muốn — Hán-Việt chính là ''hy vọng''. Đặt trước cả một câu: 希望我们很快见面 (Mong chúng mình sớm gặp nhau). Thất vọng là 失望 (shīwàng), chỉ khác một chữ.', '{"term":"希望","pinyin":"xīwàng","part_of_speech":"verb","meaning_vi":"hy vọng, mong","example":"希望我们很快见面。","example_pinyin":"Xīwàng wǒmen hěn kuài jiànmiàn.","example_vi":"Mong chúng mình sớm gặp nhau."}'::jsonb),
  ('zh-vocab-hsk2-feel-09', 'zh-vocab-hsk2-feelings', 9, 'multiple_choice', 'HSK2', 'Use 告诉 (gàosu) to tell someone news', '我___你一个好消息：下个月我去看你！', 'Anh báo cho em một tin vui: tháng sau anh sang thăm em!', '["告诉","希望","等","爱"]'::jsonb, null, null, null, null, '告诉', '["告诉"]'::jsonb, '告诉 (gàosu) means ''to tell (someone something)''. 诉 is read in the neutral tone.', '告诉 (gàosu) là nói cho biết, báo cho: 告诉你 = nói cho em biết. Hán-Việt ''cáo tố''. Chữ 诉 đọc thanh nhẹ. Khác với 说 (nói) ở chỗ 告诉 luôn có người nghe đi kèm: 告诉我 (nói cho anh biết).', '{"term":"告诉","pinyin":"gàosu","part_of_speech":"verb","meaning_vi":"nói cho biết, báo cho","example":"你可以告诉我你的想法。","example_pinyin":"Nǐ kěyǐ gàosu wǒ nǐ de xiǎngfǎ.","example_vi":"Em có thể nói cho anh biết suy nghĩ của em."}'::jsonb),
  ('zh-vocab-hsk2-feel-10', 'zh-vocab-hsk2-feelings', 10, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''to wait'': 等 (děng)', 'Chọn từ có nghĩa là ''đợi, chờ''', null, '["等","想","送","走"]'::jsonb, null, null, null, null, '等', '["等"]'::jsonb, '等 (děng) means ''to wait''. 等我 means ''wait for me''.', '等 (děng) là đợi, chờ, thanh 3. 等我 = đợi anh nhé; 我等你 = anh đợi em. Hán-Việt ''đẳng'' (đẳng cấp) — nghĩa đó dùng trong từ khác, còn trong giao tiếp 等 chủ yếu là ''đợi''.', '{"term":"等","pinyin":"děng","part_of_speech":"verb","meaning_vi":"đợi, chờ","example":"我在机场等你。","example_pinyin":"Wǒ zài jīchǎng děng nǐ.","example_vi":"Anh đợi em ở sân bay."}'::jsonb),
  ('zh-vocab-hsk2-food-01', 'zh-vocab-hsk2-food-shopping', 1, 'multiple_choice', 'HSK2', 'Recognize the meaning of 米饭 (mǐfàn)', '「米饭」nghĩa là gì?', null, '["cơm","mì","bánh bao","cháo"]'::jsonb, null, null, null, null, '米饭', '["cơm"]'::jsonb, '米饭 (mǐfàn) means ''cooked rice''. Noodles are 面条 (miàntiáo).', '米饭 (mǐfàn) là cơm (gạo đã nấu chín). Hán-Việt ''mễ phạn'' — ''mễ'' là gạo, ''phạn'' là cơm. Mì là 面条 (miàntiáo), cháo là 粥 (zhōu).', '{"term":"米饭","pinyin":"mǐfàn","part_of_speech":"noun","meaning_vi":"cơm","example":"我想吃米饭。","example_pinyin":"Wǒ xiǎng chī mǐfàn.","example_vi":"Tôi muốn ăn cơm."}'::jsonb),
  ('zh-vocab-hsk2-food-02', 'zh-vocab-hsk2-food-shopping', 2, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''fruit'': 水果 (shuǐguǒ)', 'Chọn từ có nghĩa là ''trái cây, hoa quả (nói chung)''', null, '["水果","水","苹果","菜"]'::jsonb, null, null, null, null, '水果', '["水果"]'::jsonb, '水果 (shuǐguǒ) means ''fruit'' in general. 苹果 (píngguǒ) is one fruit: an apple.', '水果 (shuǐguǒ) là trái cây nói chung. 苹果 (píngguǒ) chỉ là quả táo. Lưu ý 水 và 果 đều thanh 3, khi đọc liền thì 水 biến thành gần như thanh 2: shuí guǒ.', '{"term":"水果","pinyin":"shuǐguǒ","part_of_speech":"noun","meaning_vi":"trái cây, hoa quả","example":"多吃水果对身体好。","example_pinyin":"Duō chī shuǐguǒ duì shēntǐ hǎo.","example_vi":"Ăn nhiều trái cây tốt cho sức khỏe."}'::jsonb),
  ('zh-vocab-hsk2-food-03', 'zh-vocab-hsk2-food-shopping', 3, 'multiple_choice', 'HSK2', 'Use 鸡蛋 (jīdàn) in a sentence about food', '我早上吃了两个___。', 'Sáng nay tôi đã ăn hai quả trứng gà.', '["鸡蛋","水","商店","贵"]'::jsonb, null, null, null, null, '鸡蛋', '["鸡蛋"]'::jsonb, '鸡蛋 (jīdàn) means ''chicken egg''. You count eggs with 个: 两个鸡蛋.', '鸡蛋 (jīdàn) là trứng gà: 鸡 là con gà, 蛋 là trứng. Đếm trứng dùng lượng từ 个: 两个鸡蛋 (hai quả trứng). Món quen thuộc: 西红柿炒鸡蛋 – trứng xào cà chua.', '{"term":"鸡蛋","pinyin":"jīdàn","part_of_speech":"noun","meaning_vi":"trứng gà","example":"我会做西红柿炒鸡蛋。","example_pinyin":"Wǒ huì zuò xīhóngshì chǎo jīdàn.","example_vi":"Anh biết làm món trứng xào cà chua."}'::jsonb),
  ('zh-vocab-hsk2-food-04', 'zh-vocab-hsk2-food-shopping', 4, 'multiple_choice', 'HSK2', 'Recognize the meaning of 便宜 (piányi)', '「便宜」nghĩa là gì?', null, '["rẻ","đắt","ngon","mới"]'::jsonb, null, null, null, null, '便宜', '["rẻ"]'::jsonb, '便宜 (piányi) means ''cheap, inexpensive''. Here 便 is read pián, not biàn.', '便宜 (piányi) là rẻ. Bẫy phát âm: trong từ này 便 đọc là pián, còn trong 方便 (fāngbiàn – tiện lợi) lại đọc là biàn. Chữ 宜 đọc thanh nhẹ. Trái nghĩa là 贵 (đắt).', '{"term":"便宜","pinyin":"piányi","part_of_speech":"adjective","meaning_vi":"rẻ","example":"这里的水果很便宜。","example_pinyin":"Zhèli de shuǐguǒ hěn piányi.","example_vi":"Trái cây ở đây rất rẻ."}'::jsonb),
  ('zh-vocab-hsk2-food-05', 'zh-vocab-hsk2-food-shopping', 5, 'multiple_choice', 'HSK2', 'Use 贵 (guì) to say something is expensive', '这件衣服太___了，三千块！', 'Cái áo này đắt quá, những ba nghìn tệ!', '["贵","便宜","好吃","饿"]'::jsonb, null, null, null, null, '贵', '["贵"]'::jsonb, '贵 (guì) means ''expensive''. 太贵了 means ''too expensive''.', '贵 (guì) là đắt. 太贵了！ (Đắt quá!) là câu rất hữu ích khi mặc cả. Hán-Việt ''quý'' — đồ quý thì đắt. 贵 cũng có trong câu lịch sự 您贵姓？ (Quý danh của ngài là gì?).', '{"term":"贵","pinyin":"guì","part_of_speech":"adjective","meaning_vi":"đắt, quý","example":"这个手机太贵了。","example_pinyin":"Zhège shǒujī tài guì le.","example_vi":"Cái điện thoại này đắt quá."}'::jsonb),
  ('zh-vocab-hsk2-food-06', 'zh-vocab-hsk2-food-shopping', 6, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''to sell'': 卖 (mài)', 'Chọn từ có nghĩa là ''bán''', null, '["卖","买","送","看"]'::jsonb, null, null, null, null, '卖', '["卖"]'::jsonb, '卖 (mài, 4th tone) means ''to sell''. 买 (mǎi, 3rd tone) means ''to buy''.', '卖 (mài – thanh 4) là bán, còn 买 (mǎi – thanh 3) là mua. Mẹo nhớ: 卖 có thêm chữ 十 ở trên — phải ''có thêm'' hàng mới đem bán được. Nói sai thanh điệu là mua thành bán đấy!', '{"term":"卖","pinyin":"mài","part_of_speech":"verb","meaning_vi":"bán","example":"这个商店卖水果吗？","example_pinyin":"Zhège shāngdiàn mài shuǐguǒ ma?","example_vi":"Cửa hàng này có bán trái cây không?"}'::jsonb),
  ('zh-vocab-hsk2-food-07', 'zh-vocab-hsk2-food-shopping', 7, 'multiple_choice', 'HSK2', 'Use 块 (kuài) to talk about prices', '这个苹果五___钱。', 'Quả táo này giá năm tệ.', '["块","岁","点","个"]'::jsonb, null, null, null, null, '块', '["块"]'::jsonb, '块 (kuài) is the spoken word for the yuan, China''s money: 五块钱 means ''five yuan''.', '块 (kuài) là cách nói khẩu ngữ của ''tệ'' (đồng nhân dân tệ), tương đương 元 (yuán) trong văn viết. 五块钱 = 5 tệ. Đừng nhầm với 岁 (tuổi) hay 点 (giờ).', '{"term":"块","pinyin":"kuài","part_of_speech":"measure_word","meaning_vi":"đồng, tệ (đơn vị tiền, khẩu ngữ); miếng","example":"这杯咖啡二十块。","example_pinyin":"Zhè bēi kāfēi èrshí kuài.","example_vi":"Cốc cà phê này 20 tệ."}'::jsonb),
  ('zh-vocab-hsk2-food-08', 'zh-vocab-hsk2-food-shopping', 8, 'multiple_choice', 'HSK2', 'Recognize the meaning of 商店 (shāngdiàn)', '「商店」nghĩa là gì?', null, '["cửa hàng","nhà hàng","trường học","bệnh viện"]'::jsonb, null, null, null, null, '商店', '["cửa hàng"]'::jsonb, '商店 (shāngdiàn) means ''shop, store''. A restaurant is 饭馆 (fànguǎn).', '商店 (shāngdiàn) là cửa hàng, tiệm. Hán-Việt ''thương điếm'' — ''thương'' như thương mại, ''điếm'' là tiệm. Nhà hàng thì là 饭馆 (fànguǎn), đừng nhầm nhé.', '{"term":"商店","pinyin":"shāngdiàn","part_of_speech":"noun","meaning_vi":"cửa hàng","example":"我去商店买东西。","example_pinyin":"Wǒ qù shāngdiàn mǎi dōngxi.","example_vi":"Tôi đi cửa hàng mua đồ."}'::jsonb),
  ('zh-vocab-hsk2-food-09', 'zh-vocab-hsk2-food-shopping', 9, 'multiple_choice', 'HSK2', 'Use 好吃 (hǎochī) to say food is delicious', '妈妈做的菜很___。', 'Đồ ăn mẹ nấu rất ngon.', '["好吃","好喝","商店","鸡蛋"]'::jsonb, null, null, null, null, '好吃', '["好吃"]'::jsonb, '好吃 (hǎochī) means ''delicious'' for food. For drinks, use 好喝 (hǎohē).', '好吃 (hǎochī) là ngon (dùng cho đồ ăn) — nghĩa đen là ''dễ ăn''. Đồ uống ngon thì dùng 好喝 (hǎohē). Cùng kiểu: 好看 (đẹp, hay – để xem), 好听 (hay – để nghe).', '{"term":"好吃","pinyin":"hǎochī","part_of_speech":"adjective","meaning_vi":"ngon (đồ ăn)","example":"这个菜真好吃！","example_pinyin":"Zhège cài zhēn hǎochī!","example_vi":"Món này ngon thật!"}'::jsonb),
  ('zh-vocab-hsk2-food-10', 'zh-vocab-hsk2-food-shopping', 10, 'multiple_choice', 'HSK2', 'Recall the Chinese word for ''dish, vegetable'': 菜 (cài)', 'Chọn từ có nghĩa là ''món ăn; rau''', null, '["菜","茶","水","钱"]'::jsonb, null, null, null, null, '菜', '["菜"]'::jsonb, '菜 (cài) means ''dish (of food)'' and also ''vegetable''. 茶 (chá) is tea.', '菜 (cài) vừa là món ăn vừa là rau. Hán-Việt là ''thái''. 中国菜 là món ăn Trung Quốc, 点菜 là gọi món. Đừng nhầm với 茶 (chá – trà), hai chữ đều có bộ thảo 艹 ở trên.', '{"term":"菜","pinyin":"cài","part_of_speech":"noun","meaning_vi":"món ăn; rau","example":"我给你做中国菜。","example_pinyin":"Wǒ gěi nǐ zuò Zhōngguó cài.","example_vi":"Anh nấu món Trung Quốc cho em ăn."}'::jsonb),
  ('zh-vocab-hsk3-work-01', 'zh-vocab-hsk3-study-work', 1, 'multiple_choice', 'HSK3', 'Recognize the meaning of 考试 (kǎoshì)', '「考试」nghĩa là gì?', null, '["thi, kỳ thi","bài tập về nhà","ôn tập","cuộc họp"]'::jsonb, null, null, null, null, '考试', '["thi, kỳ thi"]'::jsonb, '考试 (kǎoshì) means ''exam'' or ''to take an exam''.', '考试 (kǎoshì) là thi, kỳ thi. Hán-Việt ''khảo thí'' (như khảo sát, thí sinh). Vừa là danh từ (明天有考试 – mai có bài thi) vừa là động từ (我在考试 – tôi đang thi).', '{"term":"考试","pinyin":"kǎoshì","part_of_speech":"noun","meaning_vi":"kỳ thi; thi","example":"明天我有汉语考试。","example_pinyin":"Míngtiān wǒ yǒu Hànyǔ kǎoshì.","example_vi":"Ngày mai tôi có bài thi tiếng Trung."}'::jsonb),
  ('zh-vocab-hsk3-work-02', 'zh-vocab-hsk3-study-work', 2, 'multiple_choice', 'HSK3', 'Use 打算 (dǎsuan) to ask about plans', '这个周末你___做什么？', 'Cuối tuần này em định làm gì?', '["打算","复习","练习","认真"]'::jsonb, null, null, null, null, '打算', '["打算"]'::jsonb, '打算 (dǎsuan) means ''to plan, to intend''. It goes before the planned action: 打算做什么, plan to do what.', '打算 (dǎsuan) là định, dự định. Đặt trước động từ: 你打算做什么？ = Em định làm gì? Nghĩa đen là ''tính toán'', giống tiếng Việt mình hay nói ''em tính làm gì?''. Chữ 算 thường đọc thanh nhẹ.', '{"term":"打算","pinyin":"dǎsuan","part_of_speech":"verb","meaning_vi":"định, dự định","example":"你打算什么时候来看我？","example_pinyin":"Nǐ dǎsuan shénme shíhou lái kàn wǒ?","example_vi":"Khi nào em định đến thăm anh?"}'::jsonb),
  ('zh-vocab-hsk3-work-03', 'zh-vocab-hsk3-study-work', 3, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''to prepare'': 准备 (zhǔnbèi)', 'Chọn từ có nghĩa là ''chuẩn bị''', null, '["准备","打算","练习","复习"]'::jsonb, null, null, null, null, '准备', '["准备"]'::jsonb, '准备 (zhǔnbèi) means ''to prepare, to get ready''. 打算 (dǎsuan) means ''to plan''.', '准备 (zhǔnbèi) là chuẩn bị — Hán-Việt y hệt ''chuẩn bị''. Chú ý chữ 准 (zhǔn) có bộ băng 冫 hai chấm, không phải ba chấm thủy. Đừng nhầm với 打算 (định, dự định).', '{"term":"准备","pinyin":"zhǔnbèi","part_of_speech":"verb","meaning_vi":"chuẩn bị","example":"我在准备明天的考试。","example_pinyin":"Wǒ zài zhǔnbèi míngtiān de kǎoshì.","example_vi":"Anh đang chuẩn bị cho bài thi ngày mai."}'::jsonb),
  ('zh-vocab-hsk3-work-04', 'zh-vocab-hsk3-study-work', 4, 'multiple_choice', 'HSK3', 'Recognize the meaning of 公司 (gōngsī)', '「公司」nghĩa là gì?', null, '["công ty","công viên","trường học","cửa hàng"]'::jsonb, null, null, null, null, '公司', '["công ty"]'::jsonb, '公司 (gōngsī) means ''company''. 公园 (gōngyuán) means ''park''.', '公司 (gōngsī) là công ty — Hán-Việt ''công ty'', rất dễ nhớ. Cẩn thận đừng nhầm với 公园 (gōngyuán – công viên). Cả hai chữ của 公司 đều thanh 1.', '{"term":"公司","pinyin":"gōngsī","part_of_speech":"noun","meaning_vi":"công ty","example":"她在中国公司工作。","example_pinyin":"Tā zài Zhōngguó gōngsī gōngzuò.","example_vi":"Cô ấy làm việc ở công ty Trung Quốc."}'::jsonb),
  ('zh-vocab-hsk3-work-05', 'zh-vocab-hsk3-study-work', 5, 'multiple_choice', 'HSK3', 'Use 作业 (zuòyè) to talk about homework', '我做完___了，现在给你打电话。', 'Anh làm xong bài tập rồi, giờ gọi điện cho em đây.', '["作业","公司","努力","认真"]'::jsonb, null, null, null, null, '作业', '["作业"]'::jsonb, '作业 (zuòyè) means ''homework, assignment''. 做作业 means ''to do homework''.', '作业 (zuòyè) là bài tập (về nhà). Hán-Việt ''tác nghiệp''. Cụm hay dùng: 做作业 (làm bài tập), 做完作业 (làm xong bài tập). Chú ý 做 và 作 đều đọc zuò nhưng là hai chữ khác nhau.', '{"term":"作业","pinyin":"zuòyè","part_of_speech":"noun","meaning_vi":"bài tập (về nhà)","example":"今天的作业很多。","example_pinyin":"Jīntiān de zuòyè hěn duō.","example_vi":"Bài tập hôm nay nhiều lắm."}'::jsonb),
  ('zh-vocab-hsk3-work-06', 'zh-vocab-hsk3-study-work', 6, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''to practice'': 练习 (liànxí)', 'Chọn từ có nghĩa là ''luyện tập''', null, '["练习","复习","学习","准备"]'::jsonb, null, null, null, null, '练习', '["练习"]'::jsonb, '练习 (liànxí) means ''to practice'' or ''an exercise''. 复习 (fùxí) means ''to review''.', '练习 (liànxí) là luyện tập — Hán-Việt y hệt ''luyện tập''. Ba từ cùng chữ 习 dễ nhầm: 学习 (học tập), 复习 (ôn tập), 练习 (luyện tập).', '{"term":"练习","pinyin":"liànxí","part_of_speech":"verb","meaning_vi":"luyện tập; bài luyện tập","example":"我们每天用汉语练习说话吧。","example_pinyin":"Wǒmen měi tiān yòng Hànyǔ liànxí shuōhuà ba.","example_vi":"Mỗi ngày mình dùng tiếng Trung luyện nói với nhau nhé."}'::jsonb),
  ('zh-vocab-hsk3-work-07', 'zh-vocab-hsk3-study-work', 7, 'multiple_choice', 'HSK3', 'Recognize the meaning of 复习 (fùxí)', '「复习」nghĩa là gì?', null, '["ôn tập, ôn bài","luyện tập","học trước bài mới","đi thi"]'::jsonb, null, null, null, null, '复习', '["ôn tập, ôn bài"]'::jsonb, '复习 (fùxí) means ''to review (what you''ve learned)''. Previewing new lessons is 预习 (yùxí).', '复习 (fùxí) là ôn tập, ôn lại bài cũ. Hán-Việt ''phục tập'' — ''phục'' là lặp lại (như phục hồi). Học trước bài mới là 预习 (yùxí – dự tập), đừng nhầm nhé.', '{"term":"复习","pinyin":"fùxí","part_of_speech":"verb","meaning_vi":"ôn tập","example":"考试前要复习。","example_pinyin":"Kǎoshì qián yào fùxí.","example_vi":"Trước khi thi phải ôn bài."}'::jsonb),
  ('zh-vocab-hsk3-work-08', 'zh-vocab-hsk3-study-work', 8, 'multiple_choice', 'HSK3', 'Use 上班 (shàngbān) to talk about going to work', '我每天早上八点去公司___。', 'Mỗi sáng tôi đến công ty làm việc lúc 8 giờ.', '["上班","作业","认真","努力"]'::jsonb, null, null, null, null, '上班', '["上班"]'::jsonb, '上班 (shàngbān) means ''to go to work, to be at work''. The opposite is 下班 (xiàbān), ''to get off work''.', '上班 (shàngbān) là đi làm, vào ca. Trái nghĩa là 下班 (xiàbān – tan làm). Hán-Việt ''thượng ban'' — ''ban'' là ca làm việc. Câu hỏi thăm dễ thương: 你下班了吗？ – Em tan làm chưa?', '{"term":"上班","pinyin":"shàngbān","part_of_speech":"verb","meaning_vi":"đi làm","example":"你明天几点上班？","example_pinyin":"Nǐ míngtiān jǐ diǎn shàngbān?","example_vi":"Mai mấy giờ em đi làm?"}'::jsonb),
  ('zh-vocab-hsk3-work-09', 'zh-vocab-hsk3-study-work', 9, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''serious, conscientious'': 认真 (rènzhēn)', 'Chọn từ có nghĩa là ''nghiêm túc, chăm chú''', null, '["认真","认识","真正","当然"]'::jsonb, null, null, null, null, '认真', '["认真"]'::jsonb, '认真 (rènzhēn) means ''serious, conscientious, careful''. 认识 (rènshi) means ''to know someone''.', '认真 (rènzhēn) là nghiêm túc, chăm chỉ cẩn thận. Hán-Việt ''nhận chân''. Đừng nhầm với 认识 (rènshi – quen biết): cùng chữ 认 nhưng nghĩa khác hẳn. 学习很认真 = học hành rất chăm chỉ, nghiêm túc.', '{"term":"认真","pinyin":"rènzhēn","part_of_speech":"adjective","meaning_vi":"nghiêm túc, chăm chú, cẩn thận","example":"他学习很认真。","example_pinyin":"Tā xuéxí hěn rènzhēn.","example_vi":"Anh ấy học hành rất nghiêm túc."}'::jsonb),
  ('zh-vocab-hsk3-work-10', 'zh-vocab-hsk3-study-work', 10, 'multiple_choice', 'HSK3', 'Use 努力 (nǔlì) to talk about working hard', '为了我们的未来，我会___工作。', 'Vì tương lai của chúng mình, anh sẽ làm việc chăm chỉ.', '["努力","复习","公司","作业"]'::jsonb, null, null, null, null, '努力', '["努力"]'::jsonb, '努力 (nǔlì) means ''hard-working, to make an effort''. 努力工作 means ''to work hard''.', '努力 (nǔlì) là cố gắng, nỗ lực — Hán-Việt chính là ''nỗ lực''. Đặt trước động từ: 努力工作 (làm việc chăm chỉ), 努力学习 (học hành chăm chỉ). Chú ý 努 thanh 3, 力 thanh 4.', '{"term":"努力","pinyin":"nǔlì","part_of_speech":"adjective","meaning_vi":"cố gắng, nỗ lực, chăm chỉ","example":"我们都要努力！","example_pinyin":"Wǒmen dōu yào nǔlì!","example_vi":"Cả hai chúng mình đều phải cố gắng nhé!"}'::jsonb),
  ('zh-vocab-hsk3-travel-01', 'zh-vocab-hsk3-travel', 1, 'multiple_choice', 'HSK3', 'Recognize the meaning of 旅游 (lǚyóu)', '「旅游」nghĩa là gì?', null, '["du lịch","làm việc","học tập","mua sắm"]'::jsonb, null, null, null, null, '旅游', '["du lịch"]'::jsonb, '旅游 (lǚyóu) means ''to travel, to tour''.', '旅游 (lǚyóu) là đi du lịch. Hán-Việt ''lữ du'' (lữ khách, du lịch). Chú ý 旅 đọc lǚ với nguyên âm ü — môi tròn như khi nói ''uy'' nhưng giữ yên.', '{"term":"旅游","pinyin":"lǚyóu","part_of_speech":"verb","meaning_vi":"du lịch","example":"我们明年去中国旅游吧！","example_pinyin":"Wǒmen míngnián qù Zhōngguó lǚyóu ba!","example_vi":"Năm sau mình đi du lịch Trung Quốc nhé!"}'::jsonb),
  ('zh-vocab-hsk3-travel-02', 'zh-vocab-hsk3-travel', 2, 'multiple_choice', 'HSK3', 'Use 机场 (jīchǎng) in a travel sentence', '我们明天早上去___坐飞机。', 'Sáng mai chúng mình ra sân bay đi máy bay.', '["机场","公园","商店","地图"]'::jsonb, null, null, null, null, '机场', '["机场"]'::jsonb, '机场 (jīchǎng) means ''airport'' — where you go to take a plane (坐飞机).', '机场 (jīchǎng) là sân bay. Hán-Việt ''cơ trường'' — ''cơ'' trong phi cơ (máy bay), ''trường'' là bãi, sân. Muốn đi máy bay (坐飞机) thì phải ra 机场.', '{"term":"机场","pinyin":"jīchǎng","part_of_speech":"noun","meaning_vi":"sân bay","example":"我开车去机场接你。","example_pinyin":"Wǒ kāichē qù jīchǎng jiē nǐ.","example_vi":"Anh lái xe ra sân bay đón em."}'::jsonb),
  ('zh-vocab-hsk3-travel-03', 'zh-vocab-hsk3-travel', 3, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''passport'': 护照 (hùzhào)', 'Chọn từ có nghĩa là ''hộ chiếu''', null, '["护照","地图","票","照片"]'::jsonb, null, null, null, null, '护照', '["护照"]'::jsonb, '护照 (hùzhào) means ''passport''. 照片 (zhàopiàn) is a photo.', '护照 (hùzhào) là hộ chiếu — Hán-Việt y hệt ''hộ chiếu''! Đừng nhầm với 照片 (zhàopiàn – ảnh chụp), cũng có chữ 照. Cả hai âm tiết của 护照 đều thanh 4.', '{"term":"护照","pinyin":"hùzhào","part_of_speech":"noun","meaning_vi":"hộ chiếu","example":"别忘了带护照！","example_pinyin":"Bié wàngle dài hùzhào!","example_vi":"Đừng quên mang hộ chiếu nhé!"}'::jsonb),
  ('zh-vocab-hsk3-travel-04', 'zh-vocab-hsk3-travel', 4, 'multiple_choice', 'HSK3', 'Recognize the meaning of 地图 (dìtú)', '「地图」nghĩa là gì?', null, '["bản đồ","vé","sân bay","khách sạn"]'::jsonb, null, null, null, null, '地图', '["bản đồ"]'::jsonb, '地图 (dìtú) means ''map''.', '地图 (dìtú) là bản đồ. Hán-Việt ''địa đồ'' — ''địa'' là đất, ''đồ'' là hình vẽ (như đồ họa). Chữ 图 thanh 2, đừng đọc thành thanh 3.', '{"term":"地图","pinyin":"dìtú","part_of_speech":"noun","meaning_vi":"bản đồ","example":"我们看看地图吧。","example_pinyin":"Wǒmen kànkan dìtú ba.","example_vi":"Mình xem bản đồ chút đi."}'::jsonb),
  ('zh-vocab-hsk3-travel-05', 'zh-vocab-hsk3-travel', 5, 'multiple_choice', 'HSK3', 'Use 附近 (fùjìn) to say something is nearby', '我家___有一个公园。', 'Gần nhà tôi có một công viên.', '["附近","城市","旅游","护照"]'::jsonb, null, null, null, null, '附近', '["附近"]'::jsonb, '附近 (fùjìn) means ''nearby, in the vicinity''. It comes after the place: 我家附近, near my home.', '附近 (fùjìn) là gần đây, lân cận. Hán-Việt ''phụ cận''. Khác tiếng Việt, 附近 đứng SAU địa điểm: 我家附近 = gần nhà tôi (nghĩa đen ''nhà tôi – gần đó'').', '{"term":"附近","pinyin":"fùjìn","part_of_speech":"noun","meaning_vi":"gần đây, lân cận","example":"宾馆附近有很多饭馆。","example_pinyin":"Bīnguǎn fùjìn yǒu hěn duō fànguǎn.","example_vi":"Gần khách sạn có rất nhiều quán ăn."}'::jsonb),
  ('zh-vocab-hsk3-travel-06', 'zh-vocab-hsk3-travel', 6, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''city'': 城市 (chéngshì)', 'Chọn từ có nghĩa là ''thành phố''', null, '["城市","国家","地方","公园"]'::jsonb, null, null, null, null, '城市', '["城市"]'::jsonb, '城市 (chéngshì) means ''city''. 国家 (guójiā) is a country and 地方 (dìfang) is a place.', '城市 (chéngshì) là thành phố. Hán-Việt ''thành thị''. Chú ý 城 đọc chéng (thanh 2, âm ''ch'' uốn lưỡi), còn 市 đọc shì (thanh 4). 国家 là quốc gia, 地方 là nơi, chỗ.', '{"term":"城市","pinyin":"chéngshì","part_of_speech":"noun","meaning_vi":"thành phố","example":"这个城市很漂亮。","example_pinyin":"Zhège chéngshì hěn piàoliang.","example_vi":"Thành phố này rất đẹp."}'::jsonb),
  ('zh-vocab-hsk3-travel-07', 'zh-vocab-hsk3-travel', 7, 'multiple_choice', 'HSK3', 'Recognize the meaning of 宾馆 (bīnguǎn)', '「宾馆」nghĩa là gì?', null, '["khách sạn","nhà hàng","ngân hàng","bệnh viện"]'::jsonb, null, null, null, null, '宾馆', '["khách sạn"]'::jsonb, '宾馆 (bīnguǎn) means ''hotel, guesthouse''. Another common word is 酒店 (jiǔdiàn).', '宾馆 (bīnguǎn) là khách sạn, nhà khách. Hán-Việt ''tân quán'' — ''tân'' là khách (như tân khách), ''quán'' là nhà. Ở Trung Quốc người ta cũng hay nói 酒店 (jiǔdiàn), đừng tưởng đó là quán rượu nhé!', '{"term":"宾馆","pinyin":"bīnguǎn","part_of_speech":"noun","meaning_vi":"khách sạn, nhà khách","example":"我们住的宾馆离海很近。","example_pinyin":"Wǒmen zhù de bīnguǎn lí hǎi hěn jìn.","example_vi":"Khách sạn bọn mình ở rất gần biển."}'::jsonb),
  ('zh-vocab-hsk3-travel-08', 'zh-vocab-hsk3-travel', 8, 'multiple_choice', 'HSK3', 'Use 票 (piào) to talk about buying tickets', '我买了两张火车___，下个星期去看你。', 'Anh đã mua hai vé tàu hỏa, tuần sau đi thăm em.', '["票","护照","宾馆","附近"]'::jsonb, null, null, null, null, '票', '["票"]'::jsonb, '票 (piào) means ''ticket''. Tickets are counted with 张: 两张票.', '票 (piào) là vé. Hán-Việt ''phiếu''. Đếm vé dùng lượng từ 张 (zhāng): 两张票 = hai cái vé. 火车票 là vé tàu, 机票 là vé máy bay.', '{"term":"票","pinyin":"piào","part_of_speech":"noun","meaning_vi":"vé","example":"你买票了吗？","example_pinyin":"Nǐ mǎi piào le ma?","example_vi":"Em mua vé chưa?"}'::jsonb),
  ('zh-vocab-hsk3-travel-09', 'zh-vocab-hsk3-travel', 9, 'multiple_choice', 'HSK3', 'Recall the Chinese word for ''park'': 公园 (gōngyuán)', 'Chọn từ có nghĩa là ''công viên''', null, '["公园","公司","花园","机场"]'::jsonb, null, null, null, null, '公园', '["公园"]'::jsonb, '公园 (gōngyuán) means ''park''. 公司 (gōngsī) means ''company''.', '公园 (gōngyuán) là công viên — Hán-Việt y hệt! Cẩn thận với 公司 (gōngsī – công ty): cùng chữ 公 nên rất dễ nhầm. 花园 (huāyuán) là vườn hoa.', '{"term":"公园","pinyin":"gōngyuán","part_of_speech":"noun","meaning_vi":"công viên","example":"我们去公园走走吧。","example_pinyin":"Wǒmen qù gōngyuán zǒuzou ba.","example_vi":"Mình ra công viên đi dạo chút nhé."}'::jsonb),
  ('zh-vocab-hsk3-travel-10', 'zh-vocab-hsk3-travel', 10, 'multiple_choice', 'HSK3', 'Use 离 (lí) to talk about distance', '我家___机场很远。', 'Nhà tôi cách sân bay rất xa.', '["离","和","在","是"]'::jsonb, null, null, null, null, '离', '["离"]'::jsonb, '离 (lí) means ''away from'' and shows distance: A 离 B 很远 means ''A is far from B''.', '离 (lí) là cách (bao xa). Cấu trúc: A + 离 + B + 很远/很近 = A cách B rất xa/rất gần. Hán-Việt ''ly'' (chia ly). Không dùng 在 hay 和 trong cấu trúc này.', '{"term":"离","pinyin":"lí","part_of_speech":"preposition","meaning_vi":"cách (khoảng cách)","example":"你家离这儿远吗？","example_pinyin":"Nǐ jiā lí zhèr yuǎn ma?","example_vi":"Nhà em cách đây có xa không?"}'::jsonb),
  ('zh-grammar-hsk1-01', 'zh-grammar-hsk1-basics', 1, 'multiple_choice', 'HSK1', 'Use 是 to link two nouns', '我___越南人。', 'Em là người Việt Nam.', '["是","很","在","有"]'::jsonb, null, null, null, null, null, '["是"]'::jsonb, '是 (shì) links a subject to a noun: 我是越南人 = I am Vietnamese. 很 goes with adjectives, 在 means ''be at'', 有 means ''have''.', '是 (shì) nối chủ ngữ với một danh từ, giống "là" trong tiếng Việt: 我是越南人 = Em là người Việt Nam. 很 dùng trước tính từ, 在 là "ở", 有 là "có" — không dùng được ở đây.', null),
  ('zh-grammar-hsk1-02', 'zh-grammar-hsk1-basics', 2, 'multiple_choice', 'HSK1', 'Form a yes/no question with 吗', '你是中国人___？', 'Anh là người Trung Quốc à?', '["吗","是","不","很"]'::jsonb, null, null, null, null, null, '["吗"]'::jsonb, 'Add 吗 (ma) to the end of a statement to turn it into a yes/no question. The word order does not change.', 'Chỉ cần thêm 吗 (ma) vào cuối câu trần thuật là thành câu hỏi có/không, giống "…à? / …không?" trong tiếng Việt. Trật tự từ giữ nguyên, không cần đảo động từ lên đầu.', null),
  ('zh-grammar-hsk1-03', 'zh-grammar-hsk1-basics', 3, 'multiple_choice', 'HSK1', 'Do not use 是 before adjectives; put time before the verb', 'Câu nào đúng? (Hôm nay em rất vui.)', 'Hôm nay em rất vui.', '["我今天很高兴。","我是很高兴今天。","我很高兴今天。","我今天高兴是。"]'::jsonb, null, null, null, null, null, '["我今天很高兴。"]'::jsonb, 'Adjectives act as the predicate by themselves, usually with 很: 我很高兴, not 我是很高兴. Time words (今天) go before the verb/adjective, not at the end.', 'Trong tiếng Trung, tính từ tự làm vị ngữ, thường đi với 很: 我很高兴. Người Việt hay dịch "là" thành 是 và nói "我是很高兴" — sai. Ngoài ra, tiếng Việt hay để thời gian ở cuối ("vui hôm nay") nhưng tiếng Trung đặt từ thời gian (今天) TRƯỚC vị ngữ.', null),
  ('zh-grammar-hsk1-04', 'zh-grammar-hsk1-basics', 4, 'multiple_choice', 'HSK1', 'Use 不 for likes and habits', '我___喜欢喝咖啡。', 'Anh không thích uống cà phê.', '["不","没","别","是"]'::jsonb, null, null, null, null, null, '["不"]'::jsonb, '不 (bù) negates habits, wishes and feelings like 喜欢. 没 is for things that did not happen or for 有. 别 means ''don''t!'' in commands.', '不 (bù) dùng để phủ định thói quen, sở thích, ý muốn: 不喜欢 = không thích. 没 dùng cho việc đã không xảy ra hoặc với 有. 别 là "đừng" (câu mệnh lệnh). Tiếng Việt chỉ có một chữ "không" nên người Việt dễ nhầm 不 và 没.', null),
  ('zh-grammar-hsk1-05', 'zh-grammar-hsk1-basics', 5, 'multiple_choice', 'HSK1', 'Negate 有 with 没', '我___有哥哥。', 'Em không có anh trai.', '["没","不","别","很"]'::jsonb, null, null, null, null, null, '["没"]'::jsonb, '有 (yǒu) is always negated with 没: 没有. Never say 不有.', 'Động từ 有 (có) LUÔN phủ định bằng 没: 没有 = không có. Tuyệt đối không nói "不有" — đây là lỗi rất hay gặp vì tiếng Việt nói "không có".', null),
  ('zh-grammar-hsk1-06', 'zh-grammar-hsk1-basics', 6, 'multiple_choice', 'HSK1', 'Use 没 for past events that did not happen', '昨天他___来。', 'Hôm qua anh ấy đã không đến.', '["没","不","别","是"]'::jsonb, null, null, null, null, null, '["没"]'::jsonb, 'For an action that did not happen in the past, use 没 (méi): 昨天他没来. 不 is for habits, the present or the future.', 'Muốn nói một việc đã KHÔNG xảy ra trong quá khứ thì dùng 没 (méi): 昨天他没来 = hôm qua anh ấy không đến. 不 dùng cho hiện tại, tương lai hoặc thói quen (明天他不来 = mai anh ấy không đến). Mẹo: "chưa / đã không" → 没.', null),
  ('zh-grammar-hsk1-07', 'zh-grammar-hsk1-basics', 7, 'multiple_choice', 'HSK1', 'Put time and place before the verb', 'Câu nào đúng? (Tối nay anh ăn cơm ở nhà.)', 'Tối nay anh ăn cơm ở nhà.', '["我今天晚上在家吃饭。","我吃饭在家今天晚上。","我今天晚上吃饭在家。","我在家吃饭今天晚上。"]'::jsonb, null, null, null, null, null, '["我今天晚上在家吃饭。"]'::jsonb, 'Chinese order: Subject + Time + Place + Verb + Object. 我 + 今天晚上 + 在家 + 吃饭.', 'Trật tự chuẩn: Chủ ngữ + Thời gian + Nơi chốn + Động từ + Tân ngữ. Tiếng Việt nói "ăn cơm ở nhà tối nay" (nơi chốn, thời gian đứng SAU động từ), còn tiếng Trung đưa cả hai lên TRƯỚC động từ: 我今天晚上在家吃饭.', null),
  ('zh-grammar-hsk1-08', 'zh-grammar-hsk1-basics', 8, 'multiple_choice', 'HSK1', 'Put the time word before the verb', 'Câu nào đúng? (Ngày mai em đi Bắc Kinh.)', 'Ngày mai em đi Bắc Kinh.', '["我明天去北京。","我去北京明天。","我去明天北京。","去北京我明天。"]'::jsonb, null, null, null, null, null, '["我明天去北京。"]'::jsonb, 'Time words like 明天 go before the verb (after or before the subject), never at the end: 我明天去北京.', 'Từ chỉ thời gian (明天, 今天, 每天…) đứng TRƯỚC động từ — có thể đứng sau hoặc trước chủ ngữ — nhưng không bao giờ đặt cuối câu như tiếng Việt hay tiếng Anh. Nói 我明天去北京, đừng nói "我去北京明天".', null),
  ('zh-grammar-hsk1-09', 'zh-grammar-hsk1-basics', 9, 'multiple_choice', 'HSK1', 'Do not add 吗 to questions with question words', 'Câu nào đúng? (Em tên là gì?)', 'Em tên là gì?', '["你叫什么名字？","你叫什么名字吗？","你是叫什么名字吗？","你名字叫吗什么？"]'::jsonb, null, null, null, null, null, '["你叫什么名字？"]'::jsonb, 'A question with a question word (什么, 谁, 哪儿) is already a question, so do not add 吗.', 'Câu đã có từ để hỏi (什么 = gì, 谁 = ai, 哪儿 = đâu) thì KHÔNG thêm 吗 nữa. 吗 chỉ dùng cho câu hỏi có/không. Từ để hỏi đứng đúng vị trí của thông tin cần hỏi, không đảo lên đầu câu.', null),
  ('zh-grammar-hsk1-10', 'zh-grammar-hsk1-basics', 10, 'multiple_choice', 'HSK1', 'Use 很 (not 是) before adjectives', '她___漂亮。', 'Cô ấy rất xinh.', '["很","是","在","有"]'::jsonb, null, null, null, null, null, '["很"]'::jsonb, 'Adjective predicates take 很 (hěn), not 是: 她很漂亮. 很 is often weak, close to just ''is''.', 'Trước tính từ dùng 很 (hěn), không dùng 是: 她很漂亮. Người Việt hay nói "她是漂亮" vì dịch từng chữ "cô ấy là xinh" — sai. 很 ở đây nhiều khi chỉ mang nghĩa nhẹ, gần như chỉ để câu tự nhiên.', null),
  ('zh-grammar-hsk2-01', 'zh-grammar-hsk2-aspect-compare', 1, 'multiple_choice', 'HSK2', 'Use 了 after a verb for a completed action', '我昨天买___一本书。', 'Hôm qua em đã mua một cuốn sách.', '["了","着","在","的"]'::jsonb, null, null, null, null, null, '["了"]'::jsonb, '了 (le) after a verb shows the action is completed: 买了一本书 = bought a book.', '了 (le) đứng sau động từ để cho biết hành động đã hoàn thành: 买了一本书 = đã mua một cuốn sách. Chú ý: 了 đứng SAU động từ, không đứng trước như chữ "đã" trong tiếng Việt.', null),
  ('zh-grammar-hsk2-02', 'zh-grammar-hsk2-aspect-compare', 2, 'multiple_choice', 'HSK2', 'Use 没 + verb + 过 for ''have never''', '我没去___中国。', 'Anh chưa từng đi Trung Quốc.', '["过","了","着","在"]'::jsonb, null, null, null, null, null, '["过"]'::jsonb, '过 (guo) marks experience: 去过 = have been to. Its negative is 没 + verb + 过. 没 and 了 cannot be used together.', '过 (guo) diễn tả trải nghiệm "đã từng": 去过中国 = đã từng đến Trung Quốc. Phủ định: 没 + động từ + 过 = chưa từng. Lỗi hay gặp: nói "没去了" — 没 và 了 không đi cùng nhau trong câu phủ định.', null),
  ('zh-grammar-hsk2-03', 'zh-grammar-hsk2-aspect-compare', 3, 'multiple_choice', 'HSK2', 'Use 在 + verb + 呢 for actions in progress', '我们___吃饭呢。', 'Bọn anh đang ăn cơm.', '["在","了","过","是"]'::jsonb, null, null, null, null, null, '["在"]'::jsonb, '在 (zài) before a verb means the action is in progress, often with 呢 at the end: 我们在吃饭呢.', '在 (zài) đặt TRƯỚC động từ = "đang": 我们在吃饭呢 = bọn anh đang ăn cơm. 呢 ở cuối câu làm câu tự nhiên hơn. Vị trí giống chữ "đang" của tiếng Việt nên khá dễ nhớ.', null),
  ('zh-grammar-hsk2-04', 'zh-grammar-hsk2-aspect-compare', 4, 'multiple_choice', 'HSK2', 'Use A 比 B + adjective without 很', 'Câu nào đúng? (Anh cao hơn em.)', 'Anh cao hơn em.', '["我比你高。","我比你很高。","我高比你。","我比你是高。"]'::jsonb, null, null, null, null, null, '["我比你高。"]'::jsonb, 'Pattern: A + 比 + B + adjective. Do not put 很 before the adjective in a 比 sentence, and 比 B comes before the adjective.', 'Cấu trúc so sánh: A + 比 + B + tính từ: 我比你高. Tiếng Việt nói "cao hơn em" (tính từ trước), còn tiếng Trung đưa 比你 lên TRƯỚC tính từ. Không dùng 很 (hay 是) trong câu 比: "我比你很高" là sai.', null),
  ('zh-grammar-hsk2-05', 'zh-grammar-hsk2-aspect-compare', 5, 'multiple_choice', 'HSK2', 'Add 一点儿 after the adjective in a 比 sentence', '今天比昨天___。', 'Hôm nay lạnh hơn hôm qua một chút.', '["冷一点儿","很冷","一点儿冷","非常冷"]'::jsonb, null, null, null, null, null, '["冷一点儿"]'::jsonb, 'To say ''a little more'', put 一点儿 after the adjective: 冷一点儿. 很 and 非常 cannot be used in 比 sentences.', 'Muốn nói "hơn một chút" thì đặt 一点儿 SAU tính từ: 比昨天冷一点儿. Không nói "一点儿冷". Các phó từ 很, 非常 không dùng trong câu so sánh với 比.', null),
  ('zh-grammar-hsk2-06', 'zh-grammar-hsk2-aspect-compare', 6, 'multiple_choice', 'HSK2', 'Negate an experience with 没…过', '我___看过这个电影。', 'Em chưa xem bộ phim này bao giờ.', '["没","不","别","很"]'::jsonb, null, null, null, null, null, '["没"]'::jsonb, 'Experiences with 过 are negated with 没: 没看过 = have never seen. 不 cannot go with 过.', 'Câu có 过 phủ định bằng 没: 没看过 = chưa từng xem. Không dùng 不 với 过. Mẹo: nói về quá khứ hoặc trải nghiệm → dùng 没.', null),
  ('zh-grammar-hsk2-07', 'zh-grammar-hsk2-aspect-compare', 7, 'multiple_choice', 'HSK2', 'Drop 了 in negative past sentences', 'Câu nào đúng? (Hôm qua anh ấy không đến.)', 'Hôm qua anh ấy không đến.', '["他昨天没来。","他昨天没来了。","他昨天不来了。","他昨天没有来了。"]'::jsonb, null, null, null, null, null, '["他昨天没来。"]'::jsonb, 'When you negate a completed action with 没/没有, remove 了: 他来了 → 他没来.', 'Câu khẳng định: 他来了 (anh ấy đến rồi). Khi phủ định bằng 没 / 没有 thì PHẢI bỏ 了: 他没来. Người Việt hay giữ 了 vì nghĩ đến chữ "rồi" — "没来了" là sai.', null),
  ('zh-grammar-hsk2-08', 'zh-grammar-hsk2-aspect-compare', 8, 'multiple_choice', 'HSK2', 'Ask whether something has been done with 了吗', '你吃饭___吗？', 'Em ăn cơm chưa?', '["了","过","在","着"]'::jsonb, null, null, null, null, null, '["了"]'::jsonb, '了吗 asks whether an action is done: 你吃饭了吗? 过 must come right after the verb (吃过饭), so 吃饭过 is wrong.', 'Hỏi "đã… chưa?" dùng 了吗: 你吃饭了吗？ = Em ăn cơm chưa? Lưu ý 过 phải đứng ngay sau động từ (吃过饭), nên "吃饭过" là sai. 在 và 着 không đứng ở vị trí này.', null),
  ('zh-grammar-hsk2-09', 'zh-grammar-hsk2-aspect-compare', 9, 'multiple_choice', 'HSK2', 'Place 在 before the verb for progressive actions', 'Câu nào đúng? (Lúc anh gọi, em đang xem tivi.)', 'Lúc anh gọi điện, em đang xem tivi.', '["你打电话的时候，我在看电视。","你打电话的时候，我看电视在。","你打电话的时候，我在看过电视。","你打电话的时候，我看在电视。"]'::jsonb, null, null, null, null, null, '["你打电话的时候，我在看电视。"]'::jsonb, 'Progressive 在 goes directly before the verb: 我在看电视. It cannot follow the verb, and 过 (experience) does not mix with 在 (in progress).', '在 (đang) đứng ngay TRƯỚC động từ: 我在看电视. Không đặt 在 sau động từ hay cuối câu. 过 (đã từng) và 在 (đang) mâu thuẫn nhau nên không dùng chung.', null),
  ('zh-grammar-hsk2-10', 'zh-grammar-hsk2-aspect-compare', 10, 'multiple_choice', 'HSK2', 'Use 更 (not 很) in 比 sentences', '他比我___高。', 'Anh ấy còn cao hơn em nữa.', '["更","很","非常","太"]'::jsonb, null, null, null, null, null, '["更"]'::jsonb, 'In 比 sentences you may add 更 (gèng, even more) or 还 before the adjective, but not 很, 非常 or 太.', 'Trong câu 比 có thể thêm 更 (càng, còn… hơn) trước tính từ: 他比我更高. Nhưng KHÔNG dùng 很, 非常, 太. Người Việt hay nói "比我很高" vì tiếng Việt nói "cao hơn rất nhiều" — muốn nói "hơn nhiều" thì dùng 高多了 / 高得多.', null),
  ('zh-grammar-hsk3-01', 'zh-grammar-hsk3-ba-complements', 1, 'multiple_choice', 'HSK3', 'Use 把 to bring the object before the verb', '请___门关上。', 'Làm ơn đóng cửa lại.', '["把","被","在","比"]'::jsonb, null, null, null, null, null, '["把"]'::jsonb, '把 (bǎ) moves the object before the verb to show what you do to it: 把门关上 = close the door. 被 is passive.', '把 (bǎ) đưa tân ngữ lên TRƯỚC động từ để nhấn mạnh việc xử lý nó: 把门关上 = đóng cửa lại. 被 là câu bị động ("bị"), 在 là "ở/đang", 比 là so sánh — đều không hợp.', null),
  ('zh-grammar-hsk3-02', 'zh-grammar-hsk3-ba-complements', 2, 'multiple_choice', 'HSK3', 'A 把 sentence needs a result after the verb', 'Câu nào đúng? (Em ăn hết bánh kem rồi.)', 'Em ăn hết bánh kem rồi.', '["我把蛋糕吃完了。","我把蛋糕吃。","我把吃完蛋糕了。","我吃完把蛋糕了。"]'::jsonb, null, null, null, null, null, '["我把蛋糕吃完了。"]'::jsonb, 'Pattern: Subject + 把 + object + verb + something extra (result, 了, place…). A bare verb (把蛋糕吃) is incomplete.', 'Cấu trúc: Chủ ngữ + 把 + tân ngữ + động từ + thành phần khác (kết quả, 了…): 我把蛋糕吃完了. Động từ trong câu 把 không được đứng trơ một mình ("我把蛋糕吃" là thiếu). Tân ngữ phải đứng ngay sau 把, trước động từ.', null),
  ('zh-grammar-hsk3-03', 'zh-grammar-hsk3-ba-complements', 3, 'multiple_choice', 'HSK3', 'Place the resultative complement right after the verb', 'Câu nào đúng? (Em nghe hiểu tiếng Trung của anh rồi.)', 'Em nghe hiểu tiếng Trung của anh rồi.', '["我听懂了你的中文。","我懂听了你的中文。","我听了懂你的中文。","我听很懂你的中文。"]'::jsonb, null, null, null, null, null, '["我听懂了你的中文。"]'::jsonb, 'Resultative complement: verb + result (听 + 懂). The two stay together, and 了 comes after the whole unit: 听懂了.', 'Bổ ngữ kết quả: động từ + kết quả (听 nghe + 懂 hiểu = nghe hiểu). Hai chữ này dính liền, 了 đặt SAU cả cụm: 听懂了. Không chen 了 hay 很 vào giữa, không đảo thành 懂听. Tiếng Việt cũng nói "nghe hiểu" nên thứ tự giống nhau.', null),
  ('zh-grammar-hsk3-04', 'zh-grammar-hsk3-ba-complements', 4, 'multiple_choice', 'HSK3', 'Use 完 to show an action is finished', '这本书我看___了，你拿去吧。', 'Cuốn sách này em đọc xong rồi, anh cầm đi.', '["完","是","很","在"]'::jsonb, null, null, null, null, null, '["完"]'::jsonb, '完 (wán) after a verb means ''finished'': 看完了 = finished reading.', '完 (wán) đứng sau động từ = "xong": 看完了 = đọc xong rồi, 吃完 = ăn xong. Giống tiếng Việt "đọc xong" — kết quả đứng ngay sau động từ.', null),
  ('zh-grammar-hsk3-05', 'zh-grammar-hsk3-ba-complements', 5, 'multiple_choice', 'HSK3', 'Use 越来越 + adjective without 很', '天气越来越___了。', 'Thời tiết càng ngày càng lạnh.', '["冷","很冷","非常冷","冷很"]'::jsonb, null, null, null, null, null, '["冷"]'::jsonb, '越来越 (yuè lái yuè) + adjective = ''more and more''. It already shows degree, so no 很 or 非常.', '越来越 + tính từ = "càng ngày càng…". Bản thân 越来越 đã chỉ mức độ nên KHÔNG thêm 很 / 非常: 越来越冷, không nói "越来越很冷". Thường có 了 ở cuối câu để chỉ sự thay đổi.', null),
  ('zh-grammar-hsk3-06', 'zh-grammar-hsk3-ba-complements', 6, 'multiple_choice', 'HSK3', 'Use 越来越 correctly in a full sentence', 'Câu nào đúng? (Tiếng Trung của em càng ngày càng tốt.)', 'Tiếng Trung của em càng ngày càng tốt.', '["我的中文越来越好了。","我的中文越来越很好了。","我的中文越来越好很。","我的中文越好越来了。"]'::jsonb, null, null, null, null, null, '["我的中文越来越好了。"]'::jsonb, '越来越 is a fixed unit placed right before the adjective: 越来越好. Do not split it or add 很.', '越来越 là một cụm cố định, đứng ngay trước tính từ: 越来越好. Không tách ra, không đảo, không thêm 很. Người Việt hay dịch "càng ngày càng rất tốt" — sai.', null),
  ('zh-grammar-hsk3-07', 'zh-grammar-hsk3-ba-complements', 7, 'multiple_choice', 'HSK3', 'Pair 因为 with 所以', '___今天下雨，所以我们不去公园了。', 'Vì hôm nay trời mưa nên tụi mình không đi công viên nữa.', '["因为","虽然","但是","如果"]'::jsonb, null, null, null, null, null, '["因为"]'::jsonb, '因为…所以… = because… so…. Chinese commonly uses both words together.', '因为…所以… = "vì… nên…". Tiếng Trung thường dùng cả cặp, giống tiếng Việt "vì… nên…". 虽然 (tuy) đi với 但是 (nhưng); 如果 (nếu) thường đi với 就, không đi với 所以.', null),
  ('zh-grammar-hsk3-08', 'zh-grammar-hsk3-ba-complements', 8, 'multiple_choice', 'HSK3', 'Pair 虽然 with 但是', '虽然很累，___我很开心。', 'Tuy rất mệt nhưng em rất vui.', '["但是","所以","因为","和"]'::jsonb, null, null, null, null, null, '["但是"]'::jsonb, '虽然…但是… = although… (but)…. Chinese keeps 但是 in the second clause, unlike English.', '虽然…但是… = "tuy… nhưng…", giống hệt tiếng Việt. 和 chỉ nối danh từ (anh 和 em), không dùng để nối hai vế câu — người Việt hay dùng 和 thay cho "và" giữa hai mệnh đề, đó là lỗi.', null),
  ('zh-grammar-hsk3-09', 'zh-grammar-hsk3-ba-complements', 9, 'multiple_choice', 'HSK3', 'Combine 虽然…但是… in a full sentence', 'Câu nào đúng? (Tuy tụi mình không ở cạnh nhau nhưng ngày nào anh cũng nhớ em.)', 'Tuy tụi mình không ở cạnh nhau nhưng ngày nào anh cũng nhớ em.', '["虽然我们不在一起，但是我每天都想你。","虽然我们不在一起，所以我每天都想你。","因为我们不在一起，但是我每天都想你。","虽然我们不在一起，我但是每天都想你。"]'::jsonb, null, null, null, null, null, '["虽然我们不在一起，但是我每天都想你。"]'::jsonb, '虽然 pairs with 但是, 因为 pairs with 所以 — do not mix them. 但是 starts its clause, before the subject.', 'Nhớ đúng cặp: 虽然 → 但是, 因为 → 所以, không trộn lẫn. 但是 đứng ĐẦU vế sau, trước chủ ngữ (但是我…), không chen giữa chủ ngữ và động từ.', null),
  ('zh-grammar-hsk3-10', 'zh-grammar-hsk3-ba-complements', 10, 'multiple_choice', 'HSK3', 'Use 把 + object + verb + 在 + place', 'Câu nào đúng? (Anh để điện thoại trên bàn rồi.)', 'Anh để điện thoại trên bàn rồi.', '["我把手机放在桌子上了。","我放把手机在桌子上了。","我把放手机在桌子上了。","我手机把放在桌子上了。"]'::jsonb, null, null, null, null, null, '["我把手机放在桌子上了。"]'::jsonb, 'Order: Subject + 把 + object + verb + 在 + place. 把 comes before the object, and the object comes before the verb.', 'Trật tự: Chủ ngữ + 把 + tân ngữ + động từ + 在 + nơi chốn: 我把手机放在桌子上了. Tiếng Việt nói "để điện thoại trên bàn" (động từ trước tân ngữ), còn câu 把 thì tân ngữ (手机) phải đứng TRƯỚC động từ (放).', null),
  ('zh-listen-hsk1-01', 'zh-listen-hsk1-daily-life', 1, 'listening', 'HSK1', 'Hear the difference between 四 and 十', 'Bạn nghe thấy câu nào về số táo?', null, '["我有四个苹果。","我有十个苹果。","我有七个苹果。","我有一个苹果。"]'::jsonb, null, '我有四个苹果。', null, null, null, '["我有四个苹果。"]'::jsonb, '四 (sì, four) is a falling 4th tone with an ''s'' sound; 十 (shí, ten) is a rising 2nd tone with a curled ''sh''.', '四 (sì = bốn) đọc thanh 4 (đi xuống, dứt khoát), âm "s" đầu lưỡi thẳng. 十 (shí = mười) đọc thanh 2 (đi lên), âm "sh" uốn lưỡi. Người Việt dễ nghe nhầm vì tiếng Việt không có âm uốn lưỡi — hãy chú ý hướng của thanh điệu.', null),
  ('zh-listen-hsk1-02', 'zh-listen-hsk1-daily-life', 2, 'listening', 'HSK1', 'Tell 买 (buy) from 卖 (sell) by tone', 'Bạn nghe thấy câu nào về cái cốc?', null, '["我想买一个杯子。","我想卖一个杯子。","我想买一个桌子。","我想卖一个桌子。"]'::jsonb, null, '我想买一个杯子。', null, null, null, '["我想买一个杯子。"]'::jsonb, '买 (mǎi, buy) is a low dipping 3rd tone; 卖 (mài, sell) is a sharp falling 4th tone. 杯子 (bēizi) is a cup, 桌子 (zhuōzi) a table.', '买 (mǎi = mua) thanh 3: giọng hạ thấp rồi hơi lên, nghe trầm. 卖 (mài = bán) thanh 4: rơi mạnh từ cao xuống, nghe dứt khoát như thanh nặng/sắc gắt. Câu nghe được dùng thanh 3 → mua. 杯子 = cái cốc, 桌子 = cái bàn.', null),
  ('zh-listen-hsk1-03', 'zh-listen-hsk1-daily-life', 3, 'listening', 'HSK1', 'Catch the destination in a plan', 'Ngày mai người nói sẽ đi đâu?', null, '["Bệnh viện","Trường học","Nhà hàng","Cửa hàng"]'::jsonb, null, '明天我去医院看朋友。', null, null, null, '["Bệnh viện"]'::jsonb, '医院 (yīyuàn) = hospital. The speaker goes to the hospital to visit a friend (看朋友).', '医院 (yīyuàn) = bệnh viện. 看朋友 ở đây nghĩa là "thăm bạn". Đừng nhầm với 学校 (xuéxiào = trường học) hay 饭馆 (fànguǎn = nhà hàng). Chú ý địa điểm luôn đứng ngay sau 去.', null),
  ('zh-listen-hsk1-04', 'zh-listen-hsk1-daily-life', 4, 'listening', 'HSK1', 'Catch a time of day', 'Bây giờ là mấy giờ theo người nói?', null, '["3 giờ chiều","3 giờ sáng","2 giờ chiều","4 giờ chiều"]'::jsonb, null, '现在是下午三点。', null, null, null, '["3 giờ chiều"]'::jsonb, '下午 (xiàwǔ) = afternoon, 三点 (sān diǎn) = three o''clock. 上午 (shàngwǔ) would be morning.', '下午 (xiàwǔ) = buổi chiều, 三点 (sān diǎn) = 3 giờ. Tiếng Trung nói buổi trước rồi mới đến giờ (下午三点 = chiều 3 giờ), ngược với tiếng Việt "3 giờ chiều". 上午 mới là buổi sáng.', null),
  ('zh-listen-hsk1-05', 'zh-listen-hsk1-daily-life', 5, 'listening', 'HSK1', 'Understand likes and dislikes with 喜欢 / 不喜欢', 'Người nói thích uống gì?', null, '["Trà","Cà phê","Nước","Sữa"]'::jsonb, null, '我喜欢喝茶，不喜欢喝咖啡。', null, null, null, '["Trà"]'::jsonb, '喜欢喝茶 = likes drinking tea; 不喜欢喝咖啡 = does not like coffee.', '喜欢喝茶 = thích uống trà; 不喜欢喝咖啡 = không thích uống cà phê. Hãy nghe kỹ chữ 不 (bù) — nó đổi nghĩa cả vế câu. 茶 (chá) thanh 2, 咖啡 (kāfēi) phát âm gần giống "cà phê".', null),
  ('zh-listen-hsk2-01', 'zh-listen-hsk2-plans-together', 1, 'listening', 'HSK2', 'Hear 买 vs 卖 and the adjective in a longer sentence', 'Bạn nghe thấy câu nào về quần áo?', null, '["我昨天买了两件衣服，都很便宜。","我昨天卖了两件衣服，都很便宜。","我昨天买了两件衣服，都很贵。","我昨天卖了两件衣服，都很贵。"]'::jsonb, null, '我昨天买了两件衣服，都很便宜。', null, null, null, '["我昨天买了两件衣服，都很便宜。"]'::jsonb, '买 (mǎi, 3rd tone) = buy; 卖 (mài, 4th tone) = sell. 便宜 (piányi) = cheap, 贵 (guì) = expensive.', 'Hai chỗ cần nghe: 买 (mǎi, thanh 3, trầm) = mua và 卖 (mài, thanh 4, rơi mạnh) = bán; 便宜 (piányi) = rẻ, còn 贵 (guì) = đắt. 两件衣服 = hai bộ quần áo — với số đếm dùng 两, không dùng 二.', null),
  ('zh-listen-hsk2-02', 'zh-listen-hsk2-plans-together', 2, 'listening', 'HSK2', 'Catch the means of transport', 'Họ sẽ đi Bắc Kinh bằng phương tiện gì?', null, '["Máy bay","Tàu hỏa","Xe buýt","Taxi"]'::jsonb, null, '我们坐飞机去北京吧，火车太慢了。', null, null, null, '["Máy bay"]'::jsonb, '坐飞机 (zuò fēijī) = take a plane. 火车太慢了 = the train is too slow, so they will not take it.', '坐飞机 = đi máy bay. Câu sau 火车太慢了 (tàu hỏa chậm quá) là lý do KHÔNG đi tàu — đừng chọn "tàu hỏa" chỉ vì nghe thấy 火车. Phương tiện đứng TRƯỚC động từ 去: 坐飞机去北京.', null),
  ('zh-listen-hsk2-03', 'zh-listen-hsk2-plans-together', 3, 'listening', 'HSK2', 'Hear the difference between 十四, 四 and 十', 'Bạn nghe thấy ngày nào người nói đi Thượng Hải?', null, '["我十四号去上海。","我四号去上海。","我十号去上海。","我十一号去上海。"]'::jsonb, null, '我十四号去上海。', null, null, null, '["我十四号去上海。"]'::jsonb, '十四 (shísì) = fourteen: ten first (rising shí), then four (falling sì). 号 (hào) marks the date.', '十四 (shísì) = 14: nghe "shí" (thanh 2, uốn lưỡi) trước rồi đến "sì" (thanh 4). Số trong tiếng Trung ghép giống tiếng Việt: mười + bốn. 号 (hào) = ngày. Mẹo: nghe đủ hai âm tiết, đừng dừng ở âm đầu.', null),
  ('zh-listen-hsk2-04', 'zh-listen-hsk2-plans-together', 4, 'listening', 'HSK2', 'Understand location words 上 and 下面', 'Điện thoại của người nghe đang ở đâu?', null, '["Trên bàn","Dưới ghế","Trên ghế","Dưới bàn"]'::jsonb, null, '你的手机在桌子上，我的在椅子下面。', null, null, null, '["Trên bàn"]'::jsonb, '你的手机在桌子上 = your phone is on the table. 我的在椅子下面 = mine is under the chair.', '你的手机 (điện thoại của bạn) 在桌子上 = ở trên bàn. Điện thoại của người nói (我的) mới ở 椅子下面 (dưới ghế). Chú ý: tiếng Trung đặt từ chỉ phương hướng SAU danh từ: 桌子上 = trên bàn (bàn + trên).', null),
  ('zh-listen-hsk2-05', 'zh-listen-hsk2-plans-together', 5, 'listening', 'HSK2', 'Understand the reason for cancelling a plan', 'Vì sao tối nay người nói không ăn tối cùng được?', null, '["Phải làm việc đến 10 giờ","Bị ốm","Phải đi học","Đã ăn rồi"]'::jsonb, null, '今天晚上我不能和你吃饭了，我要工作到十点。', null, null, null, '["Phải làm việc đến 10 giờ"]'::jsonb, '我要工作到十点 = I have to work until ten o''clock. 不能…了 = can no longer (a change of plan).', '我要工作到十点 = em phải làm việc đến 10 giờ. 不能…了 nghĩa là "không thể… được nữa" — kế hoạch đã thay đổi. 到 + thời gian = "đến (mấy giờ)".', null),
  ('zh-puzzle-hsk1-01', 'zh-writing-hsk1-sentence-puzzle', 1, 'sentence_order', 'HSK1', 'Build a Subject + 很 + Verb + Object sentence', 'Ghép câu: Anh rất yêu em.', null, null, '["你。","爱","我","很"]'::jsonb, null, 'Subject first; the adverb 很 comes before the verb.', 'Chủ ngữ đứng đầu; phó từ 很 đứng trước động từ.', null, '["我 很 爱 你。"]'::jsonb, 'Subject + Adverb + Verb + Object: 我 + 很 + 爱 + 你 (wǒ hěn ài nǐ).', 'Trật tự: Chủ ngữ + Phó từ + Động từ + Tân ngữ. 很 (rất) luôn đứng TRƯỚC động từ, giống tiếng Việt "rất yêu" — không đặt cuối câu như "yêu em rất nhiều".', null),
  ('zh-puzzle-hsk1-02', 'zh-writing-hsk1-sentence-puzzle', 2, 'sentence_order', 'HSK1', 'Put a time word before the verb', 'Ghép câu: Mỗi ngày anh đều học tiếng Trung.', null, null, '["学习","中文。","我","每天"]'::jsonb, null, 'Time word comes before the verb.', 'Từ chỉ thời gian đứng trước động từ.', null, '["我 每天 学习 中文。","每天 我 学习 中文。"]'::jsonb, '每天 (měitiān, every day) goes before the verb — either right after the subject or at the very start.', 'Từ chỉ thời gian 每天 đứng TRƯỚC động từ: sau chủ ngữ (我每天…) hoặc đầu câu (每天我…). Không đặt cuối câu như tiếng Việt "học tiếng Trung mỗi ngày".', null),
  ('zh-puzzle-hsk1-03', 'zh-writing-hsk1-sentence-puzzle', 3, 'sentence_order', 'HSK1', 'Ask ''which country'' with 哪国', 'Ghép câu: Bạn là người nước nào?', null, null, '["人？","哪","你","是","国"]'::jsonb, null, 'The question word stays where the answer would be: 你是 + 哪国人?', 'Từ để hỏi đứng đúng chỗ của câu trả lời: 你是 + 哪国人?', null, '["你 是 哪 国 人？"]'::jsonb, 'Answer: 我是越南人. Question: replace 越南 with 哪国 — no word order change, no 吗.', 'Câu trả lời là 我是越南人, nên câu hỏi chỉ cần thay 越南 bằng 哪国 (nước nào). Không đảo trật tự, không thêm 吗 vì đã có từ để hỏi.', null),
  ('zh-puzzle-hsk1-04', 'zh-writing-hsk1-sentence-puzzle', 4, 'sentence_order', 'HSK1', 'Order subject, time, 一起 and verb', 'Ghép câu: Ngày mai tụi mình cùng đi xem phim.', null, null, '["一起","电影。","明天","看","我们","去"]'::jsonb, null, 'Time (明天) before 一起, and 一起 before the verbs 去看.', 'Thời gian (明天) đứng trước 一起, 一起 đứng trước động từ 去看.', null, '["我们 明天 一起 去 看 电影。","明天 我们 一起 去 看 电影。"]'::jsonb, 'Subject + Time + 一起 + 去 + Verb + Object. 一起 (together) comes before the verb, not after it.', 'Chủ ngữ + Thời gian + 一起 + 去 + Động từ + Tân ngữ. 一起 (cùng nhau) đứng TRƯỚC động từ. 去看电影 = đi xem phim — động từ 去 đứng trước động từ chỉ mục đích, giống tiếng Việt.', null),
  ('zh-puzzle-hsk1-05', 'zh-writing-hsk1-sentence-puzzle', 5, 'sentence_order', 'HSK1', 'Put the place phrase 在 + place before the verb', 'Ghép câu: Em đợi anh ở nhà.', null, null, '["等","家","你。","我","在"]'::jsonb, null, 'Place phrase (在家) comes before the verb.', 'Cụm nơi chốn (在家) đứng trước động từ.', null, '["我 在 家 等 你。"]'::jsonb, 'Subject + 在 + place + Verb + Object: 我在家等你 (wǒ zài jiā děng nǐ).', 'Tiếng Việt nói "đợi anh ở nhà", nhưng tiếng Trung đưa nơi chốn lên TRƯỚC động từ: 我在家等你. Đây là lỗi trật tự phổ biến nhất của người Việt.', null),
  ('zh-puzzle-hsk1-06', 'zh-writing-hsk1-sentence-puzzle', 6, 'sentence_order', 'HSK1', 'Make a yes/no question with 吗', 'Ghép câu: Anh có thích uống trà không?', null, null, '["喝","吗？","你","茶","喜欢"]'::jsonb, null, 'Make a normal statement, then add 吗 at the end.', 'Xếp thành câu bình thường rồi thêm 吗 ở cuối.', null, '["你 喜欢 喝 茶 吗？"]'::jsonb, 'Statement 你喜欢喝茶 + 吗 = yes/no question. 喜欢 + verb + object: 喜欢喝茶.', 'Câu trần thuật 你喜欢喝茶 + 吗 ở cuối = câu hỏi có/không. 喜欢 đứng trước cụm động từ 喝茶 (thích uống trà), giống tiếng Việt.', null),
  ('zh-puzzle-hsk1-07', 'zh-writing-hsk1-sentence-puzzle', 7, 'sentence_order', 'HSK1', 'Put 不 before the verb', 'Ghép câu: Em không uống cà phê.', null, null, '["咖啡。","不","我","喝"]'::jsonb, null, '不 goes directly before the verb.', '不 đứng ngay trước động từ.', null, '["我 不 喝 咖啡。"]'::jsonb, '不 (bù) negates habits and goes right before the verb: 不喝.', '不 phủ định thói quen, sở thích và đứng ngay TRƯỚC động từ: 我不喝咖啡 = em không uống cà phê (thói quen).', null),
  ('zh-puzzle-hsk1-08', 'zh-writing-hsk1-sentence-puzzle', 8, 'sentence_order', 'HSK1', 'Use 的 to show possession', 'Ghép câu: Đây là bạn trai của em.', null, null, '["的","是","男朋友。","这","我"]'::jsonb, null, 'Owner + 的 + thing: 我的男朋友.', 'Người sở hữu + 的 + vật/người: 我的男朋友.', null, '["这 是 我 的 男朋友。"]'::jsonb, 'Possession: owner + 的 + noun. The owner comes first, the opposite of Vietnamese ''bạn trai của em''.', 'Sở hữu: Người sở hữu + 的 + danh từ: 我的男朋友 (của em + bạn trai). Ngược với tiếng Việt "bạn trai của em" — người Việt hay đặt nhầm thành "男朋友的我".', null),
  ('zh-puzzle-hsk1-09', 'zh-writing-hsk1-sentence-puzzle', 9, 'sentence_order', 'HSK1', 'Ask ''where'' with 在哪儿', 'Ghép câu: Bây giờ anh đang ở đâu?', null, null, '["在","哪儿？","现在","你"]'::jsonb, null, 'Time word before 在; 哪儿 goes where the place would be.', 'Từ thời gian đứng trước 在; 哪儿 đứng ở vị trí của nơi chốn.', null, '["你 现在 在 哪儿？","现在 你 在 哪儿？"]'::jsonb, '你现在在哪儿? (nǐ xiànzài zài nǎr). 现在 can go before or after the subject, but always before 在.', '现在 (bây giờ) có thể đứng trước hoặc sau chủ ngữ nhưng luôn TRƯỚC động từ 在. 哪儿 (đâu) đứng ở cuối, đúng chỗ của địa điểm trong câu trả lời (我在家).', null),
  ('zh-puzzle-hsk1-10', 'zh-writing-hsk1-sentence-puzzle', 10, 'sentence_order', 'HSK1', 'Combine a time word with 很 + verb', 'Ghép câu: Hôm nay em rất nhớ anh.', null, null, '["想","今天","你。","很","我"]'::jsonb, null, 'Time word first or after the subject, then 很 + verb.', 'Từ thời gian ở đầu câu hoặc sau chủ ngữ, rồi đến 很 + động từ.', null, '["我 今天 很 想 你。","今天 我 很 想 你。"]'::jsonb, '想 (xiǎng) here means ''to miss''. 今天 goes before 很想, never at the end.', '想 ở đây nghĩa là "nhớ". 今天 đứng trước 很想 — không nói "我很想你今天". Phó từ 很 luôn đứng sát trước động từ.', null),
  ('zh-puzzle-hsk2-01', 'zh-writing-hsk2-sentence-puzzle', 1, 'sentence_order', 'HSK2', 'Use 已经…了 for a completed action', 'Ghép câu: Anh ăn cơm rồi.', null, null, '["了。","吃饭","已经","我"]'::jsonb, null, '已经 before the verb, 了 at the end.', '已经 đứng trước động từ, 了 ở cuối câu.', null, '["我 已经 吃饭 了。"]'::jsonb, '已经 (yǐjīng, already) + verb + 了: 我已经吃饭了.', '已经 (đã) đứng TRƯỚC động từ, 了 (rồi) đứng cuối câu: 我已经吃饭了 = anh ăn cơm rồi. Giống "đã… rồi" của tiếng Việt.', null),
  ('zh-puzzle-hsk2-02', 'zh-writing-hsk2-sentence-puzzle', 2, 'sentence_order', 'HSK2', 'Ask about experience with 过…吗', 'Ghép câu: Em đã từng đến Trung Quốc chưa?', null, null, '["中国","过","你","吗？","去"]'::jsonb, null, '过 comes right after the verb, before the place.', '过 đứng ngay sau động từ, trước địa điểm.', null, '["你 去 过 中国 吗？"]'::jsonb, 'Verb + 过 + object: 去过中国. Add 吗 to ask.', '过 (đã từng) đứng ngay SAU động từ, trước tân ngữ: 去过中国. Người Việt hay đặt 过 trước động từ như chữ "từng" — sai.', null),
  ('zh-puzzle-hsk2-03', 'zh-writing-hsk2-sentence-puzzle', 3, 'sentence_order', 'HSK2', 'Use 在 + verb + 呢 for an action in progress', 'Ghép câu: Mẹ đang nấu cơm.', null, null, '["做饭","呢。","妈妈","在"]'::jsonb, null, '在 goes before the verb; 呢 ends the sentence.', '在 đứng trước động từ; 呢 ở cuối câu.', null, '["妈妈 在 做饭 呢。"]'::jsonb, '在 + verb (+ 呢) = action in progress: 妈妈在做饭呢.', '在 (đang) đứng TRƯỚC động từ, 呢 ở cuối câu làm câu tự nhiên: 妈妈在做饭呢 = mẹ đang nấu cơm.', null),
  ('zh-puzzle-hsk2-04', 'zh-writing-hsk2-sentence-puzzle', 4, 'sentence_order', 'HSK2', 'Build A 比 B + adjective + amount', 'Ghép câu: Anh lớn hơn em ba tuổi.', null, null, '["大","岁。","我","三","你","比"]'::jsonb, null, 'A 比 B + adjective + the difference.', 'A 比 B + tính từ + mức chênh lệch.', null, '["我 比 你 大 三 岁。"]'::jsonb, 'A + 比 + B + adjective + difference: 我比你大三岁 (I''m three years older than you).', 'Cấu trúc: A + 比 + B + tính từ + mức chênh lệch: 我比你大三岁. Tiếng Việt nói "lớn hơn em ba tuổi" (tính từ trước), còn tiếng Trung đưa 比你 lên TRƯỚC tính từ; số lượng chênh lệch đứng cuối.', null),
  ('zh-puzzle-hsk2-05', 'zh-writing-hsk2-sentence-puzzle', 5, 'sentence_order', 'HSK2', 'Use verb + 了 + number + measure word', 'Ghép câu: Hôm qua em mua một bộ quần áo.', null, null, '["一件","我","衣服。","买了","昨天"]'::jsonb, null, 'Time before the verb; 了 right after the verb, then number + measure word + noun.', 'Thời gian trước động từ; 了 ngay sau động từ, rồi số + lượng từ + danh từ.', null, '["我 昨天 买了 一件 衣服。","昨天 我 买了 一件 衣服。"]'::jsonb, 'Verb + 了 + quantified object: 买了一件衣服. 件 is the measure word for clothes.', 'Khi tân ngữ có số lượng, 了 đứng ngay sau động từ: 买了一件衣服. 件 là lượng từ cho quần áo. 昨天 đứng trước động từ (đầu câu hoặc sau chủ ngữ).', null),
  ('zh-puzzle-hsk2-06', 'zh-writing-hsk2-sentence-puzzle', 6, 'sentence_order', 'HSK2', 'Use 是…的 to stress when something happened', 'Ghép câu: Tụi mình quen nhau vào năm ngoái.', null, null, '["认识","去年","的。","是","我们"]'::jsonb, null, '是 + the detail you stress (time) + verb + 的.', '是 + thông tin muốn nhấn mạnh (thời gian) + động từ + 的.', null, '["我们 是 去年 认识 的。"]'::jsonb, '是…的 highlights the time, place or way of a past event: 我们是去年认识的.', 'Cấu trúc 是…的 nhấn mạnh thời gian / địa điểm / cách thức của việc ĐÃ xảy ra: 我们是去年认识的 = tụi mình quen nhau (là) vào năm ngoái. 是 đứng trước thông tin được nhấn mạnh, 的 ở cuối.', null),
  ('zh-puzzle-hsk2-07', 'zh-writing-hsk2-sentence-puzzle', 7, 'sentence_order', 'HSK2', 'Ask ''why'' with 为什么', 'Ghép câu: Sao em không vui?', null, null, '["不","高兴？","为什么","你"]'::jsonb, null, '为什么 goes before the verb/adjective, after or before the subject.', '为什么 đứng trước động từ/tính từ, sau hoặc trước chủ ngữ.', null, '["你 为什么 不 高兴？","为什么 你 不 高兴？"]'::jsonb, '为什么 (wèishénme) sits before the predicate: 你为什么不高兴? It can also start the sentence.', '为什么 (tại sao) đứng TRƯỚC vị ngữ: 你为什么不高兴？ hoặc đầu câu 为什么你不高兴？. Không thêm 吗 vì đã có từ để hỏi. Nhớ: 不高兴, không phải "不是高兴".', null),
  ('zh-puzzle-hsk2-08', 'zh-writing-hsk2-sentence-puzzle', 8, 'sentence_order', 'HSK2', 'Order 每天, 都 and 给 + person before the verb', 'Ghép câu: Ngày nào anh cũng gọi điện cho em.', null, null, '["给","都","打电话。","每天","我","你"]'::jsonb, null, 'Time + 都 + 给 + person + verb.', 'Thời gian + 都 + 给 + người nhận + động từ.', null, '["我 每天 都 给 你 打电话。","每天 我 都 给 你 打电话。"]'::jsonb, '给 + person comes before the verb: 给你打电话 (call you). 都 follows 每天 and precedes 给.', 'Tiếng Việt nói "gọi điện cho em", nhưng tiếng Trung đưa 给你 (cho em) lên TRƯỚC động từ: 给你打电话. 都 đi sau 每天 và đứng trước cụm 给你 (每天都… = ngày nào cũng…).', null),
  ('zh-puzzle-hsk2-09', 'zh-writing-hsk2-sentence-puzzle', 9, 'sentence_order', 'HSK2', 'Use a degree complement with 得', 'Ghép câu: Anh ấy chạy rất nhanh.', null, null, '["很","跑","快。","他","得"]'::jsonb, null, 'Verb + 得 + 很 + adjective.', 'Động từ + 得 + 很 + tính từ.', null, '["他 跑 得 很 快。"]'::jsonb, 'Degree complement: verb + 得 + (很) + adjective describes how well/fast an action is done.', 'Bổ ngữ trình độ: Động từ + 得 + 很 + tính từ, dùng để đánh giá hành động: 他跑得很快 = anh ấy chạy rất nhanh. Thứ tự giống tiếng Việt "chạy… nhanh", chỉ cần nhớ chèn 得 vào giữa.', null),
  ('zh-puzzle-hsk2-10', 'zh-writing-hsk2-sentence-puzzle', 10, 'sentence_order', 'HSK2', 'Make a suggestion with 吧', 'Ghép câu: Tụi mình cùng đi du lịch đi!', null, null, '["旅游","吧！","一起","我们","去"]'::jsonb, null, '一起 before the verb; 吧 at the end for a suggestion.', '一起 trước động từ; 吧 ở cuối câu để rủ rê, đề nghị.', null, '["我们 一起 去 旅游 吧！"]'::jsonb, '吧 (ba) at the end turns a statement into a suggestion: 我们一起去旅游吧!', '吧 ở cuối câu biến câu thành lời rủ rê, đề nghị ("…đi!", "…nhé!"). 一起 (cùng nhau) đứng trước động từ 去旅游.', null)
insert into public.daily_love_questions (id, prompt, prompt_vi, helper_phrase, sort_order) values
  ('love-001', 'What made you smile today?', 'Hôm nay điều gì đã làm bạn mỉm cười?', 'Today I smiled when…', 0),
  ('love-002', 'What is your favorite memory of us?', 'Kỷ niệm nào của hai đứa mình mà bạn thích nhất?', 'My favorite memory of us is when…', 1),
  ('love-003', 'Where should we travel together?', 'Mình nên cùng nhau đi du lịch ở đâu?', 'I think we should go to… because…', 2),
  ('love-004', 'What is something you appreciate about me?', 'Có điều gì ở mình mà bạn trân trọng?', 'I really appreciate that you…', 3),
  ('love-005', 'What was the best part of your day?', 'Phần vui nhất trong ngày hôm nay của bạn là gì?', 'The best part of my day was…', 4),
  ('love-006', 'What song reminds you of me?', 'Bài hát nào làm bạn nhớ đến mình?', 'The song … reminds me of you because…', 5),
  ('love-007', 'What is the first thing you want to do when we meet again?', 'Khi gặp lại nhau, điều đầu tiên bạn muốn làm là gì?', 'When we meet again, I want to…', 6),
  ('love-008', 'What food would you like to cook for me one day?', 'Một ngày nào đó, bạn muốn nấu món gì cho mình ăn?', 'One day I want to cook… for you.', 7),
  ('love-009', 'What was your first impression of me?', 'Ấn tượng đầu tiên của bạn về mình là gì?', 'When I first met you, I thought…', 8),
  ('love-010', 'What is one small thing that makes you feel loved?', 'Một điều nhỏ nhặt nào khiến bạn cảm thấy được yêu thương?', 'I feel loved when you…', 9),
  ('love-011', 'If we could spend one perfect day together, what would we do?', 'Nếu được ở bên nhau trọn một ngày hoàn hảo, mình sẽ làm gì?', 'On our perfect day, we would…', 10),
  ('love-012', 'What are you looking forward to this week?', 'Tuần này bạn đang mong chờ điều gì?', 'This week I''m looking forward to…', 11),
  ('love-013', 'What is something new you learned recently?', 'Gần đây bạn đã học được điều gì mới?', 'Recently I learned that…', 12),
  ('love-014', 'Which movie should we watch together next?', 'Lần tới mình nên cùng xem phim gì?', 'Let''s watch… because…', 13),
  ('love-015', 'What is a dream you have for the future?', 'Bạn có ước mơ gì cho tương lai?', 'One of my dreams is to…', 14),
  ('love-016', 'What do you miss most about being together in person?', 'Bạn nhớ điều gì nhất khi được ở cạnh nhau?', 'I miss … the most.', 15),
  ('love-017', 'What is your favorite way to relax after a long day?', 'Sau một ngày dài, bạn thích thư giãn bằng cách nào nhất?', 'After a long day, I like to…', 16),
  ('love-018', 'What is something that always cheers you up?', 'Điều gì luôn làm bạn vui lên?', 'I always feel better when…', 17),
  ('love-019', 'What place in your city would you like to show me?', 'Bạn muốn dẫn mình đến chỗ nào trong thành phố của bạn?', 'I want to show you… because…', 18),
  ('love-020', 'What is one thing you are proud of this month?', 'Tháng này bạn tự hào về điều gì?', 'This month I''m proud that I…', 19),
  ('love-021', 'What is a funny moment we shared?', 'Khoảnh khắc nào của hai đứa mình làm bạn thấy buồn cười nhất?', 'I still laugh when I remember…', 20),
  ('love-022', 'What new hobby would you like to try together?', 'Bạn muốn cùng mình thử sở thích mới nào?', 'I''d love to try… with you.', 21),
  ('love-023', 'What three words describe us as a couple?', 'Ba từ nào miêu tả hai đứa mình?', 'I think we are…, …, and…', 22),
